#[tokio::test]
async fn namespace_coordinates_without_original_variable_symbols_do_not_start_workspace_edits() {
    let backend = test_backend();
    let uri = Uri::from_str("file:///conditional-variable-coordinate.tcl").unwrap();
    let source = "namespace eval ::N {set value 1}";
    backend.documents.lock("test").await.insert(
        uri.clone(),
        DocumentState::new(source.to_owned(), "tcl".to_owned()),
    );
    let mut analysis = Analyser::new().analyse(source, "tcl");
    assert!(analysis.allows_lexical_declaration_advice());
    analysis.original_variable_symbols.clear();
    analysis.qualified_var_refs.clear();
    let offset = u32::try_from(source.find("value").unwrap()).unwrap();
    let position = tcl_lexer::LineIndex::new(source).position_at_utf16(offset, source);
    let position = Position::new(position.line, position.character.get());
    assert!(matches!(
        tcl_lsp_core::variable_symbol::select(source, &analysis, position.line, position.character),
        std::ops::ControlFlow::Continue(())
    ));
    assert_eq!(
        core_definition::qualified_variable_cell_at(
            source,
            analysis.resolved_profile().unwrap(),
            &analysis,
            position.line,
            position.character
        )
        .as_deref(),
        Some("::N::value")
    );
    let doc = backend.read_document(&uri).await.unwrap().unwrap();
    assert!(
        backend
            .gated_rename_tiers(&uri, &doc, &analysis, position, "changed")
            .await
            .unwrap()
            .is_none()
    );
}

use tower_lsp_server::ls_types::{
    Diagnostic, NumberOrString, PartialResultParams, Range, ReferenceContext,
    TextDocumentIdentifier, WorkDoneProgressParams,
};

fn w123_command_name(diagnostic: &Diagnostic) -> Option<&str> {
    let data = diagnostic.data.as_ref()?;
    let subject =
        tcl_lsp_core::diagnostic_subject::DiagnosticSubjectData::from_value(data, "W123")?;
    subject.command_reporting_name()?;
    data.get("subject")?.get("reportingName")?.as_str()
}

fn w123_math_function_name(diagnostic: &Diagnostic) -> Option<&str> {
    let data = diagnostic.data.as_ref()?;
    let subject =
        tcl_lsp_core::diagnostic_subject::DiagnosticSubjectData::from_value(data, "W123")?;
    subject.math_function_reporting_name()?;
    data.get("subject")?.get("reportingName")?.as_str()
}

/// `bounded_client_request` must turn a request that never resolves into
/// an error once its deadline passes — the load-bearing half of issue
/// #2021's fix: a server-to-client reply that will never arrive must not
/// keep a handler future (and with it, per `Server::serve`'s contract,
/// the whole process) alive forever. Goes through the parameterised inner
/// helper with a short deadline so the test does not have to wait out the
/// production 10s to prove it.
#[tokio::test]
async fn bounded_client_request_errors_once_its_deadline_elapses() {
    let never: std::future::Pending<jsonrpc::Result<()>> = std::future::pending();
    let started = std::time::Instant::now();
    let result =
        bounded_client_request_with_timeout(std::time::Duration::from_millis(20), never).await;
    assert!(
        result.is_err(),
        "a request that never resolves must time out as an error, not hang forever"
    );
    assert!(
        started.elapsed() < std::time::Duration::from_secs(5),
        "the timeout must actually bound the wait: took {:?}",
        started.elapsed()
    );
}

/// A typing burst must reset the diagnostics debounce window on every edit.
/// A delay fixed from the burst's first edit launches fresh salsa reads
/// throughout it, so `set_text` repeatedly waits for their cancellation and
/// the request-side edit barrier can exceed its budget.
#[tokio::test(start_paused = true)]
async fn diagnostics_debounce_waits_for_a_quiet_window() {
    let uri = Uri::from_str("file:///debounce.tcl").unwrap();
    let slots = Arc::new(Mutex::new(HashMap::new()));
    {
        let mut guard = slots.lock().await;
        let slot = guard.entry(uri.clone()).or_insert_with(DiagSlot::default);
        slot.mark_dirty();
    }

    let waiter = crate::rt::spawn({
        let slots = Arc::clone(&slots);
        let uri = uri.clone();
        async move { stable_diagnostics_generation(&slots, &uri).await }
    });

    // Virtual time makes the producer cadence exact. With wall-clock
    // sleeps a loaded suite can delay this task past the 50 ms deadline,
    // correctly letting the waiter settle before the next nominal 30 ms
    // edit and making the test report a false early-return failure.
    crate::rt::yield_now().await;
    for _ in 0..2 {
        tokio::time::advance(std::time::Duration::from_millis(30)).await;
        slots.lock().await.get_mut(&uri).unwrap().mark_dirty();
    }

    tokio::time::advance(std::time::Duration::from_millis(49)).await;
    crate::rt::yield_now().await;
    assert!(
        !waiter.is_finished(),
        "the waiter resolved before a full quiet debounce window elapsed"
    );
    tokio::time::advance(DIAGNOSTICS_DEBOUNCE * 2).await;
    let generation = waiter.await.expect("debounce waiter task panicked");
    assert_eq!(generation, Some(3));
}

/// A clean slot must be retired before the debounce waiter yields.  A
/// subsequent edit then sees no active worker claim and can start one;
/// retiring only after the waiter returned left a gap where that edit set
/// `dirty` behind the still-running worker and no future worker was spawned.
#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
async fn diagnostics_clean_slot_retires_before_waiter_returns() {
    let uri = Uri::from_str("file:///retire-clean-slot.tcl").unwrap();
    let slots = Arc::new(Mutex::new(HashMap::new()));
    slots.lock().await.insert(
        uri.clone(),
        DiagSlot {
            running: true,
            ..DiagSlot::default()
        },
    );

    assert_eq!(stable_diagnostics_generation(&slots, &uri).await, None);

    // This mirrors `schedule_diagnostics_impl`'s worker-start decision for
    // an edit arriving immediately after the clean observation.
    let starts_worker = {
        let mut guard = slots.lock().await;
        let slot = guard.entry(uri).or_insert_with(DiagSlot::default);
        slot.mark_dirty();
        if slot.running {
            false
        } else {
            slot.running = true;
            true
        }
    };
    assert!(
        starts_worker,
        "an edit after clean-slot retirement must start a diagnostics worker"
    );
}

/// A throwaway directory under the system temp dir, removed on drop.
struct TmpWs(PathBuf);
impl TmpWs {
    fn new(tag: &str) -> Self {
        use std::sync::atomic::{AtomicUsize, Ordering};
        static C: AtomicUsize = AtomicUsize::new(0);
        loop {
            let n = C.fetch_add(1, Ordering::Relaxed);
            let p =
                std::env::temp_dir().join(format!("tcl-lsp-w120-{tag}-{}-{n}", std::process::id()));
            match std::fs::create_dir(&p) {
                Ok(()) => return Self(p),
                Err(error) if error.kind() == std::io::ErrorKind::AlreadyExists => {}
                Err(error) => panic!("creating owned test directory {}: {error}", p.display()),
            }
        }
    }
    fn write(&self, rel: &str, content: &str) {
        let path = self.0.join(rel);
        std::fs::create_dir_all(path.parent().unwrap()).unwrap();
        std::fs::write(path, content).unwrap();
    }
}
impl Drop for TmpWs {
    fn drop(&mut self) {
        let _ = std::fs::remove_dir_all(&self.0);
    }
}

fn w120_diag(pkg: &str) -> tcl_compiler::analyser::Diagnostic {
    use tcl_compiler::analyser::types::{CodeFix, Severity};
    tcl_compiler::analyser::Diagnostic {
        subject: Some(tcl_compiler::analyser::DiagnosticSubject::RequiredPackage(
            tcl_registry::native_package::NativePackageNameKey::from_native_units(
                pkg.as_bytes(),
                tcl_syntax::naming::NamePolicyProtocol::authored_tcl(tcl_dialect::TclVersion::V8_6),
            ),
        )),
        code: DiagCode::W120,
        span: tcl_lexer::Span::new(0, 1),
        message: format!("\"cmd\" requires `package require {pkg}`"),
        severity: Severity::Warning,
        fixes: vec![CodeFix {
            span: tcl_lexer::Span::new(0, 0),
            new_text: format!("package require {pkg}\n"),
            description: format!("Add 'package require {pkg}'"),
            safety: tcl_compiler::analyser::FixSafety::BehaviourHardening,
        }],
    }
}

fn has_w120(diags: &[tcl_compiler::analyser::Diagnostic]) -> bool {
    diags.iter().any(|d| d.code == DiagCode::W120)
}

#[tokio::test]
async fn original_declaration_inventory_excludes_foreign_buffers_and_keeps_unknown_tcl_terminal() {
    // Implementation contract: naming.editor.original-declaration-document-participation
    // docs/design/analysis/name-resolution-proofs/original-declaration-document-participation.md
    let backend = test_backend();
    let base = Uri::from_str("file:///mixed-base.tcl").unwrap();
    let child = Uri::from_str("file:///mixed-child.tcl").unwrap();
    let javascript = Uri::from_str("file:///mixed.js").unwrap();
    let config = Uri::from_str("file:///bigip.conf").unwrap();
    let apl = Uri::from_str("file:///presentation.apl").unwrap();
    let source = r"oo::class create B\uD800 {method m\uD800 {} {}}";
    register(&backend, &base, source).await;
    register(
        &backend,
        &child,
        r"oo::class create Child {superclass B\uD800; method m\uD800 {} {}}",
    )
    .await;
    {
        let mut documents = backend.documents.lock("test mixed participants").await;
        // Counterfactual Tcl-looking text in a JavaScript buffer cannot
        // create a second declaration provider for the same class.
        documents.insert(
            javascript.clone(),
            DocumentState::new(source.to_owned(), "unknown-js".to_owned())
                .with_language_id("javascript".to_owned()),
        );
        documents.insert(
            config.clone(),
            DocumentState::new("ltm virtual example {}".to_owned(), "f5-bigip".to_owned())
                .with_language_id("f5-bigip".to_owned()),
        );
        documents.insert(
            apl.clone(),
            DocumentState::new("section test {}".to_owned(), "f5-iapps".to_owned())
                .with_language_id("apl".to_owned()),
        );
    }
    let documents = backend.original_declaration_documents(&base).await.unwrap();
    assert_eq!(documents.len(), 2);
    assert!(
        documents
            .iter()
            .all(|(uri, _, _)| uri == base.as_str() || uri == child.as_str())
    );
    let params = serde_json::from_value(serde_json::json!({
            "textDocument": {"uri": base.as_str()}, "position": {"line": 0, "character": source.find(r"m\uD800").unwrap()}
        })).unwrap();
    let Some(GotoImplementationResponse::Array(targets)) =
        Box::pin(backend.goto_implementation(params)).await.unwrap()
    else {
        panic!("foreign buffers must not disable exact Tcl implementation advice");
    };
    assert_eq!(targets.len(), 2);
    assert!(targets.iter().any(|location| location.uri == base));
    assert!(targets.iter().any(|location| location.uri == child));
    let unknown = Uri::from_str("file:///unknown-provider.tcl").unwrap();
    backend
        .documents
        .lock("test relevant unknown")
        .await
        .insert(
            unknown,
            DocumentState::new(source.to_owned(), "unknown-tcl-policy".to_owned())
                .with_language_id("tcl".to_owned()),
        );
    assert_eq!(
        backend.original_declaration_documents(&base).await.unwrap(),
        [] as [(
            std::string::String,
            std::sync::Arc<str>,
            std::sync::Arc<tcl_compiler::analyser::AnalysisResult>
        ); 0]
    );
    for dialect in ["tcl8.6", "tcl9.1", "jimtcl", "f5-irules"] {
        let document = DocumentState::new(source.to_owned(), dialect.to_owned())
            .with_language_id("tcl".to_owned());
        assert_eq!(
            Backend::original_declaration_document_participates(&base, &document),
            Some(true),
            "{dialect}"
        );
    }
}

#[tokio::test]
async fn original_implementation_queries_keep_workspace_method_and_class_owners() {
    // Implementation contract: naming.consumer.original-type-and-implementation-navigation
    // docs/design/analysis/name-resolution-proofs/original-type-and-implementation-navigation.md
    let backend = test_backend();
    let base = Uri::from_str("file:///original-implementation-base.tcl").unwrap();
    let child = Uri::from_str("file:///original-implementation-child.tcl").unwrap();
    let other = Uri::from_str("file:///original-implementation-other.tcl").unwrap();
    let base_source = r"oo::class create B\uD800 {method m\uD800 {} {}}";
    register(&backend, &base, base_source).await;
    register(
        &backend,
        &child,
        r"oo::class create Child {superclass B\uD800; method m\uD800 {} {}}",
    )
    .await;
    register(
        &backend,
        &other,
        r"oo::class create Other {method m\uD800 {} {}}",
    )
    .await;
    let params = serde_json::from_value(serde_json::json!({
        "textDocument": {"uri": base.as_str()}, "position": {"line": 0, "character": 18}
    }))
    .unwrap();
    let Some(GotoImplementationResponse::Array(classes)) =
        Box::pin(backend.goto_implementation(params)).await.unwrap()
    else {
        panic!("the exact class declaration should have a workspace subtype");
    };
    assert_eq!(classes.len(), 1);
    assert_eq!(classes[0].uri, child);
    let params = serde_json::from_value(serde_json::json!({
            "textDocument": {"uri": base.as_str()}, "position": {"line": 0, "character": base_source.find(r"m\uD800").unwrap()}
        })).unwrap();
    let Some(GotoImplementationResponse::Array(methods)) =
        Box::pin(backend.goto_implementation(params)).await.unwrap()
    else {
        panic!("the exact method declaration should retain its own and descendant definitions");
    };
    assert_eq!(methods.len(), 2);
    assert!(methods.iter().any(|location| location.uri == base));
    assert!(methods.iter().any(|location| location.uri == child));
    assert!(methods.iter().all(|location| location.uri != other));
}

