#[cfg(unix)]
#[test]
fn constructed_product_alias_retains_the_original_counted_path_for_admission() {
    for spelling in [
        "//srv/share/a.tcl",
        "///local/path.tcl",
        "//server",
        "//?/é.tcl",
    ] {
        let actual = Path::new(spelling);
        let constructed = constructed_file_uri(actual).unwrap();
        assert_eq!(constructed.path.as_os_str(), actual.as_os_str());
        assert_eq!(Some(constructed.uri.clone()), canonical_file_uri(actual));
        let admitted = constructed.admission(&vfs::NativeStore).unwrap();
        assert_eq!(admitted.path().unwrap().as_os_str(), actual.as_os_str());
        admitted
            .check_for(&constructed.uri, &vfs::NativeStore)
            .unwrap();
        // A virtual registration is an independent stronger owner. The
        // forward alias cannot replace its different selected Path.
        let virtual_store = vfs::MemoryStore::new();
        virtual_store.upsert_uri(
            constructed.uri.as_str(),
            "/different/source.tcl",
            Vec::new(),
        );
        assert!(constructed.admission(&virtual_store).is_err());
    }
}

#[test]
fn auto_source_graph_inherits_entry_requires() {
    // app.tcl requires Tk and sources lib/util.tcl; util inherits Tk, so a
    // Tk W120 in util is suppressed with no configuration at all.
    let app = Uri::from_file_path("/proj/app.tcl").unwrap();
    let util = Uri::from_file_path("/proj/lib/util.tcl").unwrap();
    let index = ws_index(&[
        (&app, "package require Tk\nsource lib/util.tcl\n"),
        (&util, "proc u {} {}\n"),
    ]);
    let inherited = compute_inherited_requires(&index, &util, &[], None);
    assert_eq!(inherited, vec!["Tk".to_owned()]);
    // The entry file itself inherits nothing.
    assert_eq!(
        compute_inherited_requires(&index, &app, &[], None),
        [] as [std::string::String; 0]
    );
}

#[test]
fn explicit_entry_points_override_source_graph() {
    // main.tcl requires Tk but does NOT source other.tcl; with main.tcl set
    // as an entry point, other.tcl still inherits Tk (project-wide), and the
    // auto source-graph is bypassed entirely.
    let root = PathBuf::from("/proj");
    let main = Uri::from_file_path("/proj/main.tcl").unwrap();
    let other = Uri::from_file_path("/proj/other.tcl").unwrap();
    let index = ws_index(&[(&main, "package require Tk\n"), (&other, "proc o {} {}\n")]);
    // Auto mode: other.tcl is not sourced by main, so it inherits nothing.
    assert_eq!(
        compute_inherited_requires(&index, &other, &[], Some(&root)),
        [] as [std::string::String; 0]
    );
    // Explicit entry point: other.tcl inherits main.tcl's Tk.
    let entries = vec!["main.tcl".to_owned()];
    let inherited = compute_inherited_requires(&index, &other, &entries, Some(&root));
    assert_eq!(inherited, vec!["Tk".to_owned()]);
}

// Cross-file command resolution + arity.
//
// The two-file shape single-file coverage cannot catch: `deflib.tcl`
// defines `proc libtest {a b c}` and
// `plaincaller.tcl` calls `libtest 1 2`. Go-to-definition already
// resolved it; diagnostics called it unknown.
//
// Oracle, C Tcl 9.0.4:
//
// ```
// % cat deflib.tcl
// proc libtest {a b c} { return [expr {$a + $b + $c}] }
// % tclsh9.0
// % source deflib.tcl ; libtest 1 2
// wrong # args: should be "libtest a b c"
// ```

/// Settle `caller_src`'s call sites against an index built from `others`.
fn settle(
    caller_uri: &Uri,
    caller_src: &str,
    others: &[(&Uri, &str)],
) -> (tcl_compiler::analyser::AnalysisResult, CrossFileCalls) {
    // These reporting-index controls explicitly select Logical source
    // compatibility; they provide no Native lookup or callable entry.
    let analysis = original_workspace_diagnostics_tests::lexical_analysis(caller_src);
    let providers: Vec<_> = others
        .iter()
        .map(|(uri, source)| {
            (
                uri.as_str().to_owned(),
                original_workspace_diagnostics_tests::lexical_analysis(source),
            )
        })
        .collect();
    let index = core_workspace_index::WorkspaceIndex::from_documents(
        providers
            .iter()
            .map(|(uri, analysis)| (uri.as_str(), analysis)),
    );
    let registry = tcl_registry::model::ingress::static_context_for("tcl8.6").commands();
    if std::env::var_os("TCL_LSP_TRACE_LOGICAL_SETTLEMENT130").is_some() {
        eprintln!(
            "logical130 caller={caller_src:?} lexical={} unresolved={:?}",
            analysis.allows_lexical_declaration_advice(),
            analysis.unresolved_command_sites
        );
        eprintln!(
            "logical130 providers={:?} live={:?}",
            providers
                .iter()
                .map(|(uri, analysis)| (
                    uri,
                    analysis.allows_lexical_declaration_advice(),
                    analysis.all_procs.keys().collect::<Vec<_>>()
                ))
                .collect::<Vec<_>>(),
            index
                .live_procs()
                .map(|proc| (&proc.qualified_name, proc.arity))
                .collect::<Vec<_>>()
        );
        for invocation in &analysis.command_invocations {
            let binding = analysis
                .retained_command_realm()
                .unwrap()
                .invocation_at_source("", invocation.range.start());
            eprintln!(
                "logical130 invocation={:?} lookup={:?} candidates={:?} logical={} presence={:?} diagnostic={:?} original={} index={:?}",
                invocation.name,
                invocation.lookup,
                invocation.resolution_candidates,
                binding.logical_source_name_advice_input().is_some(),
                binding.selected_slot_presence(),
                binding.selected_slot_diagnostic_presence(),
                binding.original_recorded_head_name_input().is_some(),
                invocation
                    .resolution_candidates
                    .iter()
                    .map(|candidate| (
                        candidate,
                        index.workspace_command_exists_for_call(candidate, false)
                    ))
                    .collect::<Vec<_>>()
            );
        }
    }
    let settled = settle_cross_file_calls(&index, &analysis, registry, caller_uri.as_str());
    (analysis, settled)
}

/// The E002/E003 codes `cross_file_arity_diagnostics` reports, in order.
fn arity_codes(
    analysis: &tcl_compiler::analyser::AnalysisResult,
    settled: &CrossFileCalls,
) -> Vec<String> {
    cross_file_arity_diagnostics(analysis, settled, |_| false)
        .iter()
        .map(|d| d.code.as_str().to_owned())
        .collect()
}

fn caller_uri() -> Uri {
    Uri::from_file_path("/proj/plaincaller.tcl").unwrap()
}

fn deflib() -> Uri {
    Uri::from_file_path("/proj/deflib.tcl").unwrap()
}

/// **TP.** The cross-file call resolves (so its W123 is
/// suppressed) *and* its wrong argument count is reported.
#[test]
fn cross_file_call_resolves_and_arity_checks() {
    let (analysis, settled) = settle(
        &caller_uri(),
        "libtest 1 2\n",
        &[(&deflib(), "proc libtest {a b c} { return 1 }\n")],
    );
    assert_eq!(
        settled.resolved.len(),
        1,
        "a workspace proc must settle the call: {settled:?}",
    );
    assert_eq!(
        arity_codes(&analysis, &settled),
        ["E002"],
        "tclsh: `wrong # args: should be \"libtest a b c\"`",
    );
}

/// **TP.** Too many arguments is the other half of the same check.
#[test]
fn cross_file_call_reports_too_many_arguments() {
    let (analysis, settled) = settle(
        &caller_uri(),
        "libtest 1 2 3 4\n",
        &[(&deflib(), "proc libtest {a b c} { return 1 }\n")],
    );
    assert_eq!(arity_codes(&analysis, &settled), ["E003"]);
}

/// **TP.** A correct call draws nothing — the check is not simply
/// "anything cross-file is an error".
#[test]
fn cross_file_call_with_a_fitting_count_is_silent() {
    let (analysis, settled) = settle(
        &caller_uri(),
        "libtest 1 2 3\n",
        &[(&deflib(), "proc libtest {a b c} { return 1 }\n")],
    );
    assert_eq!(settled.resolved.len(), 1, "still resolves: {settled:?}");
    assert_eq!(
        arity_codes(&analysis, &settled),
        [] as [std::string::String; 0]
    );
}

#[test]
fn cross_file_source_candidates_do_not_match_foreign_namespace_tails() {
    let caller = Uri::from_file_path("/proj/caller.tcl").unwrap();
    let foreign = Uri::from_file_path("/proj/foreign.tcl").unwrap();
    let (analysis, settled) = settle(
        &caller,
        "namespace eval caller { helper x }\n",
        &[(&foreign, "namespace eval foreign { proc helper {x} {} }\n")],
    );
    assert!(analysis.allows_lexical_declaration_advice());
    assert!(settled.resolved.is_empty());
}

#[test]
fn cross_file_math_function_uses_the_retained_expression_coordinate() {
    let caller = Uri::from_file_path("/proj/vector.tcl").unwrap();
    let mathfunc = Uri::from_file_path("/proj/mathfunc.tcl").unwrap();
    let source = "expr {Pi()}\n";
    let (analysis, settled) = settle(
        &caller,
        source,
        &[(
            &mathfunc,
            "namespace eval ::tcl::mathfunc { proc Pi {} { return 3.14 } }\n",
        )],
    );
    let start = u32::try_from(source.find("Pi").unwrap()).unwrap();
    assert!(settled.resolved.contains(&(start, start + 2)));
    assert!(analysis.allows_lexical_declaration_advice());
}

/// **TP — disjoint union.** Two indexed runtime identities accepting
/// exactly one and exactly three arguments do not accept the gap at two.
/// C Tcl 9.0.4 rejects `p x y` under either definition: exact-one says
/// `p a`, and exact-three says `p a b c`. The workspace may not know which
/// identity runs, but it does know the call fits neither.
#[test]
fn disjoint_cross_file_arity_ranges_reject_the_gap() {
    let second = Uri::from_file_path("/proj/deflib2.tcl").unwrap();
    let (analysis, settled) = settle(
        &caller_uri(),
        "p 1 2\n",
        &[
            (&deflib(), "proc p {a} {}\n"),
            (&second, "proc p {a b c} {}\n"),
        ],
    );
    assert_eq!(arity_codes(&analysis, &settled), ["E005"]);
    let diagnostics = cross_file_arity_diagnostics(&analysis, &settled, |_| false);
    assert_eq!(
        diagnostics[0].message,
        "Wrong argument-count shape for 'p': expected 1 or 3, got 2",
    );
}

/// **TN/FP guard.** Every member of a disjoint arity union remains valid;
/// preserving the gap must not turn the union into an intersection.
#[test]
fn disjoint_cross_file_arity_ranges_accept_each_member() {
    let second = Uri::from_file_path("/proj/deflib2.tcl").unwrap();
    for call in ["p 1\n", "p 1 2 3\n"] {
        let (analysis, settled) = settle(
            &caller_uri(),
            call,
            &[
                (&deflib(), "proc p {a} {}\n"),
                (&second, "proc p {a b c} {}\n"),
            ],
        );
        assert!(
            arity_codes(&analysis, &settled).is_empty(),
            "one indexed proc accepts `{call}`: {settled:?}",
        );
    }
}

/// **FP guard — the precision that lets this tier be on by default.** A
/// bare `buried` called at global scope has candidates `::buried` only; a
/// `proc ::deep::buried` matches none of them, so the call must NOT
/// resolve. This is exactly the bare-tail match that made the opt-in tier
/// silence 197 justified W123s over tcllib.
#[test]
fn a_namespaced_proc_does_not_settle_a_bare_global_call() {
    let (analysis, settled) = settle(
        &caller_uri(),
        "buried 1\n",
        &[(
            &deflib(),
            "namespace eval ::deep { proc buried {x} { return $x } }\n",
        )],
    );
    assert!(
        settled.resolved.is_empty(),
        "`buried` at global scope reaches `::buried`, which nothing \
             defines — tclsh: `invalid command name \"buried\"`: {settled:?}",
    );
    assert_eq!(
        arity_codes(&analysis, &settled),
        [] as [std::string::String; 0]
    );
}

/// **FN guard.** A command nothing in the workspace defines still does not
/// resolve, so its W123 survives every tier.
#[test]
fn a_genuinely_unknown_command_never_resolves() {
    let (_, settled) = settle(
        &caller_uri(),
        "totallyUnknownCommand 1 2\n",
        &[(&deflib(), "proc libtest {a b c} { return 1 }\n")],
    );
    assert!(settled.resolved.is_empty(), "{settled:?}");
}

/// **TN — `args` tail.** An unbounded signature accepts any count above
/// its minimum, so no argument count draws an error.
#[test]
fn arity_abstains_for_an_args_tailed_signature() {
    let (analysis, settled) = settle(
        &caller_uri(),
        "argstail 1 2 3 4 5 6 7\n",
        &[(&deflib(), "proc argstail {a args} { return $a }\n")],
    );
    assert_eq!(settled.resolved.len(), 1, "still resolves: {settled:?}");
    assert!(
        arity_codes(&analysis, &settled).is_empty(),
        "a trailing `args` is unbounded (tclsh accepts every count >= 1)",
    );
}

/// **TN — `args` tail, below the minimum.** The minimum is still enforced:
/// abstention is about the *upper* bound, not a blanket exemption.
#[test]
fn arity_still_enforces_the_minimum_of_an_args_tailed_signature() {
    let (analysis, settled) = settle(
        &caller_uri(),
        "argstail\n",
        &[(&deflib(), "proc argstail {a args} { return $a }\n")],
    );
    assert_eq!(arity_codes(&analysis, &settled), ["E002"]);
}

/// **TN — defaulted parameter.** A default lowers the minimum, so both the
/// short and the full call are accepted.
#[test]
fn arity_abstains_across_a_defaulted_parameter() {
    for call in ["defaulted 1\n", "defaulted 1 2\n"] {
        let (analysis, settled) = settle(
            &caller_uri(),
            call,
            &[(&deflib(), "proc defaulted {a {b 2}} { return $a }\n")],
        );
        assert!(
            arity_codes(&analysis, &settled).is_empty(),
            "`{call}` is accepted by tclsh",
        );
    }
}

/// **TN — computed parameter list.** `proc p $params {…}` declares an
/// unknown number of formals; reading the empty recorded list as "takes no
/// arguments" draws a false E003, so the arity must be fully open.
#[test]
fn arity_abstains_for_a_computed_parameter_list() {
    let (analysis, settled) = settle(
        &caller_uri(),
        "computed 1 2 3\n",
        &[(
            &deflib(),
            "set params {a b}\nproc computed $params { return 1 }\n",
        )],
    );
    assert!(arity_codes(&analysis, &settled).is_empty(), "{settled:?}");
}

/// **TN — a class shares the name.** The call may dispatch to the
/// arity-less class command, so the name resolves (no W123) but draws no
/// arity error.
#[test]
fn arity_abstains_when_a_class_shares_the_name() {
    let (analysis, settled) = settle(
        &caller_uri(),
        "Widget 1 2 3 4 5\n",
        &[(&deflib(), "oo::class create Widget {}\n")],
    );
    assert_eq!(
        settled.resolved.len(),
        1,
        "the class command resolves the name: {settled:?}",
    );
    assert!(
        arity_codes(&analysis, &settled).is_empty(),
        "a class command has no fixed arity",
    );
}

/// **TN — dynamic providers.** `namespace unknown` makes resolution
/// unknowable, and the analyser records no unresolved sites at all, so
/// both the suppression and the arity check abstain together.
#[test]
fn nothing_settles_when_the_document_has_dynamic_providers() {
    let (analysis, settled) = settle(
        &caller_uri(),
        "namespace unknown myhandler\nlibtest 1 2\n",
        &[(&deflib(), "proc libtest {a b c} { return 1 }\n")],
    );
    assert!(
        analysis.has_dynamic_providers,
        "`namespace unknown` must widen to dynamic providers",
    );
    assert!(settled.resolved.is_empty(), "{settled:?}");
    assert_eq!(
        arity_codes(&analysis, &settled),
        [] as [std::string::String; 0]
    );
}

/// **TN — a `{*}`-expanded call.** The true argument count is a runtime
/// fact, so no arity claim can be made.
#[test]
fn arity_abstains_for_an_expanded_call() {
    let (analysis, settled) = settle(
        &caller_uri(),
        "set a {1 2}\nlibtest {*}$a\n",
        &[(&deflib(), "proc libtest {a b c} { return 1 }\n")],
    );
    assert!(arity_codes(&analysis, &settled).is_empty(), "{settled:?}");
}

/// A disabled code is honoured — the arity diagnostics are synthesised
/// after the analyser applied its own filter, so this path must replicate
/// it or a user who turned E002 off still sees it.
#[test]
fn cross_file_arity_honours_a_disabled_code() {
    let (analysis, settled) = settle(
        &caller_uri(),
        "libtest 1 2\n",
        &[(&deflib(), "proc libtest {a b c} { return 1 }\n")],
    );
    let out = cross_file_arity_diagnostics(&analysis, &settled, |code| code == "E002");
    assert!(out.is_empty(), "{out:?}");
}

/// Legacy signature dependencies remain targeted by names and arity.
/// A body edit independently changes complete original source ownership.
#[test]
fn indexed_signature_changes_select_only_their_callers() {
    let lib = Uri::from_file_path("/proj/lib.tcl").unwrap();
    let caller = Uri::from_file_path("/proj/caller.tcl").unwrap();
    let unrelated = Uri::from_file_path("/proj/unrelated.tcl").unwrap();
    let mut index = ws_index(&[
        (&lib, "proc helper {a} {}\n"),
        (&caller, "helper 1 2\n"),
        (&unrelated, "other 1 2\n"),
    ]);
    let before = IndexedDiagnosticFacts::capture(&index, lib.as_str());
    let edited = Analyser::new()
        .analyse("proc helper {a b} {}\n", "tcl8.6")
        .clone();
    index.replace_document(lib.as_str(), &edited);
    let after = IndexedDiagnosticFacts::capture(&index, lib.as_str());
    let change = before.change_to(&after);
    assert_eq!(
        change.command_names,
        HashSet::from(["::helper".to_owned()]),
        "an arity edit changes the callable signature without changing its name",
    );
    assert_eq!(
        command_diagnostic_consumers(&index, &change.command_names),
        HashSet::from([caller.as_str().to_owned()]),
        "only the matching caller consumes this signature",
    );

    let stable = IndexedDiagnosticFacts::capture(&index, lib.as_str());
    let body_only = Analyser::new()
        .analyse("proc helper {a b} { return $a }\n", "tcl8.6")
        .clone();
    index.replace_document(lib.as_str(), &body_only);
    let body_change = stable.change_to(&IndexedDiagnosticFacts::capture(&index, lib.as_str()));
    assert!(body_change.command_names.is_empty());
    assert!(
        body_change.original_changed,
        "changed full source withdraws retained original ownership"
    );
    assert!(body_change.moved_workspace_facts());
}

fn diagnostic_tcl_document(source: &str) -> DocumentState {
    DocumentState::new(source.to_owned(), "tcl8.6".to_owned())
}

#[test]
fn original_diagnostic_invalidation_keeps_opaque_dependencies_and_foreign_surfaces_separate() {
    // Implementation contract: naming.editor.original-diagnostic-invalidation
    // docs/design/analysis/name-resolution-proofs/original-diagnostic-invalidation.md
    let library = Uri::from_str("file:///opaque-provider.tcl").unwrap();
    let caller = Uri::from_str("file:///opaque-caller.tcl").unwrap();
    let sibling = Uri::from_str("file:///opaque-sibling.tcl").unwrap();
    let javascript = Uri::from_str("file:///foreign.js").unwrap();
    let config = Uri::from_str("file:///bigip.conf").unwrap();
    let before_source = r"proc p\uD800 {one} {}";
    let after_source = r"proc p\uD800 {one two} {}";
    let caller_source = r"p\uD800 1";
    let sibling_source = r"p\uD801 1";
    let mut original = Analyser::new().analyse(before_source, "tcl8.6");
    original.all_procs.clear();
    original.proc_declaration_sites.clear();
    let mut caller_analysis = Analyser::new().analyse(caller_source, "tcl8.6");
    for invocation in &mut caller_analysis.command_invocations {
        invocation.name = "counterfactual-report".to_owned();
        invocation.resolution_candidates = vec!["counterfactual-report".to_owned()];
    }
    let sibling_analysis = Analyser::new().analyse(sibling_source, "tcl8.6");
    assert!(
        caller_analysis
            .command_invocations
            .iter()
            .any(|invocation| invocation.original_lookup.is_some())
    );
    let mut index = core_workspace_index::WorkspaceIndex::from_documents([
        (library.as_str(), &original),
        (caller.as_str(), &caller_analysis),
        (sibling.as_str(), &sibling_analysis),
    ]);
    let before = IndexedDiagnosticFacts::capture(&index, library.as_str());
    let mut after_analysis = Analyser::new().analyse(after_source, "tcl8.6");
    after_analysis.all_procs.clear();
    after_analysis.proc_declaration_sites.clear();
    index.replace_document(library.as_str(), &after_analysis);
    let after = IndexedDiagnosticFacts::capture(&index, library.as_str());
    let change = before.change_to(&after);
    assert_eq!(before.procs, after.procs);
    assert_eq!(before.classes, after.classes);
    assert!(change.command_names.is_empty());
    assert!(change.original_changed && change.moved_workspace_facts());
    let mut docs = HashMap::from([
        (library.clone(), diagnostic_tcl_document(after_source)),
        (caller.clone(), diagnostic_tcl_document(caller_source)),
        (sibling.clone(), diagnostic_tcl_document(sibling_source)),
        (
            javascript.clone(),
            DocumentState::new(caller_source.to_owned(), "unknown-js".to_owned())
                .with_language_id("javascript".to_owned()),
        ),
        (
            config.clone(),
            DocumentState::new(caller_source.to_owned(), "f5-bigip".to_owned())
                .with_language_id("f5-bigip".to_owned()),
        ),
    ]);
    assert_eq!(
        original_diagnostic_consumers(&index, &docs, &change),
        HashSet::from([caller.as_str().to_owned()])
    );
    assert!(
        !after
            .change_to(&IndexedDiagnosticFacts::capture(&index, library.as_str()))
            .moved_workspace_facts()
    );
    // Missing actual caller lookup cannot be repaired from the report.
    caller_analysis
        .command_invocations
        .iter_mut()
        .find(|invocation| invocation.original_lookup.is_some())
        .unwrap()
        .original_lookup = None;
    index.replace_document(caller.as_str(), &caller_analysis);
    let all_tcl = HashSet::from([
        library.as_str().to_owned(),
        caller.as_str().to_owned(),
        sibling.as_str().to_owned(),
    ]);
    assert_eq!(
        original_diagnostic_consumers(&index, &docs, &change),
        all_tcl
    );
    assert!(
        original_diagnostic_consumers(&index, &docs, &IndexedDiagnosticChange::default())
            .is_empty()
    );
    // An unpublished changed source has unknown current dependencies.
    index.replace_document(
        caller.as_str(),
        &Analyser::new().analyse(caller_source, "tcl8.6"),
    );
    docs.get_mut(&caller).unwrap().text = Arc::from("# changed caller source");
    assert_eq!(
        original_diagnostic_consumers(&index, &docs, &change),
        all_tcl
    );
}

/// **A constants-only edit is a source-graph change.** Retargeting
/// `set dir /a` to `/b` leaves the `source [file
/// join $dir x.tcl]` row byte-identical, so comparing rows alone reports
/// "nothing changed" and neither the old child nor the new one is
/// rescheduled — both were stale.  The captured constants must move the
/// needle, and the old rows must reconstruct the **old** edge from the
/// old constants, not the post-edit ones.
#[test]
fn a_constants_only_edit_reschedules_both_children() {
    let parent = Uri::from_file_path("/proj/parent.tcl").unwrap();
    let old_child = Uri::from_file_path("/proj/a/x.tcl").unwrap();
    let new_child = Uri::from_file_path("/proj/b/x.tcl").unwrap();
    let parent_before = "set dir /proj/a\nsource [file join $dir x.tcl]\n";
    let mut index = ws_index(&[
        (&parent, parent_before),
        (&old_child, "proc a_helper {} {}\n"),
        (&new_child, "proc b_helper {} {}\n"),
    ]);
    let before = IndexedDiagnosticFacts::capture(&index, parent.as_str());
    let edited = Analyser::new()
        .analyse("set dir /proj/b\nsource [file join $dir x.tcl]\n", "tcl8.6")
        .clone();
    index.replace_document(parent.as_str(), &edited);
    let after = IndexedDiagnosticFacts::capture(&index, parent.as_str());
    let change = before.change_to(&after);
    assert_eq!(
        before.sources, after.sources,
        "precondition: the source row text is untouched by this edit",
    );
    assert!(
        change.source_or_package_changed,
        "the constant moved, so the resolved graph moved",
    );

    // The old edge, reconstructed from the old constants.
    let stale = source_diagnostic_consumers_with_sources(
        &index,
        parent.as_str(),
        Some(ReplacedSources {
            rows: &before.sources,
            constants: &before.path_constants,
        }),
    );
    assert!(
        stale.contains(old_child.as_str()),
        "the child that is no longer sourced must be refreshed: {stale:?}",
    );
    // The new edge, from the current index.
    let fresh = source_diagnostic_consumers(&index, parent.as_str());
    assert!(
        fresh.contains(new_child.as_str()),
        "the newly sourced child must be refreshed: {fresh:?}",
    );
}

/// Source dependencies are directional. A changed child wakes its sourcing
/// ancestors and anything it sources in turn, but not a sibling under the
/// same parent.
#[test]
fn source_fact_changes_select_ancestors_and_descendants_not_siblings() {
    let root = Uri::from_file_path("/proj/root.tcl").unwrap();
    let child = Uri::from_file_path("/proj/child.tcl").unwrap();
    let grandchild = Uri::from_file_path("/proj/grandchild.tcl").unwrap();
    let sibling = Uri::from_file_path("/proj/sibling.tcl").unwrap();
    let index = ws_index(&[
        (&root, "source child.tcl\nsource sibling.tcl\n"),
        (&child, "source grandchild.tcl\npackage require Tk\n"),
        (&grandchild, "winfo exists .x\n"),
        (&sibling, "winfo exists .y\n"),
    ]);
    assert_eq!(
        source_diagnostic_consumers(&index, child.as_str()),
        HashSet::from([root.as_str().to_owned(), grandchild.as_str().to_owned(),]),
    );
}

/// **TP/TN for the hand-built wake set.**  A document that is open but not
/// in the index is woken — the transient open-before-first-publish race —
/// *unless* its backing file was deleted out of band, in which case
/// it is unindexed permanently rather than transiently: the publish path
/// removes rather than replaces it, so it would otherwise be re-woken by
/// every fact-moving publish anywhere in the workspace, for ever, to
/// re-derive the same answer.  An indexed document is never in this set at
/// all — the index-driven consumer queries find those.
#[test]
fn the_wake_set_skips_a_buffer_whose_backing_file_was_deleted() {
    let indexed = Uri::from_file_path("/proj/indexed.tcl").unwrap();
    let just_opened = Uri::from_file_path("/proj/just-opened.tcl").unwrap();
    let orphaned = Uri::from_file_path("/proj/orphaned.tcl").unwrap();
    let index = ws_index(&[(&indexed, "proc helper {a} {}\n")]);

    let mut docs: HashMap<Uri, DocumentState> = HashMap::new();
    for uri in [&indexed, &just_opened, &orphaned] {
        docs.insert(
            uri.clone(),
            DocumentState::new("helper 1\n".to_owned(), "tcl8.6".to_owned()),
        );
    }
    docs.get_mut(&orphaned).unwrap().backing_file_deleted = true;

    let woken: HashSet<String> = unindexed_open_documents(&index, &docs)
        .into_iter()
        .collect();
    assert_eq!(
        woken,
        HashSet::from([just_opened.as_str().to_owned()]),
        "only the transiently unindexed buffer is woken by hand",
    );
}

/// **The other half of the same buffer's story.** Being
/// absent from the index is two facts about an orphan, not one: it must
/// not *contribute* — its path is dead, and re-adding it resurrects the
/// ghost `did_change_watched_files` retired — but it does still *consume*.
/// The buffer is on screen and its squiggles are read, so when a peer
/// changes the arity of a proc it calls, its E002/W123 must be recomputed.
/// Nothing else can name it: the index-driven consumer queries read its
/// call-site records from the index, and it has none there.
///
/// TP: the orphan calls `helper`, whose signature moved. TN: a change to
/// an unrelated name leaves it alone, so this stays a targeted wake and
/// not a blanket re-wake.
#[test]
fn an_orphan_is_still_woken_by_a_signature_it_consumes() {
    let orphan = Uri::from_file_path("/proj/orphan.tcl").unwrap();
    let live = Uri::from_file_path("/proj/live.tcl").unwrap();
    let mut docs: HashMap<Uri, DocumentState> = HashMap::new();
    docs.insert(
        orphan.clone(),
        DocumentState::new("helper 1\n".to_owned(), "tcl8.6".to_owned()),
    );
    docs.insert(
        live.clone(),
        DocumentState::new("helper 1\n".to_owned(), "tcl8.6".to_owned()),
    );
    docs.get_mut(&orphan).unwrap().backing_file_deleted = true;
    let _source_query_slots =
        retain_default_orphan_query_fixture(&orphan, docs.get_mut(&orphan).unwrap());

    let consumed = IndexedDiagnosticChange {
        command_names: HashSet::from(["::helper".to_owned()]),
        source_or_package_changed: false,
        ..IndexedDiagnosticChange::default()
    };
    assert_eq!(
        orphaned_fact_consumers(&docs, &consumed),
        vec![orphan.as_str().to_owned()],
        "the orphan calls `helper`, so a change to its signature reaches it",
    );

    let unrelated = IndexedDiagnosticChange {
        command_names: HashSet::from(["::unrelated".to_owned()]),
        source_or_package_changed: false,
        ..IndexedDiagnosticChange::default()
    };
    assert!(
        orphaned_fact_consumers(&docs, &unrelated).is_empty(),
        "a name the orphan never mentions must not wake it",
    );

    // A source-graph or package move can change what the orphan's own
    // calls resolve to without renaming anything, so it is not filterable
    // by name.
    let graph_moved = IndexedDiagnosticChange {
        command_names: HashSet::new(),
        source_or_package_changed: true,
        ..IndexedDiagnosticChange::default()
    };
    assert_eq!(
        orphaned_fact_consumers(&docs, &graph_moved),
        vec![orphan.as_str().to_owned()],
    );
}

/// The same defect stated where it bites, over the **union** of every
/// consumer set a publish builds. `live.tcl` changes
/// `helper`'s arity; the orphan calls `helper 1` and is on screen with a
/// now-wrong E002. It is absent from the index, so
/// [`command_diagnostic_consumers`] cannot see its call site, and it is
/// excluded from [`unindexed_open_documents`] — without
/// [`orphaned_fact_consumers`] no set names it and its squiggles stay
/// stale with no signal.
#[test]
fn every_consumer_set_together_still_names_an_orphaned_caller() {
    let live = Uri::from_file_path("/proj/live.tcl").unwrap();
    let orphan = Uri::from_file_path("/proj/orphan.tcl").unwrap();
    // The index holds the publishing document only: the orphan was removed
    // from it by its own publish, exactly as `remove_document` leaves it.
    let index = ws_index(&[(&live, "proc helper {a b} {}\n")]);

    let mut docs: HashMap<Uri, DocumentState> = HashMap::new();
    docs.insert(
        live.clone(),
        DocumentState::new("proc helper {a b} {}\n".to_owned(), "tcl8.6".to_owned()),
    );
    docs.insert(
        orphan.clone(),
        DocumentState::new("helper 1\n".to_owned(), "tcl8.6".to_owned()),
    );
    docs.get_mut(&orphan).unwrap().backing_file_deleted = true;

    let change = IndexedDiagnosticChange {
        command_names: HashSet::from(["::helper".to_owned()]),
        source_or_package_changed: false,
        ..IndexedDiagnosticChange::default()
    };
    let mut consumers = command_diagnostic_consumers(&index, &change.command_names);
    consumers.extend(unindexed_open_documents(&index, &docs));
    consumers.extend(orphaned_fact_consumers(&docs, &change));
    assert!(
        consumers.contains(orphan.as_str()),
        "an on-screen orphan consuming the changed signature must be woken; got {consumers:?}",
    );
}

/// A `source`d file's `package require` is available *after* the statement
/// and not before it — the C Tcl 9.0.4 behaviour recorded on
/// `source_graph::descendant_requires`.
#[test]
fn placed_requires_are_only_available_after_the_source_statement() {
    let inheritance = SourceInheritance {
        original: None,
        ambient: Vec::new(),
        placed: vec![tcl_lsp_core::source_graph::PlacedRequire {
            name: "Tk".to_owned(),
            at: 20,
            enclosing_body: None,
        }],
        unresolvable_source: false,
    };
    assert!(
        inheritance.available_at(5, None).is_empty(),
        "a call above the `source` runs before it",
    );
    assert_eq!(
        inheritance.available_at(40, None),
        vec!["Tk".to_owned()],
        "a call below the `source` runs after it",
    );
}

/// A load-level `source` counts for a call written inside *any* proc body,
/// wherever that body sits — the whole file loads before any body runs.
#[test]
fn a_load_level_source_covers_a_call_inside_a_proc_body() {
    let inheritance = SourceInheritance {
        original: None,
        ambient: Vec::new(),
        placed: vec![tcl_lsp_core::source_graph::PlacedRequire {
            name: "Tk".to_owned(),
            at: 90,
            enclosing_body: None,
        }],
        unresolvable_source: false,
    };
    // A call at offset 40 inside a body spanning 30..60 — textually above
    // the `source` at 90, but it cannot run until the body is invoked.
    let body = tcl_lexer::Span::new(30, 60);
    assert_eq!(
        inheritance.available_at(40, Some(body)),
        vec!["Tk".to_owned()],
    );
}

/// The whole up direction is inert for a document that `source`s nothing,
/// which is the shape of almost every file — and the abstention flag stays
/// down, so W120/W123 keep working normally.
#[test]
fn a_document_that_sources_nothing_inherits_nothing_and_does_not_abstain() {
    let uri = Uri::from_file_path("/proj/solo.tcl").unwrap();
    let analysis = tcl_compiler::analyser::Analyser::new()
        .analyse("winfo exists .l\n", "tcl8.6")
        .clone();
    let index = ws_index(&[(&uri, "winfo exists .l\n")]);
    let got = compute_source_inheritance(
        &index,
        &uri,
        &analysis,
        &[],
        None,
        tcl_lsp_core::package_resolver::PackagePrefer::default(),
    );
    assert_eq!(
        got.placed,
        [] as [tcl_lsp_core::source_graph::PlacedRequirement<std::string::String>; 0]
    );
    assert!(!got.unresolvable_source);
    assert!(got.is_empty());
}

/// A `source` whose target is not an indexed document — outside the
/// workspace, absent, or a path no static fold can prove — sets the
/// abstention flag, and W120/W123 then go quiet document-wide.
#[test]
fn an_unfollowable_source_sets_the_abstention_flag() {
    let uri = Uri::from_file_path("/proj/main.tcl").unwrap();
    let src = "source nosuchfile.tcl\nwinfo exists .l\n";
    let analysis = tcl_compiler::analyser::Analyser::new()
        .analyse(src, "tcl8.6")
        .clone();
    let index = ws_index(&[(&uri, src)]);
    let got = compute_source_inheritance(
        &index,
        &uri,
        &analysis,
        &[],
        None,
        tcl_lsp_core::package_resolver::PackagePrefer::default(),
    );
    assert!(
        got.unresolvable_source,
        "a `source` of a file the workspace does not hold is unknowable",
    );
}

/// The followable case: `main.tcl` sources `tkFile.tcl`, which requires
/// Tk. Tk arrives in `main.tcl`, and the abstention flag stays down —
/// followable source, so no abstention.
#[test]
fn a_followable_source_contributes_its_requires_without_abstaining() {
    let main = Uri::from_file_path("/proj/main.tcl").unwrap();
    let tk = Uri::from_file_path("/proj/tkFile.tcl").unwrap();
    let src = "source tkFile.tcl\nwinfo exists .l\n";
    let analysis = tcl_compiler::analyser::Analyser::new()
        .analyse(src, "tcl8.6")
        .clone();
    let index = ws_index(&[(&main, src), (&tk, "package require Tk\n")]);
    let got = compute_source_inheritance(
        &index,
        &main,
        &analysis,
        &[],
        None,
        tcl_lsp_core::package_resolver::PackagePrefer::default(),
    );
    assert!(
        !got.unresolvable_source,
        "a literal `source` of an indexed file is followable",
    );
    assert_eq!(
        got.placed
            .iter()
            .map(|p| p.name.as_str())
            .collect::<Vec<_>>(),
        ["Tk"],
        "{got:?}",
    );
}

/// **TN.** Sourcing a file that requires nothing contributes nothing, so a
/// Tk-command W120 in the sourcing file still stands. Option (2) must not
/// have been applied globally.
#[test]
fn sourcing_a_non_tk_file_contributes_nothing() {
    let main = Uri::from_file_path("/proj/main.tcl").unwrap();
    let plain = Uri::from_file_path("/proj/plain.tcl").unwrap();
    let src = "source plain.tcl\nwinfo exists .l\n";
    let analysis = tcl_compiler::analyser::Analyser::new()
        .analyse(src, "tcl8.6")
        .clone();
    let index = ws_index(&[(&main, src), (&plain, "proc helper {} { return 1 }\n")]);
    let got = compute_source_inheritance(
        &index,
        &main,
        &analysis,
        &[],
        None,
        tcl_lsp_core::package_resolver::PackagePrefer::default(),
    );
    assert!(!got.unresolvable_source);
    assert!(got.placed.is_empty(), "{got:?}");
}

#[test]
fn entry_point_paths_resolve_relative_and_absolute() {
    let root = PathBuf::from("/proj");
    let rel = entry_point_uri("src/main.tcl", Some(&root)).unwrap();
    assert_eq!(
        rel,
        Uri::from_file_path("/proj/src/main.tcl").unwrap().as_str()
    );
    let abs = entry_point_uri("/opt/app.tcl", Some(&root)).unwrap();
    assert_eq!(abs, Uri::from_file_path("/opt/app.tcl").unwrap().as_str());
    // A relative entry with no folder root can't be resolved.
    assert!(entry_point_uri("main.tcl", None).is_none());
}

#[test]
fn folder_config_parses_entry_points() {
    let cfg = serde_json::json!({
        "entryPoints": ["main.tcl", "src/app.tcl"],
    });
    let fc = parse_folder_config(&cfg).unwrap();
    assert_eq!(
        fc.entry_points,
        Some(vec!["main.tcl".to_owned(), "src/app.tcl".to_owned()])
    );
}

#[test]
fn folder_config_parses_the_iruleslx_plugin_mapping() {
    let fc = parse_folder_config(&serde_json::json!({
        "iruleslx": {
            "plugins": { "prod": "workspaces/ws_alpha", "other": "/abs/ws" },
            "rules": { "prod": ["irules/http", "irules/tcp"] },
        }
    }))
    .expect("folder config");
    // Sorted by plugin name: a JSON object has no guaranteed order, and an
    // unstable candidate list would make an ambiguity report unstable too.
    assert_eq!(
        fc.iruleslx,
        vec![
            IlxPluginSpec {
                plugin: "other".to_owned(),
                workspace: "/abs/ws".to_owned(),
                extra_rule_dirs: Vec::new(),
            },
            IlxPluginSpec {
                plugin: "prod".to_owned(),
                workspace: "workspaces/ws_alpha".to_owned(),
                extra_rule_dirs: vec!["irules/http".to_owned(), "irules/tcp".to_owned()],
            },
        ]
    );
}

#[test]
fn an_iruleslx_rules_entry_without_a_plugin_entry_is_dropped() {
    // Extra caller directories are only meaningful once the plugin's own
    // workspace is known. Keeping the half-declaration would widen the
    // search for a plugin that still resolves by the directory-name
    // convention — an association the user never made.
    let fc = parse_folder_config(&serde_json::json!({
        "iruleslx": { "rules": { "prod": ["irules"] } }
    }))
    .expect("folder config");
    assert_eq!(fc.iruleslx, [] as [IlxPluginSpec; 0]);
    // …and an empty workspace path is not a declaration either.
    let blank = parse_folder_config(&serde_json::json!({
        "iruleslx": { "plugins": { "prod": "  " } }
    }))
    .expect("folder config");
    assert_eq!(blank.iruleslx, [] as [IlxPluginSpec; 0]);
}

#[test]
fn iruleslx_paths_resolve_against_the_folder_root() {
    let specs = vec![IlxPluginSpec {
        plugin: "prod".to_owned(),
        workspace: "../shared/ws".to_owned(),
        extra_rule_dirs: vec!["irules".to_owned(), "/abs/elsewhere".to_owned()],
    }];
    let roots = resolve_ilx_specs(&specs, Path::new("/repo/app"));
    assert_eq!(roots.len(), 1);
    // Lexically normalised, so this compares equal to the same directory
    // reached from a document's own ancestors.
    assert_eq!(roots[0].workspace, Path::new("/repo/shared/ws"));
    assert_eq!(
        roots[0].extra_rule_dirs,
        vec![
            PathBuf::from("/repo/app/irules"),
            PathBuf::from("/abs/elsewhere"),
        ]
    );
}

#[tokio::test]
async fn default_off_w242_hidden_by_default_enableable_via_config() {
    // End-to-end: a default-off W242 is not published by default, but
    // `tclLsp.diagnostics.W242: true` turns it on (the server has a
    // per-code enable path).
    let backend = test_backend();
    let uri = Uri::from_str("file:///w242.tcl").unwrap();
    let src = "while {$x < 10} {puts hi}\n"; // emits W242 from the analyser
    register(&backend, &uri, src).await;

    let off = backend
        .full_diagnostics_for(&uri, Arc::from(src), "tcl8.6".to_owned(), "tcl")
        .await
        .unwrap();
    assert!(
        !off.iter().any(|d| matches!(
            &d.code,
            Some(tower_lsp_server::ls_types::NumberOrString::String(c)) if c == "W242"
        )),
        "W242 hidden by default: {off:?}",
    );

    backend
        .apply_global_config(&serde_json::json!({ "diagnostics": { "W242": true } }))
        .await
        .unwrap();
    let on = backend
        .full_diagnostics_for(&uri, Arc::from(src), "tcl8.6".to_owned(), "tcl")
        .await
        .unwrap();
    assert!(
        on.iter().any(|d| matches!(
            &d.code,
            Some(tower_lsp_server::ls_types::NumberOrString::String(c)) if c == "W242"
        )),
        "W242 should appear once enabled: {on:?}",
    );
}

/// A policy with every optimisation on and nothing configured — what the
/// old lifts took as `optimiser_enabled = true` and empty sets.
fn open_policy() -> core_policy::Policy {
    let mut policy = core_policy::PolicyBuilder::new().build();
    policy.optimiser = core_policy::OptimiserPolicy::all_on();
    policy
}

/// The wire set of `src`'s compiler checks and rewrites under `policy`,
/// through the one report path every publish path takes.
fn lifted_compiler_set(
    src: &str,
    registry: &CommandRegistry,
    dialect: &str,
    policy: &core_policy::Policy,
) -> Vec<tower_lsp_server::ls_types::Diagnostic> {
    let diags = tcl_lsp_db::compiler_check_diagnostics_uncached(src, registry, dialect, None, None);
    lift_report(src, &core_policy::apply(compiler_findings(&diags), policy))
}

#[test]
fn report_publication_retains_unavailable_generation_status() {
    // naming.diagnostic.typed-subject-reporting
    // docs/design/analysis/name-resolution-proofs/diagnostic-typed-subject-reporting.md
    // The publication adapter carries an explicit refused input, independently of message text.
    let mut analysis = AnalysisResult::default();
    analysis.analysis_context_unavailable = Some(tcl_registry::model::OverlayMiss {
        environment: "tcl9.0".to_owned(),
        overlay: u64::MAX,
    });
    let mut report = core_policy::apply(Vec::new(), &open_policy());
    report.retain_analysis_context(&analysis);
    let rows = lift_report("", &report);
    assert_eq!(rows.len(), 1);
    assert!(has_code(&rows, "ANALYSIS_CONTEXT_UNAVAILABLE"));
    let data = rows[0].data.as_ref().unwrap();
    assert_eq!(data["kind"], "analysisContextUnavailable");
    assert_eq!(data["environment"], "tcl9.0");
    assert_eq!(data["overlay"], u64::MAX);
    assert_eq!(
        lift_report("", &core_policy::apply(Vec::new(), &open_policy())),
        [] as [tower_lsp_server::ls_types::Diagnostic; 0]
    );
}

fn has_code(diags: &[tower_lsp_server::ls_types::Diagnostic], code: &str) -> bool {
    diags.iter().any(|d| matches!(&d.code, Some(tower_lsp_server::ls_types::NumberOrString::String(c)) if c == code))
}

/// The constant-true `if` is folded by SCCP and surfaced
/// as an `O100` constant-branch diagnostic from `run_all_checks`.
/// The base analyser never emits it, so a non-empty result with an
/// O-code proves the compiler-check pipeline's output reaches the
/// published diagnostic set.
#[test]
fn the_report_surfaces_compiler_check_codes() {
    let registry = CommandRegistry::build_default();
    let src = "if {1} { set x 1 } else { set y 2 }\n";
    let diags = lifted_compiler_set(src, &registry, "", &open_policy());
    assert!(
        has_code(&diags, "O100"),
        "expected an O100 constant-branch diagnostic, got: {:?}",
        diags.iter().map(|d| d.code.clone()).collect::<Vec<_>>(),
    );
    // Every lifted diagnostic carries the shared source tag.
    assert!(diags.iter().all(|d| d.source.as_deref() == Some("tcl-lsp")));
}

/// An iRules taint flow (`HTTP::uri` → `HTTP::respond`) is an
/// IRULE3001 the base analyser does not emit; the dialect-aware
/// registry path must surface it through the report.
#[test]
fn the_report_surfaces_irules_taint_flow() {
    let registry = tcl_registry::model::ingress::static_context_for_profile(
        tcl_dialect::DialectProfile::irules(),
    )
    .commands();
    let src = "set u [HTTP::uri]\nHTTP::respond 200 content $u\n";
    let diags = lifted_compiler_set(src, registry, "f5-irules", &open_policy());
    assert!(
        has_code(&diags, "IRULE3001"),
        "expected IRULE3001, got: {:?}",
        diags.iter().map(|d| d.code.clone()).collect::<Vec<_>>(),
    );
}

/// A per-check feature toggle (`tclLsp.diagnostics.<CODE> = false`)
/// must suppress a compiler-*check* code — not just the analyser families.
#[test]
fn the_report_honours_a_per_check_disable() {
    let registry = tcl_registry::model::ingress::static_context_for_profile(
        tcl_dialect::DialectProfile::irules(),
    )
    .commands();
    let src = "set u [HTTP::uri]\nHTTP::respond 200 content $u\n";
    let baseline = lifted_compiler_set(src, registry, "f5-irules", &open_policy());
    assert!(
        has_code(&baseline, "IRULE3001"),
        "expected IRULE3001 baseline"
    );
    let mut policy = core_policy::PolicyBuilder::new()
        .layer(
            core_policy::PolicyLayer::Editor,
            &serde_json::json!({ "diagnostics": { "IRULE3001": false } }),
        )
        .build();
    policy.optimiser = core_policy::OptimiserPolicy::all_on();
    let filtered = lifted_compiler_set(src, registry, "f5-irules", &policy);
    assert!(
        !has_code(&filtered, "IRULE3001"),
        "IRULE3001 must be suppressed when disabled per-check: {:?}",
        filtered.iter().map(|d| d.code.clone()).collect::<Vec<_>>(),
    );
}

/// W110 owns the string-comparison site it shares with O120: the report
/// keeps one squiggle where the two coincide and both where they do not.
#[test]
fn the_report_keeps_one_squiggle_where_w110_and_o120_coincide() {
    use tcl_lexer::Span;
    let finding =
        |code: DiagCode, span: Span, producer: core_policy::Producer| core_policy::Finding {
            code,
            span,
            severity: tcl_core_types::Severity::Warning,
            message: code.to_string(),
            fixes: Vec::new(),
            data: None,
            producer,
        };
    let same = Span::new(2, 4);
    let other = Span::new(10, 12);
    let policy = open_policy();
    let report = core_policy::apply(
        vec![
            finding(DiagCode::W110, same, core_policy::Producer::Analyser),
            finding(DiagCode::O120, same, core_policy::Producer::Optimiser),
            finding(DiagCode::O120, other, core_policy::Producer::Optimiser),
        ],
        &policy,
    );
    let codes: Vec<String> = report.shown().map(|s| s.finding.code.to_string()).collect();
    assert_eq!(codes, ["W110", "O120"]);
    let alone = core_policy::apply(
        vec![finding(
            DiagCode::O120,
            same,
            core_policy::Producer::Optimiser,
        )],
        &policy,
    );
    assert_eq!(alone.shown().count(), 1, "O120 survives without W110");
}

#[test]
fn parse_non_ascii_mode_maps_settings() {
    assert_eq!(parse_non_ascii_mode("off"), NonAsciiMode::Off);
    assert_eq!(parse_non_ascii_mode("strict"), NonAsciiMode::Strict);
    assert_eq!(
        parse_non_ascii_mode("confusables"),
        NonAsciiMode::Confusables
    );
    assert_eq!(parse_non_ascii_mode("common"), NonAsciiMode::Common);
    assert_eq!(parse_non_ascii_mode("bogus"), NonAsciiMode::Default);
}

#[test]
fn settings_non_ascii_mode_nested_and_flat() {
    let nested = serde_json::json!({"tclLsp": {"style": {"nonAscii": "common"}}});
    assert_eq!(settings_non_ascii_mode(&nested), Some(NonAsciiMode::Common));
    let flat = serde_json::json!({"tclLsp.style.nonAscii": "off"});
    assert_eq!(settings_non_ascii_mode(&flat), Some(NonAsciiMode::Off));
    let none = serde_json::json!({"tclLsp": {"dialect": "tcl9.0"}});
    assert_eq!(settings_non_ascii_mode(&none), None);
}

#[test]
fn semantic_tokens_capability_advertises_delta_and_range() {
    use tower_lsp_server::ls_types::SemanticTokensServerCapabilities as Cap;
    let Cap::SemanticTokensOptions(o) = semantic_tokens_capability() else {
        panic!("expected SemanticTokensOptions");
    };
    assert_eq!(o.range, Some(true));
    assert!(matches!(
        o.full,
        Some(SemanticTokensFullOptions::Delta { delta: Some(true) })
    ));
}

#[test]
fn position_encoding_negotiation() {
    use tower_lsp_server::ls_types::{ClientCapabilities, GeneralClientCapabilities};
    let params_with = |encs: Option<Vec<PositionEncodingKind>>| InitializeParams {
        capabilities: ClientCapabilities {
            general: Some(GeneralClientCapabilities {
                position_encodings: encs,
                ..GeneralClientCapabilities::default()
            }),
            ..ClientCapabilities::default()
        },
        ..InitializeParams::default()
    };
    let with_encodings =
        |encs: Option<Vec<PositionEncodingKind>>| negotiate_position_encoding(&params_with(encs));
    // Client offers UTF-16 → advertise it explicitly.
    assert_eq!(
        with_encodings(Some(vec![PositionEncodingKind::UTF16])),
        Some(PositionEncodingKind::UTF16)
    );
    // Client lists only UTF-8 → don't advertise an encoding it can't
    // honour; omitting it falls back to the UTF-16 default.
    assert_eq!(with_encodings(Some(vec![PositionEncodingKind::UTF8])), None);
    // No `general` capability at all → omit (default UTF-16).
    assert_eq!(
        negotiate_position_encoding(&InitializeParams::default()),
        None
    );

    // `client_lacks_utf16_support`: only true for a non-empty list that
    // omits UTF-16 — the case `initialize` warns about.
    assert!(client_lacks_utf16_support(&params_with(Some(vec![
        PositionEncodingKind::UTF8
    ]))));
    assert!(client_lacks_utf16_support(&params_with(Some(vec![
        PositionEncodingKind::UTF8,
        PositionEncodingKind::UTF32,
    ]))));
    // A list containing UTF-16, an empty list, and no list at all are all
    // fine — UTF-16 is available (or defaulted) so no warning fires.
    assert!(!client_lacks_utf16_support(&params_with(Some(vec![
        PositionEncodingKind::UTF8,
        PositionEncodingKind::UTF16,
    ]))));
    assert!(!client_lacks_utf16_support(&params_with(Some(vec![]))));
    assert!(!client_lacks_utf16_support(&InitializeParams::default()));
}

#[test]
fn pull_diagnostic_capability_detection() {
    use tower_lsp_server::ls_types::{
        ClientCapabilities, DiagnosticClientCapabilities, TextDocumentClientCapabilities,
    };
    // No `textDocument.diagnostic` → push-only client (no pull).
    assert!(!client_supports_pull_diagnostics(
        &InitializeParams::default()
    ));
    // A client advertising `textDocument/diagnostic` support → pull-capable,
    // so the worker must stop pushing to avoid a double display.
    let pull_params = InitializeParams {
        capabilities: ClientCapabilities {
            text_document: Some(TextDocumentClientCapabilities {
                diagnostic: Some(DiagnosticClientCapabilities::default()),
                ..TextDocumentClientCapabilities::default()
            }),
            ..ClientCapabilities::default()
        },
        ..InitializeParams::default()
    };
    assert!(client_supports_pull_diagnostics(&pull_params));
}

#[test]
fn relative_watch_pattern_capability_detection() {
    use tower_lsp_server::ls_types::{
        ClientCapabilities, DidChangeWatchedFilesClientCapabilities, WorkspaceClientCapabilities,
    };
    let params_with = |support: Option<bool>| InitializeParams {
        capabilities: ClientCapabilities {
            workspace: Some(WorkspaceClientCapabilities {
                did_change_watched_files: Some(DidChangeWatchedFilesClientCapabilities {
                    relative_pattern_support: support,
                    ..DidChangeWatchedFilesClientCapabilities::default()
                }),
                ..WorkspaceClientCapabilities::default()
            }),
            ..ClientCapabilities::default()
        },
        ..InitializeParams::default()
    };
    // Only an explicit `true` earns an external-pack watcher: handed a
    // bare absolute pattern instead, a client without relative patterns
    // matches it against the workspace and watches the whole project.
    assert!(client_supports_relative_watch_patterns(&params_with(Some(
        true
    ))));
    assert!(!client_supports_relative_watch_patterns(&params_with(
        Some(false)
    )));
    // Field absent, `didChangeWatchedFiles` absent, and no `workspace`
    // capability at all all mean "cannot express a base URI".
    assert!(!client_supports_relative_watch_patterns(&params_with(None)));
    assert!(!client_supports_relative_watch_patterns(
        &InitializeParams {
            capabilities: ClientCapabilities {
                workspace: Some(WorkspaceClientCapabilities::default()),
                ..ClientCapabilities::default()
            },
            ..InitializeParams::default()
        }
    ));
    assert!(!client_supports_relative_watch_patterns(
        &InitializeParams::default()
    ));
}

#[test]
fn message_capability_detection() {
    use tower_lsp_server::ls_types::{
        ClientCapabilities, MessageActionItemCapabilities, ShowDocumentClientCapabilities,
        ShowMessageRequestClientCapabilities, WindowClientCapabilities,
    };
    let params_with = |window: Option<WindowClientCapabilities>| InitializeParams {
        capabilities: ClientCapabilities {
            window,
            ..ClientCapabilities::default()
        },
        ..InitializeParams::default()
    };
    let none = InitializeParams::default();
    assert!(!client_supports_message_action_items(&none));
    assert!(!client_supports_show_document(&none));

    // `showMessage` without `messageActionItem` cannot render actions.
    let bare_show_message = params_with(Some(WindowClientCapabilities {
        show_message: Some(ShowMessageRequestClientCapabilities::default()),
        ..WindowClientCapabilities::default()
    }));
    assert!(!client_supports_message_action_items(&bare_show_message));

    let actions = params_with(Some(WindowClientCapabilities {
        show_message: Some(ShowMessageRequestClientCapabilities {
            message_action_item: Some(MessageActionItemCapabilities::default()),
        }),
        ..WindowClientCapabilities::default()
    }));
    assert!(client_supports_message_action_items(&actions));
    assert!(!client_supports_show_document(&actions));

    // `showDocument` counts only when its `support` flag is set.
    let document = |support| {
        params_with(Some(WindowClientCapabilities {
            show_document: Some(ShowDocumentClientCapabilities { support }),
            ..WindowClientCapabilities::default()
        }))
    };
    assert!(client_supports_show_document(&document(true)));
    assert!(!client_supports_show_document(&document(false)));
}

#[test]
fn environment_kind_setting_is_read_from_every_payload_shape() {
    let off = Some(false);
    // Nested under `tclLsp`, unwrapped, and flat-dotted.
    for payload in [
        serde_json::json!({ "tclLsp": { "notifications": { "environmentKind": false } } }),
        serde_json::json!({ "notifications": { "environmentKind": false } }),
        serde_json::json!({ "tclLsp.notifications.environmentKind": false }),
    ] {
        assert_eq!(
            settings_environment_kind_enabled(&payload),
            off,
            "{payload}"
        );
    }
    assert_eq!(
        settings_environment_kind_enabled(
            &serde_json::json!({ "tclLsp": { "notifications": { "environmentKind": true } } })
        ),
        Some(true)
    );
    // Anything else says nothing, so the current value stands.
    for payload in [
        serde_json::json!({}),
        serde_json::json!({ "tclLsp": { "notifications": {} } }),
        serde_json::json!({ "notifications": { "highlightingHealth": false } }),
        serde_json::json!({ "notifications": { "environmentKind": "no" } }),
        serde_json::Value::Null,
    ] {
        assert_eq!(
            settings_environment_kind_enabled(&payload),
            None,
            "{payload}"
        );
    }
}

#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
async fn environment_kind_setting_reaches_the_notice() {
    let backend = test_backend();
    assert!(backend.environment_notice.enabled(), "on unless set off");
    backend
        .apply_global_config(&serde_json::json!({ "notifications": { "environmentKind": false } }))
        .await
        .unwrap();
    assert!(!backend.environment_notice.enabled());
    // A pull that does not carry the key leaves the last value in force.
    backend
        .apply_global_config(&serde_json::json!({}))
        .await
        .unwrap();
    assert!(!backend.environment_notice.enabled());
    backend
        .apply_global_config(&serde_json::json!({ "notifications": { "environmentKind": true } }))
        .await
        .unwrap();
    assert!(backend.environment_notice.enabled());
}

#[test]
fn feature_toggles_default_on_and_merge() {
    let mut toggles = FeatureToggles::default();
    // Absent keys default to enabled.
    assert!(toggles.is_enabled("hover"));
    assert!(toggles.is_enabled("completion"));
    // Applying a partial `features` object sets only the named keys.
    let features = serde_json::json!({"hover": false, "folding": false});
    toggles.apply(features.as_object().unwrap());
    assert!(!toggles.is_enabled("hover"));
    assert!(!toggles.is_enabled("folding"));
    // Unnamed keys keep their default-on value.
    assert!(toggles.is_enabled("completion"));
    // Re-enabling merges (does not reset the rest).
    toggles.apply(serde_json::json!({"hover": true}).as_object().unwrap());
    assert!(toggles.is_enabled("hover"));
    assert!(!toggles.is_enabled("folding"));
}

#[test]
fn inlay_keys_default_off() {
    // The opt-in inlay families default off, so `getEffectiveConfig`
    // reports them disabled until an editor sets them (matching the
    // handler's default-off gate).
    let toggles = FeatureToggles::default();
    assert!(!toggles.is_enabled("inlayTypeHints"));
    assert!(!toggles.is_enabled("inlayParameterHints"));
    let map = toggles.resolved_map();
    assert_eq!(
        map.get("inlayTypeHints")
            .and_then(serde_json::Value::as_bool),
        Some(false)
    );
    assert_eq!(
        map.get("inlayParameterHints")
            .and_then(serde_json::Value::as_bool),
        Some(false),
    );
}

#[test]
fn legacy_inlay_hints_key_maps_to_type_family() {
    // The retired `inlayHints` key maps to `inlayTypeHints`: an existing
    // explicit opt-in keeps showing the
    // inferred-variable-type hints after the rename, while the verbose
    // parameter-name hints stay off.
    let mut toggles = FeatureToggles::default();
    toggles.apply(serde_json::json!({"inlayHints": true}).as_object().unwrap());
    assert!(toggles.is_enabled("inlayTypeHints"));
    // It does not touch the parameter-name family.
    assert!(!toggles.is_enabled("inlayParameterHints"));
}

#[test]
fn explicit_new_inlay_key_wins_over_legacy_alias() {
    // When a config carries both, the explicit new `inlayTypeHints` key
    // takes precedence over the `inlayHints` alias.
    let mut toggles = FeatureToggles::default();
    toggles.apply(
        serde_json::json!({"inlayHints": true, "inlayTypeHints": false})
            .as_object()
            .unwrap(),
    );
    assert!(!toggles.is_enabled("inlayTypeHints"));
}

