/// A single `did_change_watched_files` event batch carrying a CREATED, a
/// CHANGED and a DELETED file together must land on the same end state a
/// one-file-at-a-time serial path would produce — the
/// `workspace_index` and salsa db reflecting exactly the final on-disk
/// population, in one batched pass rather than three sequential full
/// analyses.
#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
async fn watched_files_batch_applies_created_changed_and_deleted_together() {
    let root = unique_scratch_dir("watched-batch");
    let created_path = root.join("created.tcl");
    let changed_path = root.join("changed.tcl");
    let deleted_path = root.join("deleted.tcl");
    std::fs::write(&created_path, "proc created_proc {} {}\n").unwrap();
    std::fs::write(&changed_path, "proc changed_proc {} {}\n").unwrap();
    std::fs::write(&deleted_path, "proc deleted_proc {} {}\n").unwrap();

    let backend = test_backend();
    let created_uri = Uri::from_file_path(&created_path).unwrap();
    let changed_uri = Uri::from_file_path(&changed_path).unwrap();
    let deleted_uri = Uri::from_file_path(&deleted_path).unwrap();

    // Seed the pre-event state: `changed.tcl` and `deleted.tcl` are
    // already indexed (as a prior scan would have left them) under their
    // *old* content — `changed.tcl`'s on-disk copy above is already the
    // new content, standing in for the edit the CHANGED event reports;
    // `deleted.tcl`'s on-disk file is removed below before the event
    // fires, standing in for the delete. `created.tcl` starts entirely
    // unindexed.
    for (uri, old_src) in [
        (&changed_uri, "proc old_changed_proc {} {}\n"),
        (&deleted_uri, "proc deleted_proc {} {}\n"),
    ] {
        backend
            .db_set_source(uri, old_src, "tcl8.6".to_owned())
            .await
            .unwrap();
        let mut analyser = Analyser::new();
        let analysis = analyser.analyse(old_src, "tcl8.6").clone();
        backend
            .workspace_index
            .write()
            .await
            .add_document(uri.as_str(), &analysis);
    }
    std::fs::remove_file(&deleted_path).unwrap();

    backend
        .did_change_watched_files(DidChangeWatchedFilesParams {
            changes: vec![
                tower_lsp_server::ls_types::FileEvent {
                    uri: created_uri.clone(),
                    typ: FileChangeType::CREATED,
                },
                tower_lsp_server::ls_types::FileEvent {
                    uri: changed_uri.clone(),
                    typ: FileChangeType::CHANGED,
                },
                tower_lsp_server::ls_types::FileEvent {
                    uri: deleted_uri.clone(),
                    typ: FileChangeType::DELETED,
                },
            ],
        })
        .await;

    let index = backend.workspace_index.read().await;
    assert!(
        !index
            .proc_definitions("created_proc", "created_proc")
            .is_empty(),
        "the CREATED file must be indexed",
    );
    assert!(
        !index
            .proc_definitions("changed_proc", "changed_proc")
            .is_empty(),
        "the CHANGED file's new content must be indexed",
    );
    assert!(
        index
            .proc_definitions("old_changed_proc", "old_changed_proc")
            .is_empty(),
        "the CHANGED file's stale content must not survive the batch",
    );
    assert!(
        index
            .proc_definitions("deleted_proc", "deleted_proc")
            .is_empty(),
        "the DELETED file must be dropped from the index",
    );
    drop(index);

    let files = backend.db_files.lock().await;
    assert!(
        files.contains_key(&created_uri),
        "the CREATED file must gain a salsa SourceFile input",
    );
    assert!(
        files.contains_key(&changed_uri),
        "the CHANGED file keeps its salsa SourceFile input",
    );
    assert!(
        !files.contains_key(&deleted_uri),
        "the DELETED file's salsa SourceFile input must be retired",
    );
    drop(files);

    std::fs::remove_dir_all(&root).ok();
}

/// Removing a source retires its salsa input with an emptied payload
/// instead of dropping it, and re-creating the same URI revives that handle
/// rather than allocating a second one salsa can never free.
#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
async fn db_remove_source_retires_input_for_reuse() {
    let backend = test_backend();
    let uri = Uri::from_str("file:///retired.tcl").unwrap();
    backend
        .db_set_source(&uri, "proc foo {} {}\n", "tcl8.6".to_owned())
        .await
        .unwrap();
    let first = *backend
        .db_files
        .lock()
        .await
        .get(&uri)
        .expect("the source is tracked once set");

    backend.db_remove_source(&uri).await;

    assert!(
        !backend.db_files.lock().await.contains_key(&uri),
        "a removed source must leave the live file set",
    );
    {
        let db = backend.db.lock().await;
        let tombstones = backend.db_tombstones.lock().await;
        let retired = *tombstones
            .get(&uri)
            .expect("the input must be retired, not dropped — salsa never frees one");
        assert!(retired == first, "the retired handle is the original input");
        assert!(
            retired.text(&*db).is_empty(),
            "a retired input must release its text: {:?}",
            retired.text(&*db),
        );
        assert!(
            retired.external_call_sites(&*db).is_none(),
            "a retired input must release its cross-file evidence",
        );
    }

    backend
        .db_set_source(&uri, "proc bar {} {}\n", "tcl8.6".to_owned())
        .await
        .unwrap();
    let second = *backend
        .db_files
        .lock()
        .await
        .get(&uri)
        .expect("the re-created source is tracked again");
    assert!(
        first == second,
        "re-creating a removed URI must revive its retired input",
    );
    assert!(
        backend.db_tombstones.lock().await.is_empty(),
        "a revived input must leave the tombstone map",
    );
    // The revived handle carries the new text and is the project's only file.
    {
        let db = backend.db.lock().await;
        assert_eq!(second.text(&*db), "proc bar {} {}\n");
        let project = backend.db_project.lock().await;
        let files = project
            .expect("a project exists once a file is tracked")
            .files(&*db);
        assert!(
            files.as_slice() == [second],
            "the project file set must hold exactly the one live input",
        );
    }
}

/// Publication admission is not a failed fixed-point computation. A
/// factory waiter must release all publisher locks until intent retires.
#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
async fn factory_round_waits_for_snapshot_admission_without_holding_locks() {
    let backend = test_backend();
    let uri = Uri::from_str("file:///factory-snapshot-admission.tcl").unwrap();
    backend
        .db_set_source(&uri, "set value 1\n", "tcl8.6".to_owned())
        .await
        .unwrap();
    let handles = EvidenceHandles {
        db_config: Arc::clone(&backend.db_config),
        folder_db_configs: Arc::clone(&backend.folder_db_configs),
        db: Arc::clone(&backend.db),
        db_files: Arc::clone(&backend.db_files),
        db_project_members: Arc::clone(&backend.db_project_members),
        db_project: Arc::clone(&backend.db_project),
        workspace_index: Arc::clone(&backend.workspace_index),
        documents: Arc::clone(&backend.documents),
        rehoming_gate: Arc::clone(&backend.rehoming_gate),
        live_publication_gate: Arc::clone(&backend.live_publication_gate),
        class_factory_generation: Arc::clone(&backend.class_factory_generation),
    };
    let publication = backend.db.begin_snapshot_drain();
    let round = sync_workspace_class_factories_round(&handles);
    tokio::pin!(round);
    std::future::poll_fn(|context| {
        assert!(std::future::Future::poll(round.as_mut(), context).is_pending());
        std::task::Poll::Ready(())
    })
    .await;
    assert_eq!(backend.db.snapshot_report().outstanding, 0);
    crate::rt::timeout(std::time::Duration::from_secs(5), async {
        let _db = backend.db.lock().await;
        let _files = backend.db_files.lock().await;
        let project = backend.db_project.lock().await;
        assert!(project.is_some());
    })
    .await
    .expect("a pending factory reader must release publication locks");
    drop(publication);
    let outcome = crate::rt::timeout(std::time::Duration::from_secs(5), round)
        .await
        .expect("the original factory round must resume after publication");
    assert!(matches!(outcome, ClassFactoryRound::Settled));
}

/// The project-wide evidence read runs on a cloned salsa snapshot off the
/// `db` mutex, so the write section has to re-check
/// currency against the live database rather than trusting the snapshot's
/// view.  A second pass over an unchanged project must therefore write
/// nothing — no input moves, nothing downstream is invalidated, and no peer
/// is rescheduled — which is also what stops the worker/peer loop from
/// running forever.
#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
async fn cross_file_evidence_sync_settles_after_one_pass() {
    let backend = test_backend();
    let lib = Uri::from_str("file:///w/lib.tcl").unwrap();
    let main = Uri::from_str("file:///w/main.tcl").unwrap();
    backend
        .db_set_source(
            &lib,
            "proc helper {mode} { return $mode }\n",
            "tcl8.6".to_owned(),
        )
        .await
        .unwrap();
    backend
        .db_set_source(&main, "helper dev\n", "tcl8.6".to_owned())
        .await
        .unwrap();
    let handles = EvidenceHandles {
        db_config: Arc::clone(&backend.db_config),
        folder_db_configs: Arc::clone(&backend.folder_db_configs),
        db: Arc::clone(&backend.db),
        db_files: Arc::clone(&backend.db_files),
        db_project_members: Arc::clone(&backend.db_project_members),
        db_project: Arc::clone(&backend.db_project),
        workspace_index: Arc::clone(&backend.workspace_index),
        documents: Arc::clone(&backend.documents),
        rehoming_gate: Arc::clone(&backend.rehoming_gate),
        live_publication_gate: Arc::clone(&backend.live_publication_gate),
        class_factory_generation: Arc::clone(&backend.class_factory_generation),
    };

    let first = sync_cross_file_evidence(&handles).await;
    assert_eq!(
        first.changed.len(),
        2,
        "the cold pass gives both covered files a view: {:?}",
        first.changed,
    );
    let second = sync_cross_file_evidence(&handles).await;
    assert!(
        second.changed.is_empty(),
        "an unchanged project must write no input: {:?}",
        second.changed,
    );

    let db = backend.db.lock().await;
    let files = backend.db_files.lock().await;
    let evidence = files[&lib]
        .external_call_sites(&*db)
        .clone()
        .expect("a covered file gets a view");
    assert_eq!(
        evidence.callees().collect::<Vec<_>>(),
        vec!["::helper"],
        "main.tcl's call reaches lib.tcl's proc"
    );
}

/// Coverage and cross-file evidence must read
/// the same Salsa revision. Ordinary edits intentionally retain the prior
/// workspace-index slot until diagnostics republishes it, so an old
/// literal target there must not hide a new external target in Salsa.
#[tokio::test]
async fn covered_load_targets_use_the_captured_salsa_revision_1854() {
    use salsa::Setter as _;

    let backend = test_backend();
    let main = Uri::from_str("file:///w/main.tcl").unwrap();
    let target = Uri::from_str("file:///w/target.tcl").unwrap();
    backend
        .db_set_source(&main, "source target.tcl\n", "tcl8.6".to_owned())
        .await
        .unwrap();
    backend
        .db_set_source(&target, "proc target {} {}\n", "tcl8.6".to_owned())
        .await
        .unwrap();
    let analysis = Analyser::new()
        .analyse("source target.tcl\n", "tcl8.6")
        .clone();
    backend
        .workspace_index
        .write()
        .await
        .replace_document(main.as_str(), &analysis);
    {
        let mut db = backend.db.lock().await;
        let files = backend.db_files.lock().await;
        files[&main]
            .set_text(&mut *db)
            .to("source ../outside.tcl\n".to_owned());
    }
    assert_eq!(
        backend.workspace_index.read().await.sources().count(),
        1,
        "the regression requires the previous covered index view",
    );
    let handles = EvidenceHandles {
        db_config: Arc::clone(&backend.db_config),
        folder_db_configs: Arc::clone(&backend.folder_db_configs),
        db: Arc::clone(&backend.db),
        db_files: Arc::clone(&backend.db_files),
        db_project_members: Arc::clone(&backend.db_project_members),
        db_project: Arc::clone(&backend.db_project),
        workspace_index: Arc::clone(&backend.workspace_index),
        documents: Arc::clone(&backend.documents),
        rehoming_gate: Arc::clone(&backend.rehoming_gate),
        live_publication_gate: Arc::clone(&backend.live_publication_gate),
        class_factory_generation: Arc::clone(&backend.class_factory_generation),
    };
    let captured = capture_cross_file_evidence_snapshot(&handles)
        .await
        .expect("the project must remain initialised");
    let covered = files_with_covered_load_targets(
        &captured.snapshot,
        &captured.files,
        &captured.members,
        captured.project,
    );
    assert!(
        !covered.contains(&main),
        "the current external target must defeat the stale covered index view",
    );
}

/// Diagnostics for the driving document are computed before evidence
/// refresh. If its new text turns a covered
/// `source` into an external one, losing `Some(evidence)` must schedule the
/// second pass that withdraws any fold made from that stale closed world.
#[tokio::test]
async fn coverage_loss_marks_the_driving_diagnostics_dirty_1854() {
    use salsa::Setter as _;

    let backend = test_backend();
    let main = Uri::from_str("file:///w/coverage-loss-main-1854.tcl").unwrap();
    let target = Uri::from_str("file:///w/coverage-loss-target-1854.tcl").unwrap();
    backend
        .db_set_source(
            &main,
            "source coverage-loss-target-1854.tcl\n",
            "tcl8.6".to_owned(),
        )
        .await
        .unwrap();
    backend
        .db_set_source(&target, "proc target {} {}\n", "tcl8.6".to_owned())
        .await
        .unwrap();
    let handles = EvidenceHandles {
        db_config: Arc::clone(&backend.db_config),
        folder_db_configs: Arc::clone(&backend.folder_db_configs),
        db: Arc::clone(&backend.db),
        db_files: Arc::clone(&backend.db_files),
        db_project_members: Arc::clone(&backend.db_project_members),
        db_project: Arc::clone(&backend.db_project),
        workspace_index: Arc::clone(&backend.workspace_index),
        documents: Arc::clone(&backend.documents),
        rehoming_gate: Arc::clone(&backend.rehoming_gate),
        live_publication_gate: Arc::clone(&backend.live_publication_gate),
        class_factory_generation: Arc::clone(&backend.class_factory_generation),
    };
    let initial = sync_cross_file_evidence(&handles).await;
    assert!(initial.changed.contains(&main));
    {
        let mut db = backend.db.lock().await;
        let files = backend.db_files.lock().await;
        assert!(files[&main].external_call_sites(&*db).is_some());
        files[&main]
            .set_text(&mut *db)
            .to("source ../outside.tcl\n".to_owned());
    }
    let slots = Arc::new(Mutex::new(HashMap::from([(
        main.clone(),
        DiagSlot::default(),
    )])));

    refresh_cross_file_evidence(&handles, &slots, &main).await;

    assert!(
        slots.lock().await[&main].dirty,
        "coverage loss must schedule the driving document's soundness pass",
    );
}

/// The evaluator epoch reaches the query database after a diagnostics
/// pass. A hook quarantined on a worker thread moves the process's
/// epoch, and nothing a query reads says so; the refresh that follows the
/// pass takes it, compare-then-set, and reschedules nothing for it. That
/// the input re-keys the memoised lattices is `tcl-lsp-db`'s
/// `an_evaluator_epoch_re_keys_the_memoised_lattices`.
#[tokio::test]
async fn the_pass_after_a_quarantine_takes_the_evaluator_epoch() {
    let backend = test_backend();
    let uri = Uri::from_str("file:///w/evaluator-epoch-d104.tcl").unwrap();
    backend
        .db_set_source(&uri, "proc p {} {return 1}\n", "tcl8.6".to_owned())
        .await
        .unwrap();
    let taken = || async {
        let db = backend.db.lock().await;
        tcl_lsp_db::EvaluatorEpoch::try_get(&*db).map(|epoch| epoch.generation(&*db))
    };
    std::thread::spawn(tcl_registry::pack_hooks::note_quarantine)
        .join()
        .expect("the worker quarantined");
    let moved = tcl_registry::pack_hooks::evaluator_epoch();
    assert!(
        taken().await.is_some_and(|epoch| epoch < moved),
        "the database has not seen the quarantine"
    );
    let handles = EvidenceHandles {
        db_config: Arc::clone(&backend.db_config),
        folder_db_configs: Arc::clone(&backend.folder_db_configs),
        db: Arc::clone(&backend.db),
        db_files: Arc::clone(&backend.db_files),
        db_project_members: Arc::clone(&backend.db_project_members),
        db_project: Arc::clone(&backend.db_project),
        workspace_index: Arc::clone(&backend.workspace_index),
        documents: Arc::clone(&backend.documents),
        rehoming_gate: Arc::clone(&backend.rehoming_gate),
        live_publication_gate: Arc::clone(&backend.live_publication_gate),
        class_factory_generation: Arc::clone(&backend.class_factory_generation),
    };
    let slots = Arc::new(Mutex::new(HashMap::from([(
        uri.clone(),
        DiagSlot::default(),
    )])));

    refresh_cross_file_evidence(&handles, &slots, &uri).await;

    assert!(
        taken().await.is_some_and(|epoch| epoch >= moved),
        "the refresh after the pass takes the moved epoch"
    );
    assert!(
        !slots.lock().await[&uri].dirty,
        "and reschedules nothing for it"
    );
}

