/// A folder whose override set empties retires its `AnalyserConfig`
/// handle (payload cleared) and revives it when the override comes back —
/// `.tcl-lsp.ini` churn must not allocate a config input per save.
#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
async fn folder_db_config_handle_is_retired_and_revived() {
    let backend = test_backend();
    let folder = Uri::from_str("file:///proj-a").unwrap();
    *backend.workspace_folders.lock().await = vec![folder.clone()];
    let overriding = || FolderConfig {
        disabled_diagnostics: Some(std::iter::once("W100".to_owned()).collect()),
        ..FolderConfig::default()
    };

    backend
        .apply_folder_configs(vec![(folder.clone(), overriding())])
        .await;
    let first = backend
        .folder_db_configs
        .lock()
        .await
        .iter()
        .find(|(u, _)| u == &folder)
        .map(|(_, handle)| *handle)
        .expect("an overriding folder gets its own AnalyserConfig handle");

    // The next re-pull drops the override, so the folder needs no handle.
    backend
        .apply_folder_configs(vec![(folder.clone(), FolderConfig::default())])
        .await;
    assert!(
        backend.folder_db_configs.lock().await.is_empty(),
        "a folder with no overrides must not keep a live handle",
    );
    {
        let db = backend.db.lock().await;
        let tombstones = backend.folder_db_config_tombstones.lock().await;
        let retired = *tombstones
            .get(&folder)
            .expect("the handle must be retired, not dropped");
        assert!(retired == first, "the retired handle is the original input");
        assert!(
            retired.disabled_diagnostics(&*db).is_empty(),
            "a retired config must release its code list",
        );
    }

    // Re-enabling the override revives the retired handle.
    backend
        .apply_folder_configs(vec![(folder.clone(), overriding())])
        .await;
    let second = backend
        .folder_db_configs
        .lock()
        .await
        .iter()
        .find(|(u, _)| u == &folder)
        .map(|(_, handle)| *handle)
        .expect("the re-enabled folder has a handle again");
    assert!(
        first == second,
        "re-enabling an override must revive the retired config input",
    );
    assert!(
        backend.folder_db_config_tombstones.lock().await.is_empty(),
        "a revived config must leave the tombstone map",
    );
}

#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
async fn did_change_on_unopened_document_is_dropped() {
    // Notification handlers run concurrently, so a
    // `didChange` can be processed before its `didOpen` or after its
    // `didClose`. It must NOT resurrect/create a phantom document.
    let backend = test_backend();
    let uri = Uri::from_str("file:///phantom.tcl").unwrap();
    backend
        .did_change(DidChangeTextDocumentParams {
            text_document: tower_lsp_server::ls_types::VersionedTextDocumentIdentifier {
                uri: uri.clone(),
                version: 5,
            },
            content_changes: vec![tower_lsp_server::ls_types::TextDocumentContentChangeEvent {
                range: None,
                range_length: None,
                text: "set y 2\n".to_owned(),
            }],
        })
        .await;
    assert!(
        !backend.documents.lock("test").await.contains_key(&uri),
        "did_change on an unopened URI must not create a document",
    );
}

#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
async fn selection_range_returns_one_entry_per_position() {
    // The LSP spec requires `result[i]` to answer
    // `positions[i]`. Any position that yields no chain must still produce
    // a range (a degenerate fallback at the cursor) rather than being
    // dropped, which would misalign every later cursor in a multi-cursor
    // Expand Selection. Assert the handler always returns exactly one range
    // per requested position, including out-of-range cursors.
    let backend = test_backend();
    let uri = Uri::from_str("file:///sel.tcl").unwrap();
    register(&backend, &uri, "set x 1\n").await;
    let positions = vec![
        Position::new(0, 4),  // on `x`
        Position::new(99, 0), // far past the buffer
        Position::new(0, 0),  // line start
    ];
    let result = backend
        .selection_range(SelectionRangeParams {
            work_done_progress_params: WorkDoneProgressParams::default(),
            partial_result_params: PartialResultParams::default(),
            text_document: TextDocumentIdentifier { uri: uri.clone() },
            positions: positions.clone(),
        })
        .await
        .expect("ok")
        .expect("some");
    assert_eq!(
        result.len(),
        positions.len(),
        "one selection range per requested position",
    );
}

#[test]
fn materialise_selection_range_none_falls_back_to_cursor() {
    // The fallback the handler applies when a position yields no chain:
    // `materialise_selection_range` returns `None` for an empty chain, and
    // the handler substitutes a degenerate range at the cursor so the
    // position is never dropped.
    assert!(materialise_selection_range(&[]).is_none());
}

#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
async fn did_change_configuration_applies_inline_settings() {
    let backend = test_backend();
    let params = DidChangeConfigurationParams {
        settings: serde_json::json!({
            "dialect": "tcl9.0",
            "tclLsp.style.nonAscii": "strict",
            "tclLsp.diagnostics.W211": false,
        }),
    };
    // `did_change_configuration` ends by pulling config from the client,
    // which errors fast against the test's detached socket; the timeout is
    // a backstop so a future transport change can't hang the suite.
    crate::rt::timeout(
        std::time::Duration::from_secs(10),
        backend.did_change_configuration(params),
    )
    .await
    .expect("did_change_configuration should not hang");
    assert_eq!(*backend.default_dialect.lock().await, "tcl9.0");
    assert_eq!(*backend.non_ascii_mode.lock().await, NonAsciiMode::Strict);
    assert!(
        backend.disabled_diagnostics.lock().await.contains("W211"),
        "W211 should be disabled by the inline settings",
    );
}

/// The editor's Workspace Trust state reaches pack discovery from the two
/// places a client states it — `initializationOptions.workspaceTrust` and a
/// top-level `workspaceTrust` push — and from nowhere a workspace's own
/// settings file can write. The negative: `tclLsp.workspaceTrust` inside
/// a pushed `tclLsp` section (what VS Code's configuration sync sends, from
/// every settings layer) changes nothing. A client that says nothing is
/// trusted.
#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
async fn workspace_trust_comes_from_the_client_and_never_from_a_setting() {
    use tcl_dialect::model::WorkspaceTrust;
    let owned = test_backend();
    let backend = &owned;
    let trust = move || async move { backend.spec_pack_discovery().await.workspace_trust };
    assert_eq!(trust().await, WorkspaceTrust::Trusted, "absent is trusted");

    backend
        .apply_initialization_options(&InitializeParams {
            initialization_options: Some(serde_json::json!({
                "workspaceTrust": "untrusted",
            })),
            ..InitializeParams::default()
        })
        .await;
    assert_eq!(trust().await, WorkspaceTrust::Untrusted);

    // Each push ends in the coalesced configuration reload, which fails
    // fast against the detached socket; the timeout is a backstop.
    let push = move |settings: serde_json::Value| {
        crate::rt::timeout(
            std::time::Duration::from_secs(60),
            backend.did_change_configuration(DidChangeConfigurationParams { settings }),
        )
    };
    push(serde_json::json!({ "tclLsp": { "workspaceTrust": "trusted" } }))
        .await
        .expect("did_change_configuration should not hang");
    push(serde_json::json!({ "tclLsp.workspaceTrust": "trusted" }))
        .await
        .expect("did_change_configuration should not hang");
    assert_eq!(
        trust().await,
        WorkspaceTrust::Untrusted,
        "a synchronised setting cannot grant trust"
    );

    push(serde_json::json!({ "workspaceTrust": "trusted" }))
        .await
        .expect("did_change_configuration should not hang");
    assert_eq!(trust().await, WorkspaceTrust::Trusted, "the client's grant");
    push(serde_json::json!({ "workspaceTrust": "sometimes" }))
        .await
        .expect("did_change_configuration should not hang");
    assert_eq!(
        trust().await,
        WorkspaceTrust::Trusted,
        "an unreadable value is no statement"
    );
}

/// A burst of `didChangeConfiguration` notifications must
/// coalesce into a single reload.  The leader is the only handler that runs
/// the pipeline; every other notification in the window returns straight
/// away after applying its inline settings.
#[tokio::test(flavor = "multi_thread", worker_threads = 4)]
async fn a_configuration_burst_coalesces_into_one_reload() {
    let backend = test_backend();
    let notify = |dialect: &str| DidChangeConfigurationParams {
        settings: serde_json::json!({ "dialect": dialect }),
    };
    // `tower_lsp_server` drives notifications concurrently
    // (`buffer_unordered`, see `EditOrder`), so the burst is modelled that
    // way: one handler becomes the leader and parks for the debounce
    // window, and the other fifteen land while it is parked.
    let leader = backend.did_change_configuration(notify("tcl8.4"));
    let dialects = ["tcl8.5", "tcl8.6", "tcl9.0"];
    let followers = async {
        // Let the leader claim the slot before the followers arrive.
        crate::rt::sleep(std::time::Duration::from_millis(10)).await;
        let start = std::time::Instant::now();
        for i in 0..15 {
            backend
                .did_change_configuration(notify(dialects[i % dialects.len()]))
                .await;
        }
        // The whole point: a follower applies its inline settings and
        // returns — it never waits for a pull, let alone its own window.
        assert!(
            start.elapsed() < CONFIG_RELOAD_DEBOUNCE,
            "followers must not each wait out a debounce window: {:?}",
            start.elapsed(),
        );
        // All fifteen are folded into the single pending generation.
        let slot = backend.config_reload.lock().await;
        assert!(slot.running, "exactly one leader owns the reload");
        assert!(slot.dirty, "the burst is pending for that leader");
    };
    tokio::join!(leader, followers);

    // The leader has run the pipeline and retired, and the state it settled
    // on is the *last* notification's — a superseded generation may be
    // dropped, the final one never may.
    {
        let slot = backend.config_reload.lock().await;
        assert!(
            !slot.running,
            "the leader must retire once the burst drains"
        );
        assert!(!slot.dirty);
    }
    assert_eq!(*backend.default_dialect.lock().await, "tcl9.0");
}

/// The coalescing must not swallow the final generation: after the window
/// closes the leader runs the pipeline and retires.
#[tokio::test(flavor = "multi_thread", worker_threads = 4)]
async fn the_last_generation_of_a_burst_still_runs_to_completion() {
    let backend = test_backend();
    for _ in 0..4 {
        backend
            .did_change_configuration(DidChangeConfigurationParams {
                settings: serde_json::json!({ "dialect": "tcl9.0" }),
            })
            .await;
    }
    // The leader is still sleeping out its window; wait for it to run and
    // then retire. `client.configuration` errors fast against the test's
    // detached socket, so the pipeline completes rather than hanging.
    let retired = wait_for(|| async {
        let slot = backend.config_reload.lock().await;
        !slot.running && !slot.dirty
    })
    .await;
    assert!(retired, "the leader must run the reload and then retire");
    assert_eq!(*backend.default_dialect.lock().await, "tcl9.0");
}

/// A deliberate session override outranks the configured default and
/// survives a configuration pull.
#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
async fn a_session_dialect_override_survives_a_config_pull() {
    let backend = test_backend();
    backend
        .set_session_dialect_override_command(&[serde_json::json!("f5-irules")])
        .await
        .expect("override command");
    assert_eq!(backend.session_dialect().await, "f5-irules");

    // A pulled/pushed `tclLsp.dialect` rewrites the *configured* default …
    backend
        .apply_global_config(&serde_json::json!({ "dialect": "tcl9.0" }))
        .await
        .unwrap();
    assert_eq!(*backend.default_dialect.lock().await, "tcl9.0");
    // … and must leave the override in force.
    assert_eq!(
        backend.session_dialect().await,
        "f5-irules",
        "a config pull must not revert a deliberate session override",
    );

    // Clearing hands the session back to the configured value.
    backend
        .set_session_dialect_override_command(&[])
        .await
        .expect("clear command");
    assert_eq!(backend.session_dialect().await, "tcl9.0");
}

/// An unknown dialect is rejected rather than installed.
#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
async fn a_session_dialect_override_rejects_an_unknown_dialect() {
    let backend = test_backend();
    let reply = backend
        .set_session_dialect_override_command(&[serde_json::json!("tcl99")])
        .await
        .expect("override command")
        .expect("a reply");
    assert_eq!(reply["success"], serde_json::json!(false), "{reply}");
    assert!(backend.session_dialect_override.lock().await.is_none());
}

/// The override sits in the session-fallback tier, so it reaches a document
/// whose dialect is not pinned by anything stronger — and nothing else.
#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
async fn a_session_dialect_override_only_reaches_the_fallback_tier() {
    let backend = test_backend();
    backend
        .set_session_dialect_override_command(&[serde_json::json!("f5-irules")])
        .await
        .expect("override command");
    let plain = Uri::from_str("file:///plain.tcl").unwrap();
    assert_eq!(
        backend.dialect_for_open(&plain, "", "set x 1\n").await,
        "f5-irules",
        "an unpinned document falls back to the override",
    );
    // An explicit language id still wins, exactly as it does over the
    // configured default.
    assert_eq!(
        backend.dialect_for_open(&plain, "tcl90", "set x 1\n").await,
        "tcl9.0",
        "an explicit language id must still outrank the session tier",
    );
}

/// A per-document override is the strongest tier — stronger
/// than an explicit language id and than the in-source directive — and it
/// reaches only the document it names.
#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
async fn a_document_dialect_override_outranks_every_inference() {
    let backend = test_backend();
    let sample = Uri::from_str("file:///studio/test.tcl").unwrap();
    let sibling = Uri::from_str("file:///studio/other.tcl").unwrap();
    backend
        .set_document_dialect_override_command(&[
            serde_json::json!(sample.as_str()),
            serde_json::json!("f5-irules"),
        ])
        .await
        .expect("override command");

    assert_eq!(
        backend.dialect_for_open(&sample, "tcl", "set x 1\n").await,
        "f5-irules",
        "the named document takes the override",
    );
    assert_eq!(
        backend
            .dialect_for_open(&sample, "tcl90", "set x 1\n")
            .await,
        "f5-irules",
        "an explicit language id does not outrank a named document",
    );
    assert_eq!(
        backend
            .dialect_for_open(&sample, "tcl", "# tcl-dialect: tcl8.4\n")
            .await,
        "f5-irules",
        "an in-source directive does not outrank a named document",
    );
    assert_eq!(
        backend.dialect_for_open(&sibling, "tcl", "set x 1\n").await,
        "tcl8.6",
        "no other buffer is re-tagged — the whole point of the tier",
    );
}

