#[tokio::test]
async fn dropping_one_factory_reindexes_its_consumers_while_retaining_others() {
    let root = unique_scratch_dir("metaclass-drop-one");
    write_metaclass_workspace(&root);
    std::fs::write(
        root.join("other-factory.tcl"),
        concat!(
            "namespace eval ::other {}\n",
            "oo::class create ::other::Factory {\n",
            "    superclass oo::class\n",
            "    self method create {name body} { next $name $body }\n",
            "}\n",
        ),
    )
    .unwrap();
    std::fs::write(
        root.join("other-consumer.tcl"),
        "::other::Factory create ::Kept { method ok {} {} }\n",
    )
    .unwrap();
    let backend = test_backend();
    *backend.workspace_folders.lock().await = vec![Uri::from_file_path(&root).unwrap()];
    backend.scan_workspace_folders().await.unwrap();
    {
        let index = backend.workspace_index.read().await;
        assert_eq!(index.classes_named("::IconList").len(), 1);
        assert_eq!(index.classes_named("::Kept").len(), 1);
    }

    std::fs::write(root.join("megawidget.tcl"), "# one factory removed\n").unwrap();
    backend.scan_workspace_folders().await.unwrap();

    let index = backend.workspace_index.read().await;
    assert_eq!(
        index.classes_named("::IconList"),
        [] as [&tcl_lsp_core::workspace_index::WorkspaceClass; 0]
    );
    assert_eq!(index.classes_named("::Kept").len(), 1);
    drop(index);
    std::fs::remove_dir_all(&root).ok();
}

#[test]
fn workspace_class_cache_key_covers_bare_word_and_factory_oracles() {
    let classes = HashSet::from(["::Widget".to_owned()]);
    let no_bare_words = HashSet::new();
    let bare_words = HashSet::from(["::Widget".to_owned()]);
    let base = workspace_class_analysis_fingerprint(
        "Widget .w\n",
        tcl_lsp_core::profile_for_dialect("tcl9.0"),
        &classes,
        &no_bare_words,
        None,
    );
    let changed_bare_words = workspace_class_analysis_fingerprint(
        "Widget .w\n",
        tcl_lsp_core::profile_for_dialect("tcl9.0"),
        &classes,
        &bare_words,
        None,
    );
    assert_ne!(base, changed_bare_words);

    let analysis = Analyser::new()
        .analyse("oo::class create Meta { superclass oo::class }\n", "tcl9.0")
        .clone();
    let factories = analysis.class_factories();
    let changed_factories = workspace_class_analysis_fingerprint(
        "Widget .w\n",
        tcl_lsp_core::profile_for_dialect("tcl9.0"),
        &classes,
        &no_bare_words,
        Some(&factories),
    );
    assert_ne!(base, changed_factories);

    let changed_analysis = Analyser::new()
        .analyse(
            concat!(
                "oo::class create Meta {\n",
                "  superclass oo::class\n",
                "  method unknown {w args} {\n",
                "    [self] create ::$w\n",
                "    return $w\n",
                "  }\n",
                "}\n",
            ),
            "tcl9.0",
        )
        .clone();
    let changed_factory_content = changed_analysis.class_factories();
    assert_eq!(
        factories.keys().collect::<Vec<_>>(),
        changed_factory_content.keys().collect::<Vec<_>>()
    );
    assert_ne!(
        workspace_class_analysis_fingerprint(
            "Widget .w\n",
            tcl_lsp_core::profile_for_dialect("tcl9.0"),
            &classes,
            &no_bare_words,
            Some(&factories),
        ),
        workspace_class_analysis_fingerprint(
            "Widget .w\n",
            tcl_lsp_core::profile_for_dialect("tcl9.0"),
            &classes,
            &no_bare_words,
            Some(&changed_factory_content),
        )
    );
}

#[tokio::test]
async fn scan_workspace_folders_skips_open_documents() {
    let root = unique_scratch_dir("scan-open");
    let on_disk = root.join("buf.tcl");
    // The on-disk copy defines `stale`; the live buffer (below)
    // defines `fresh`. After the scan the index must reflect the
    // live buffer, not the on-disk copy.
    std::fs::write(&on_disk, "proc stale {} {}\n").unwrap();

    let backend = test_backend();
    let root_url = Uri::from_file_path(&root).unwrap();
    let uri = Uri::from_file_path(&on_disk).unwrap();
    *backend.workspace_folders.lock().await = vec![root_url];
    backend.documents.lock("test").await.insert(
        uri.clone(),
        DocumentState::new("proc fresh {} {}\n".to_owned(), "tcl8.6".to_owned()),
    );
    // Seed the index from the live buffer the way did_open would.
    {
        let mut analyser = Analyser::new();
        let analysis = analyser.analyse("proc fresh {} {}\n", "tcl8.6").clone();
        backend
            .workspace_index
            .write()
            .await
            .add_document(uri.as_str(), &analysis);
    }

    backend.scan_workspace_folders().await.unwrap();

    let index = backend.workspace_index.read().await;
    assert!(
        !index.proc_definitions("fresh", "fresh").is_empty(),
        "live buffer's proc must survive the scan",
    );
    assert!(
        index.proc_definitions("stale", "stale").is_empty(),
        "on-disk copy must not clobber the open document",
    );
    drop(index);

    std::fs::remove_dir_all(&root).ok();
}

/// A workspace scan of unopened files must build only the
/// lightweight tier — `workspace_index` (from the scan's own analyser
/// pass) and the salsa `SourceFile` inputs — never the deep salsa tier
/// (`file_analysis_incremental` / `compilation_unit` /
/// `compiler_check_diagnostics`).  Uses the same
/// `TclDatabase::with_event_logger` technique as
/// `closed_file_republish_does_not_memoise_the_deep_compiler_tier` to
/// observe exactly which salsa queries a scan with no open documents
/// executes.
#[tokio::test]
async fn scan_workspace_folders_does_not_build_deep_tier_for_unopened_files() {
    let root = unique_scratch_dir("scan-no-deep-tier");
    std::fs::write(
        root.join("lib.tcl"),
        "proc greet {name} { puts \"hi $name\" }\n",
    )
    .unwrap();
    std::fs::write(root.join("main.tcl"), "greet world\n").unwrap();

    let executed: Arc<std::sync::Mutex<Vec<String>>> = Arc::default();
    let sink = Arc::clone(&executed);
    let backend = test_backend_over(tcl_lsp_db::TclDatabase::with_event_logger(move |key| {
        sink.lock().unwrap().push(key);
    }));
    let root_url = Uri::from_file_path(&root).unwrap();
    *backend.workspace_folders.lock().await = vec![root_url];

    backend.scan_workspace_folders().await.unwrap();

    let deep: Vec<String> = executed
        .lock()
        .unwrap()
        .iter()
        .filter(|key| {
            [
                "compilation_unit",
                "compiler_check_diagnostics",
                "file_analysis_incremental",
            ]
            .iter()
            .any(|query| key.contains(query))
        })
        .cloned()
        .collect();
    assert!(
        deep.is_empty(),
        "a workspace scan with no open documents must not build any \
             deep-tier salsa query for the files it discovers: {deep:?}",
    );

    // The lightweight index the scan's own analyser pass builds must still
    // cover both files — cross-file resolution for open documents is not
    // lost, only the eager deep-tier warm.
    let index = backend.workspace_index.read().await;
    assert!(
        !index.proc_definitions("greet", "greet").is_empty(),
        "the scan must still index the unopened file's declarations",
    );
    assert!(
        !index.invocations_of("greet", "").is_empty(),
        "the scan must still index the unopened file's call sites",
    );
    drop(index);

    std::fs::remove_dir_all(&root).ok();
}

/// [`Backend::warm_open_documents`] (the body
/// [`Backend::spawn_workspace_warm`] detaches) primes the deep salsa tier
/// for an **open** document but must not touch an unopened one the scan
/// only fed into `db_files` as a lightweight `SourceFile` input.
#[tokio::test]
async fn warm_open_documents_only_touches_open_files() {
    let executed: Arc<std::sync::Mutex<Vec<String>>> = Arc::default();
    let sink = Arc::clone(&executed);
    let backend = test_backend_over(tcl_lsp_db::TclDatabase::with_event_logger(move |key| {
        sink.lock().unwrap().push(key);
    }));
    let open_uri = Uri::from_str("file:///workspace/open.tcl").unwrap();
    let closed_uri = Uri::from_str("file:///workspace/closed.tcl").unwrap();
    backend.documents.lock("test").await.insert(
        open_uri.clone(),
        DocumentState::new("proc open_proc {} {}\n".to_owned(), "tcl8.6".to_owned()),
    );
    backend
        .db_set_source(&open_uri, "proc open_proc {} {}\n", "tcl8.6".to_owned())
        .await
        .unwrap();
    // Never opened, but present in `db_files` — exactly the state a
    // workspace scan leaves an unopened file in.
    backend
        .db_set_source(&closed_uri, "proc closed_proc {} {}\n", "tcl8.6".to_owned())
        .await
        .unwrap();

    Backend::warm_open_documents(
        Arc::clone(&backend.db),
        Arc::clone(&backend.db_files),
        Arc::clone(&backend.documents),
        Arc::clone(&backend.db_config),
        Arc::clone(&backend.folder_db_configs),
    )
    .await;

    let deep_runs = executed
        .lock()
        .unwrap()
        .iter()
        .filter(|key| key.contains("file_analysis_incremental"))
        .count();
    assert_eq!(
        deep_runs, 1,
        "the warm must run the deep tier exactly once, for the one open \
             document, never for the unopened one",
    );
}

