/// Poll `cond` until it holds or ~2s elapse, reporting whether it held.
/// For assertions on state a detached background task settles (a debounced
/// diagnostics worker retiring, say) rather than the awaited call itself.
async fn wait_for<F, Fut>(mut cond: F) -> bool
where
    F: FnMut() -> Fut,
    Fut: std::future::Future<Output = bool>,
{
    for _ in 0..200 {
        if cond().await {
            return true;
        }
        crate::rt::sleep(std::time::Duration::from_millis(10)).await;
    }
    false
}

/// Build a unique scratch directory under the system temp dir
/// for a disk-walk test, returning its path. The caller removes
/// it when done.
fn unique_scratch_dir(tag: &str) -> PathBuf {
    use std::sync::atomic::{AtomicU64, Ordering};
    static COUNTER: AtomicU64 = AtomicU64::new(0);
    loop {
        let n = COUNTER.fetch_add(1, Ordering::Relaxed);
        let dir =
            std::env::temp_dir().join(format!("tcl-lsp-scan-{tag}-{}-{n}", std::process::id()));
        match std::fs::create_dir(&dir) {
            Ok(()) => return dir,
            Err(error) if error.kind() == std::io::ErrorKind::AlreadyExists => {}
            Err(error) => panic!(
                "creating owned scratch directory {}: {error}",
                dir.display()
            ),
        }
    }
}

#[test]
fn collect_tcl_files_walks_recursively_and_skips_vendor() {
    let root = unique_scratch_dir("walk");
    std::fs::create_dir_all(root.join("sub")).unwrap();
    std::fs::create_dir_all(root.join("node_modules")).unwrap();
    std::fs::create_dir_all(root.join(".git")).unwrap();
    std::fs::write(root.join("top.tcl"), "set x 1\n").unwrap();
    std::fs::write(root.join("mod.tm"), "set y 2\n").unwrap();
    std::fs::write(root.join("readme.txt"), "not tcl\n").unwrap();
    std::fs::write(root.join("sub/nested.tcl"), "set z 3\n").unwrap();
    std::fs::write(root.join("node_modules/dep.tcl"), "set q 4\n").unwrap();
    std::fs::write(root.join(".git/hook.tcl"), "set w 5\n").unwrap();

    let mut out = Vec::new();
    collect_tcl_files(&vfs::NativeStore, &root, 100, &mut out);
    let mut names: Vec<String> = out
        .iter()
        .map(|p| p.file_name().unwrap().to_string_lossy().into_owned())
        .collect();
    names.sort();

    std::fs::remove_dir_all(&root).ok();

    assert_eq!(names, vec!["mod.tm", "nested.tcl", "top.tcl"]);
}

#[test]
fn collect_tcl_files_picks_up_tcltest_files() {
    // TP — a `.test` file (the standard `tcltest` extension; every mined
    // corpus, and tcllib's own test suite, use it throughout, e.g.
    // `test/argparse.test`). Invisible to the background workspace scan,
    // cross-document find-references / rename-safety silently miss call
    // sites living in an un-opened `.test` file.
    let root = unique_scratch_dir("tcltest");
    std::fs::create_dir_all(root.join("test")).unwrap();
    std::fs::write(root.join("lib.tcl"), "proc plain {} { return 1 }\n").unwrap();
    std::fs::write(root.join("test/argparse.test"), "plain\n").unwrap();

    let mut out = Vec::new();
    collect_tcl_files(&vfs::NativeStore, &root, 100, &mut out);
    let mut names: Vec<String> = out
        .iter()
        .map(|p| p.file_name().unwrap().to_string_lossy().into_owned())
        .collect();
    names.sort();

    std::fs::remove_dir_all(&root).ok();

    assert_eq!(names, vec!["argparse.test", "lib.tcl"]);
}

#[test]
fn collect_tcl_files_reads_a_memory_store_workspace() {
    let store = vfs::MemoryStore::new();
    store.upsert("/ws/main.tcl", b"".to_vec());
    store.upsert("/ws/lib/helpers.tcl", b"".to_vec());
    store.upsert("/ws/tmp/mypkg/impl.tcl", b"".to_vec());
    let mut out = Vec::new();
    collect_tcl_files(&store, Path::new("/ws"), 100, &mut out);
    let mut names: Vec<String> = out
        .iter()
        .map(|p| p.to_string_lossy().into_owned())
        .collect();
    names.sort();
    // `tmp/` is a skipped scan directory, exactly as on disk.
    assert_eq!(names, vec!["/ws/lib/helpers.tcl", "/ws/main.tcl"]);
}

#[test]
fn collect_tcl_files_respects_cap() {
    let root = unique_scratch_dir("cap");
    for i in 0..10 {
        std::fs::write(root.join(format!("f{i}.tcl")), "set x 1\n").unwrap();
    }
    let mut out = Vec::new();
    let complete = collect_tcl_files(&vfs::NativeStore, &root, 3, &mut out);
    let got = out.len();
    std::fs::remove_dir_all(&root).ok();
    assert_eq!(got, 3);
    assert!(!complete, "the capped scan must not authorize absence");
}

#[tokio::test]
async fn dialect_for_open_falls_back_to_folder_dialect() {
    let backend = test_backend();
    *backend.folder_dialects.lock().await = vec![(
        Uri::from_str("file:///workspace/").unwrap(),
        "f5-irules".to_owned(),
    )];
    let doc = Uri::from_str("file:///workspace/main.tcl").unwrap();
    // The bare `tcl` language id names no specific version (editors send it
    // for every `.tcl` file), so the folder override *is* consulted — it is
    // the more specific signal.
    assert_eq!(
        backend.dialect_for_open(&doc, "tcl", "").await,
        "f5-irules".to_owned(),
    );
    // An unknown language id (`plaintext`) lets the folder
    // override take effect.
    assert_eq!(
        backend.dialect_for_open(&doc, "plaintext", "").await,
        "f5-irules".to_owned(),
    );
    // An explicit *versioned* language id is a deliberate choice and still
    // wins over the folder override.
    assert_eq!(
        backend.dialect_for_open(&doc, "tcl9.0", "").await,
        "tcl9.0".to_owned(),
    );
}

/// Opening a `.tclspec` activates the `SpecTcl` pack.
///
/// Every editor integration registers `.tclspec` under the plain `tcl`
/// language id (the extension is the registration `spec-packs.md` asks
/// for), so the routing that has to work is the bare-`tcl` path: the
/// shared detector reads the extension — and, for a pack saved under
/// another name, the `speclib` content signature — and answers `spectcl`.
/// The canonical name and the editor spellings are accepted directly too,
/// for MCP / direct callers and any integration that contributes its own
/// language id.
#[tokio::test]
async fn dialect_for_open_routes_tclspec_to_the_spectcl_dialect() {
    let backend = test_backend();
    // A folder override is in place precisely to prove the file's own
    // identity beats it: a `.tclspec` under an iRules folder is still a
    // spec pack.
    *backend.folder_dialects.lock().await = vec![(
        Uri::from_str("file:///workspace/").unwrap(),
        "f5-irules".to_owned(),
    )];
    let pack = Uri::from_str("file:///workspace/mylib.tclspec").unwrap();
    assert_eq!(
        backend
            .dialect_for_open(&pack, "tcl", "command foo { arity 1 }\n")
            .await,
        "spectcl".to_owned(),
        "the `.tclspec` extension selects the SpecTcl dialect",
    );
    // The `speclib` directive is a content signature, so a pack saved
    // under a `.tcl` name routes too.
    let misnamed = Uri::from_str("file:///workspace/mylib.tcl").unwrap();
    assert_eq!(
        backend
            .dialect_for_open(&misnamed, "tcl", "speclib mylib 1.0 {\n}\n")
            .await,
        "spectcl".to_owned(),
    );
    // An explicit language id — canonical or editor spelling — routes
    // directly, without consulting the document at all.
    for id in ["spectcl", "tclspec", "tcl-spec"] {
        assert_eq!(
            backend.dialect_for_open(&pack, id, "").await,
            "spectcl".to_owned(),
            "language id {id:?} names the SpecTcl dialect",
        );
    }
    // …and the registry that dialect resolves to really carries the pack.
    let reg = tcl_registry::model::ingress::static_context_for("spectcl").commands();
    assert!(reg.get("speclib").is_some(), "the SpecTcl pack is loaded");
    assert!(reg.get("set").is_some(), "core Tcl stays underneath it");
}

/// Opening a `.sslictcl` activates the `SslicTcl` vocabulary.
///
/// The `SpecTcl` test above, for the sibling declarative dialect: the
/// `.sslictcl` extension routes under the bare `tcl` language id every
/// editor sends, the mandatory `sslictcl VERSION` header is the content
/// signature that recognises a document saved under a `.tcl` name, and the
/// canonical name — which is also the editor language id — routes
/// directly.
#[tokio::test]
async fn dialect_for_open_routes_sslictcl_to_the_sslictcl_dialect() {
    let backend = test_backend();
    // As above: a folder override proves the file's own identity wins.
    *backend.folder_dialects.lock().await = vec![(
        Uri::from_str("file:///workspace/").unwrap(),
        "f5-irules".to_owned(),
    )];
    let doc = Uri::from_str("file:///workspace/site.sslictcl").unwrap();
    assert_eq!(
        backend
            .dialect_for_open(&doc, "tcl", "sslictcl 1\nendpoint /Common/www {\n}\n")
            .await,
        "sslictcl".to_owned(),
        "the `.sslictcl` extension selects the SslicTcl dialect",
    );
    let misnamed = Uri::from_str("file:///workspace/site.tcl").unwrap();
    assert_eq!(
        backend
            .dialect_for_open(&misnamed, "tcl", "sslictcl 1\n")
            .await,
        "sslictcl".to_owned(),
        "the `sslictcl VERSION` header is the content signature",
    );
    for id in ["sslictcl"] {
        assert_eq!(
            backend.dialect_for_open(&doc, id, "").await,
            "sslictcl".to_owned(),
            "language id {id:?} names the SslicTcl dialect",
        );
    }
    // …and the registry that dialect resolves to really carries the pack.
    let reg = tcl_registry::model::ingress::static_context_for("sslictcl").commands();
    assert!(reg.get("endpoint").is_some(), "the SslicTcl pack is loaded");
    assert!(reg.get("set").is_some(), "core Tcl stays underneath it");
}

/// A `dialect =` key in `config.ini` / `.tcl-lsp.ini` sets the session
/// `default_dialect`; a normally-opened `.tcl` buffer (language id `"tcl"`,
/// which every editor sends) must resolve to it rather than pinning
/// `tcl8.6`.
#[tokio::test]
async fn dialect_for_open_respects_config_default_dialect() {
    let backend = test_backend();
    *backend.default_dialect.lock().await = "tcl9.0".to_owned();
    let doc = Uri::from_str("file:///workspace/main.tcl").unwrap();
    assert_eq!(
        backend.dialect_for_open(&doc, "tcl", "").await,
        "tcl9.0".to_owned(),
    );
    // An in-source dialect directive is still the most specific signal and
    // overrides the configured default.
    assert_eq!(
        backend
            .dialect_for_open(&doc, "tcl", "# tcl-dialect: tcl8.4\n")
            .await,
        "tcl8.4".to_owned(),
    );
}

/// An explicit BIG-IP language id resolves to `f5-bigip` even when the
/// document basename is not a canonical `bigip*.conf` name — the
/// manual-language-mode case the `is_bigip_conf_uri` basename branch
/// alone would miss.
#[tokio::test]
async fn dialect_for_open_maps_bigip_language_id() {
    let backend = test_backend();
    let doc = Uri::from_str("file:///workspace/device_config.txt").unwrap();
    assert_eq!(
        backend.dialect_for_open(&doc, "tcl-bigip", "").await,
        "f5-bigip".to_owned(),
    );
    assert_eq!(
        backend.dialect_for_open(&doc, "f5-bigip", "").await,
        "f5-bigip".to_owned(),
    );
    // A generic Tcl language id on the same non-conf name does not get the
    // BIG-IP dialect (no basename match, no explicit BIG-IP id).
    assert_ne!(
        backend.dialect_for_open(&doc, "tcl", "").await,
        "f5-bigip".to_owned(),
    );
}

/// The basename route reads the URI's decoded last segment: a
/// percent-encoded canonical name is that name, and a literal backslash in
/// a POSIX name is part of the name rather than a separator.
#[tokio::test]
async fn dialect_for_open_reads_the_decoded_uri_basename() {
    let backend = test_backend();
    for raw in [
        "file:///workspace/bigip%2Econf",
        "file:///my%20dir/BIGIP_BASE.CONF",
    ] {
        let doc = Uri::from_str(raw).unwrap();
        assert_eq!(
            backend.dialect_for_open(&doc, "tcl", "").await,
            "f5-bigip".to_owned(),
            "{raw}",
        );
    }
    let doc = Uri::from_str("file:///workspace/a%5Cbigip.conf").unwrap();
    assert_ne!(
        backend.dialect_for_open(&doc, "tcl", "").await,
        "f5-bigip".to_owned(),
    );
}

/// A session-default dialect change (as `tclLsp.selectDialect` pushes via
/// `workspace/didChangeConfiguration`) re-resolves already-open documents:
/// one that fell back to the default moves to the new default, while one
/// opened with an explicit language id keeps its dialect.
#[tokio::test]
async fn dialect_config_change_reresolves_open_documents() {
    let backend = test_backend();
    *backend.default_dialect.lock().await = "tcl8.6".to_owned();

    let plain = Uri::from_str("file:///plain.tcl").unwrap();
    let irule = Uri::from_str("file:///app.irule").unwrap();
    {
        let mut docs = backend.documents.lock("test").await;
        // No recognised language id → opened under the session default.
        docs.insert(
            plain.clone(),
            DocumentState::new("set x 1\n".to_owned(), "tcl8.6".to_owned())
                .with_language_id("plaintext".to_owned()),
        );
        // An explicit iRules language id → resolved independently of the
        // default.
        docs.insert(
            irule.clone(),
            DocumentState::new("when HTTP_REQUEST {}\n".to_owned(), "f5-irules".to_owned())
                .with_language_id("tcl-irule".to_owned()),
        );
    }

    // The user switches the session dialect to tcl9.0.
    *backend.default_dialect.lock().await = "tcl9.0".to_owned();
    backend.reresolve_open_document_dialects().await.unwrap();

    let docs = backend.documents.lock("test").await;
    assert_eq!(
        docs.get(&plain).unwrap().dialect,
        "tcl9.0",
        "a default-resolved document should follow the new session default",
    );
    assert_eq!(
        docs.get(&irule).unwrap().dialect,
        "f5-irules",
        "an explicit-language-id document keeps its dialect",
    );
}

#[tokio::test]
async fn registry_for_dialect_reuses_cached_registry() {
    let backend = test_backend();
    let first = backend.registry_for_dialect("f5-irules").await;
    let second = backend.registry_for_dialect("f5-irules").await;

    assert!(
        Arc::ptr_eq(&first, &second),
        "repeated dialect lookups should return the cached registry",
    );
    assert!(
        first
            .profile()
            .is_some_and(tcl_dialect::DialectProfile::is_irules),
        "the shared cache stamps the dialect profile the fold policy reads",
    );
}

#[test]
fn command_head_gate_distinguishes_head_from_argument() {
    let src = "proc greet {x} {}\ngreet arg\n";
    let analysis = Analyser::new().analyse(src, "tcl8.6").clone();
    let index = tcl_lexer::LineIndex::new_lsp(src);
    // `greet` at line 1 is a command head (the call site).
    assert!(position_is_command_head(
        src,
        Position {
            line: 1,
            character: 2
        },
        &analysis,
        &index,
    ));
    // `arg` at line 1 is an argument word, not a command head, so
    // the cross-document fallback must not fire on it.
    assert!(!position_is_command_head(
        src,
        Position {
            line: 1,
            character: 7
        },
        &analysis,
        &index,
    ));
}

#[test]
fn command_head_gate_uses_whole_original_words_and_exact_utf16_positions() {
    let src = "\"greet\" arg\ngr\\u0065et arg\n😀greet arg\nset value [greet arg]\nset data {greet arg}\n";
    let analysis = Analyser::new().analyse(src, "tcl8.6");
    let index = tcl_lexer::LineIndex::new_lsp(src);
    for pos in [
        Position::new(0, 0),
        Position::new(0, 3),
        Position::new(0, 6),
        Position::new(1, 4),
        Position::new(2, 0),
        Position::new(2, 2),
        Position::new(3, 12),
    ] {
        assert!(
            position_is_command_head(src, pos, &analysis, &index),
            "{pos:?}"
        );
    }
    for pos in [
        Position::new(0, 9),
        Position::new(2, 1),
        Position::new(2, 99),
        Position::new(3, 18),
        Position::new(4, 12),
        Position::new(99, 0),
    ] {
        assert!(
            !position_is_command_head(src, pos, &analysis, &index),
            "{pos:?}"
        );
    }
    let multiline = "\"greet\nmore\" arg\n";
    let analysis = Analyser::new().analyse(multiline, "tcl8.6");
    let index = tcl_lexer::LineIndex::new_lsp(multiline);
    assert!(!position_is_command_head(
        multiline,
        Position::new(0, 99),
        &analysis,
        &index
    ));
}

#[test]
fn command_head_gate_withdraws_stale_inputs_and_nonhead_report_rows() {
    let src = "greet arg\n";
    let analysis = Analyser::new().analyse(src, "tcl8.6");
    let index = tcl_lexer::LineIndex::new_lsp(src);
    let pos = Position::new(0, 2);
    assert!(position_is_command_head(src, pos, &analysis, &index));
    assert!(!position_is_command_head(
        "other arg\n",
        pos,
        &analysis,
        &index
    ));
    let foreign_index = tcl_lexer::LineIndex::new_lsp("one\ntwo\n");
    assert!(!position_is_command_head(
        src,
        pos,
        &analysis,
        &foreign_index
    ));
    let mut missing = analysis.clone();
    missing.resolved_input = None;
    assert!(!position_is_command_head(src, pos, &missing, &index));
    let mut grammar = analysis.clone();
    grammar.body_lexer_config = None;
    assert!(!position_is_command_head(src, pos, &grammar, &index));
    let mut consumed = analysis.clone();
    for invocation in &mut consumed.command_invocations {
        invocation.lookup =
            tcl_compiler::signature_scan::types::SignatureCommandLookup::DeferredReference;
    }
    assert!(!position_is_command_head(src, pos, &consumed, &index));
    let mut argument_report = analysis;
    for invocation in &mut argument_report.command_invocations {
        invocation.range = tcl_lexer::Span::new(6, 9);
    }
    assert!(!position_is_command_head(
        src,
        Position::new(0, 7),
        &argument_report,
        &index
    ));
}

#[tokio::test]
async fn cross_document_definition_resolves_sibling_proc() {
    let backend = test_backend();
    let lib_uri = Uri::from_str("file:///lib.tcl").unwrap();
    let main_uri = Uri::from_str("file:///main.tcl").unwrap();
    let lib_src = "proc shared_helper {} {}\n";
    let main_src = "shared_helper\n";
    // Register both documents.
    {
        let mut docs = backend.documents.lock("test").await;
        docs.insert(
            lib_uri.clone(),
            DocumentState::new(lib_src.to_owned(), "tcl8.6".to_owned()),
        );
        docs.insert(
            main_uri.clone(),
            DocumentState::new(main_src.to_owned(), "tcl8.6".to_owned()),
        );
    }
    // Index the library document's proc.
    {
        let mut a = Analyser::new();
        let lib_analysis = a.analyse(lib_src, "tcl8.6").clone();
        backend
            .workspace_index
            .write()
            .await
            .add_document(lib_uri.as_str(), &lib_analysis);
    }
    // From main.tcl, jumping on `shared_helper` resolves to
    // lib.tcl's declaration.
    let locs = Box::pin(backend.compute_definition(&main_uri, Position::new(0, 0)))
        .await
        .expect("definition ok");
    assert_eq!(locs.len(), 1, "{locs:?}");
    assert_eq!(locs[0].uri, lib_uri);
    // `proc shared_helper` — name token starts at column 5.
    assert_eq!(locs[0].range.start.line, 0);
    assert_eq!(locs[0].range.start.character, 5);
}

#[tokio::test]
async fn cross_document_definition_resolves_wildcard_imported_proc() {
    // TP, cross-document: `lib.tcl` defines and exports `bar`;
    // `main.tcl` wildcard-imports `::Lib::*` and calls `bar` bare.
    // `main.tcl`'s own in-document resolver can't see `::Lib::bar`
    // (a different file's proc), so this exercises the cross-document
    // fallback in `resolve_workspace_symbols`
    // (`WorkspaceIndex::resolve_wildcard_import`). Both documents must
    // be indexed: the `namespace import` itself is recorded in
    // `main.tcl`'s own analysis.
    let backend = test_backend();
    let lib_uri = Uri::from_str("file:///wc_lib.tcl").unwrap();
    let main_uri = Uri::from_str("file:///wc_main.tcl").unwrap();
    let lib_src = "namespace eval ::Lib {\n    proc bar {} {}\n    namespace export bar\n}\n";
    let main_src = "namespace import ::Lib::*\nbar\n";
    {
        let mut docs = backend.documents.lock("test").await;
        docs.insert(
            lib_uri.clone(),
            DocumentState::new(lib_src.to_owned(), "tcl8.6".to_owned()),
        );
        docs.insert(
            main_uri.clone(),
            DocumentState::new(main_src.to_owned(), "tcl8.6".to_owned()),
        );
    }
    {
        let mut index = backend.workspace_index.write().await;
        let mut a = Analyser::new();
        let lib_analysis = a.analyse(lib_src, "tcl8.6").clone();
        index.add_document(lib_uri.as_str(), &lib_analysis);
        let mut a2 = Analyser::new();
        let main_analysis = a2.analyse(main_src, "tcl8.6").clone();
        index.add_document(main_uri.as_str(), &main_analysis);
    }
    // Cursor on the bareword `bar` call (line 1, col 0).
    let locs = Box::pin(backend.compute_definition(&main_uri, Position::new(1, 0)))
        .await
        .expect("definition ok");
    assert_eq!(locs.len(), 1, "{locs:?}");
    assert_eq!(locs[0].uri, lib_uri);
    // `proc bar` — name token starts at column 9 on line 1 of lib.tcl.
    assert_eq!(locs[0].range.start.line, 1);
    assert_eq!(locs[0].range.start.character, 9);
}

