// Document-snapshot sharing and revision currency.
//
// `read_document` hands every in-flight request its own `DocumentState`.
// Those snapshots must (a) share one allocation of the document text and
// line index rather than copying both per request, and (b) stay pinned to
// the revision they were taken at, so a request that overlaps an edit
// finishes against coherent text *and* index instead of a mixture.

/// A synthetic document whose text and line index are both far larger than
/// a pointer, so "the snapshot shared them" is a meaningful claim rather
/// than a coincidence of small allocations. Deliberately not corpus-sized:
/// `register` analyses it, and the property under test is pointer
/// identity, which does not get truer with more lines.
fn large_document_source() -> String {
    use std::fmt::Write as _;
    (0..300).fold(String::new(), |mut acc, i| {
        let _ = writeln!(acc, "proc p{i} {{a b}} {{ return [expr {{$a + $b}}] }}");
        acc
    })
}

/// **TP** — concurrent reads of one open document share its storage.
#[tokio::test(flavor = "multi_thread", worker_threads = 4)]
async fn concurrent_snapshots_share_one_text_and_index_allocation() {
    let backend = Arc::new(test_backend());
    let uri = Uri::from_str("file:///shared.tcl").unwrap();
    let source = large_document_source();
    register(&backend, &uri, &source).await;

    // 32 overlapping readers, the concurrency the issue asks for.
    let mut tasks = Vec::new();
    for _ in 0..32 {
        let backend = Arc::clone(&backend);
        let uri = uri.clone();
        tasks.push(crate::rt::spawn(async move {
            backend
                .read_document(&uri)
                .await
                .unwrap()
                .expect("open document")
        }));
    }
    let mut snapshots = Vec::new();
    for t in tasks {
        snapshots.push(t.await.expect("reader task panicked"));
    }

    let owner = {
        let docs = backend.documents.lock("test").await;
        docs.get(&uri).expect("open document").clone()
    };
    for (i, snap) in snapshots.iter().enumerate() {
        assert!(
            Arc::ptr_eq(&owner.text, &snap.text),
            "snapshot {i} copied the document text instead of sharing it"
        );
        assert!(
            owner.line_index.shares_storage_with(&snap.line_index),
            "snapshot {i} copied the line index instead of sharing it"
        );
    }
    // One allocation, held by: the store, `owner`, and the 32 snapshots.
    assert_eq!(Arc::strong_count(&owner.text), 34);
    // …and every snapshot really does describe the whole document, so the
    // sharing assertions above are not passing on an empty buffer.
    assert_eq!(&*snapshots[0].text, source.as_str());
}

/// **FP** — editing while an older snapshot is alive must not mix
/// revisions: the in-flight reader keeps text *and* index from the
/// revision it was given, and they stay consistent with each other.
#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
async fn an_edit_never_mutates_a_snapshot_an_in_flight_request_holds() {
    let backend = Arc::new(test_backend());
    let uri = Uri::from_str("file:///revisions.tcl").unwrap();
    register(&backend, &uri, "set alpha 1\nset beta 2\n").await;

    let before = backend
        .read_document(&uri)
        .await
        .unwrap()
        .expect("open document");
    let before_revision = before.revision;

    backend
        .did_change(DidChangeTextDocumentParams {
            text_document: tower_lsp_server::ls_types::VersionedTextDocumentIdentifier {
                uri: uri.clone(),
                version: 2,
            },
            content_changes: vec![tower_lsp_server::ls_types::TextDocumentContentChangeEvent {
                range: Some(Range {
                    start: pos(0, 0),
                    end: pos(0, 0),
                }),
                range_length: None,
                text: "# a new leading comment line\n".to_owned(),
            }],
        })
        .await;

    // The old snapshot is untouched…
    assert_eq!(&*before.text, "set alpha 1\nset beta 2\n");
    assert_eq!(before.revision, before_revision);
    // …and its index still describes *its own* text: line 1 starts at the
    // `set beta` of the pre-edit buffer. A snapshot that had picked up the
    // post-edit index would resolve line 1 to the wrong byte offset, which
    // is precisely the corruption the one-snapshot invariant rules out.
    let line1 = before.line_index.line_start(1) as usize;
    assert_eq!(&before.text[line1..], "set beta 2\n");

    // The live document did advance, on both fields together.
    let after = backend
        .read_document(&uri)
        .await
        .unwrap()
        .expect("open document");
    assert!(after.text.starts_with("# a new leading comment line\n"));
    assert!(after.revision > before_revision);
    let after_line1 = after.line_index.line_start(1) as usize;
    assert_eq!(&after.text[after_line1..], "set alpha 1\nset beta 2\n");
    assert!(!Arc::ptr_eq(&before.text, &after.text));
}

/// **TN** — reading a closed on-disk file yields a snapshot but must not
/// install it in the open-document store, so a one-off cross-file read
/// cannot retain every file it ever touched.
#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
async fn reading_a_closed_on_disk_file_does_not_retain_it() {
    let dir = std::env::temp_dir().join(format!(
        "tcl-lsp-1184-{}",
        std::time::SystemTime::now()
            .duration_since(std::time::UNIX_EPOCH)
            .expect("clock")
            .as_nanos()
    ));
    std::fs::create_dir_all(&dir).expect("temp dir");
    let path = dir.join("ondisk.tcl");
    std::fs::write(&path, "proc onDisk {} { return 1 }\n").expect("write fixture");

    let backend = test_backend();
    let uri = canonical_file_uri(&path).expect("fixture path has a representable file URI");

    assert!(backend.documents.lock("test").await.is_empty());
    let snap = backend
        .read_document(&uri)
        .await
        .unwrap()
        .expect("disk fallback");
    assert_eq!(&*snap.text, "proc onDisk {} { return 1 }\n");
    assert!(
        backend.documents.lock("test").await.is_empty(),
        "a disk read must not become a permanent open-document entry"
    );
    // Reading again is a fresh read, not a retained snapshot.
    let again = backend
        .read_document(&uri)
        .await
        .unwrap()
        .expect("disk fallback");
    assert!(!Arc::ptr_eq(&snap.text, &again.text));

    std::fs::remove_dir_all(&dir).ok();
}

/// Register a document in the store and the workspace index.
/// A request that reads a document must not observe a buffer that is missing
/// an already-received edit.
///
/// `tower-lsp-server` drives requests and notifications through one
/// `buffer_unordered` pool, so a request handler can be polled while an
/// earlier `didChange` is still in flight. `read_document` must therefore
/// wait for the outstanding edit rather than racing ahead and answering from
/// the pre-edit text (which yielded semantic tokens whose lines/lengths
/// described text the client had already replaced).
#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
async fn read_document_waits_for_an_in_flight_edit() {
    let backend = Arc::new(test_backend());
    let uri = Uri::from_str("file:///ordering.tcl").unwrap();
    register(&backend, &uri, "set x 1\n").await;

    // Stand in for a `didChange` that has arrived and taken its turn, but has
    // not yet spliced the buffer.
    let ticket = backend.edit_order.take_ticket("didChange", &uri);
    let edit_in_flight = backend.edit_order.wait_turn(ticket).await;

    let mut reader = crate::rt::spawn({
        let backend = Arc::clone(&backend);
        let uri = uri.clone();
        async move { backend.read_document(&uri).await.unwrap().map(|d| d.text) }
    });

    // While the edit is in flight the read must not resolve.
    let elapsed = std::time::Duration::from_millis(300);
    if let Ok(done) = crate::rt::timeout(elapsed, &mut reader).await {
        panic!("read_document returned {done:?} while an edit was still in flight");
    }

    // Land the edit, then release the ordering lock: the read must now
    // resolve against the *settled* buffer, never the pre-edit text.
    backend.documents.lock("test").await.insert(
        uri.clone(),
        DocumentState::new("set x 2\n".to_owned(), "tcl8.6".to_owned()),
    );
    drop(edit_in_flight);
    let text = crate::rt::timeout(std::time::Duration::from_secs(5), reader)
        .await
        .expect("read_document must resolve once the edit lands")
        .expect("reader task panicked");
    assert_eq!(text.as_deref(), Some("set x 2\n"));
}

/// A ticket whose waiter is dropped *before* its turn is granted must not
/// stop the sequence for ever.
///
/// [`EditOrder::wait_turn`]'s own docs claim this already holds — "the guard
/// releases it on drop — including on ... a dropped (cancelled) handler
/// future, so a turn is never lost". That is true only once the guard
/// exists, and the guard is created at the *grant*, not at the draw. A
/// future dropped while parked in the wait leaves `now_serving` pointing at
/// a ticket nobody holds and nobody will ever release.
///
/// The consequence is total and permanent: every later document-sync
/// notification blocks in `wait_turn`, and every request handler blocks in
/// `edits_settled` — no CPU, no output, stdin still draining.
#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
async fn a_dropped_waiter_does_not_wedge_the_edit_order() {
    let order = EditOrder::default();
    let uri = Uri::from_str("file:///w/ordering.tcl").unwrap();

    // Ticket 0 is held by an edit that is getting on with its work.
    let first = order.take_ticket("didChange", &uri);
    let first_turn = order.wait_turn(first).await;

    // Ticket 1's handler is dropped while parked — it never reaches the
    // grant, so it never owns an `EditTurn`.
    let abandoned = order.take_ticket("didChange", &uri);
    let abandoned_n = abandoned.ticket;
    {
        let mut waiting = Box::pin(order.wait_turn(abandoned));
        // Poll it so it really is registered and parked, then drop it.
        assert!(
            crate::rt::timeout(std::time::Duration::from_millis(50), &mut waiting)
                .await
                .is_err(),
            "ticket {abandoned_n} must not be granted while an earlier ticket holds the turn",
        );
    }

    // Ticket 2 is a later edit, waiting its turn behind the abandoned one.
    let third = order.take_ticket("didChange", &uri);
    let third_n = third.ticket;
    let next = order.wait_turn(third);

    drop(first_turn);

    assert!(
        crate::rt::timeout(std::time::Duration::from_secs(5), next)
            .await
            .is_ok(),
        "a waiter dropped before its turn was granted stopped the edit order for ever: \
             ticket {third_n} never ran behind abandoned ticket {abandoned_n}. Every later edit \
             and every request handler waiting on `edits_settled` would now be blocked \
             permanently (#1657)",
    );

    // And the sequence is genuinely caught up, not merely unblocked: a
    // request barrier taken now must see every drawn ticket accounted for.
    assert!(
        crate::rt::timeout(
            std::time::Duration::from_secs(5),
            order.settled_to(order.settle_target()),
        )
        .await
        .is_ok(),
        "`settled` must not still be waiting on the abandoned ticket",
    );
}

/// The progressive diagnostics path once awaited the fast tier while its
/// own deep pass sat unpolled. A lock acquire parked inside the deep pass
/// keeps its place in the lock's fair queue, so when the holder released
/// the lock it was assigned to that unpolled acquire, and the fast tier,
/// waiting for the same lock, could never get it. The lock then read as
/// free while every later waiter stayed parked (#1657).
#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
async fn a_parked_deep_pass_does_not_strand_the_lock_the_fast_tier_needs_1657() {
    let short = std::time::Duration::from_millis(200);
    let lock = tokio::sync::Mutex::new(());
    let gate = FastTierGate::default();
    let elsewhere = lock.lock().await;
    let deep = async {
        drop(lock.lock().await);
        gate.pass().await;
    };
    tokio::pin!(deep);
    assert!(
        crate::rt::timeout(short, &mut deep).await.is_err(),
        "the deep pass must queue behind the current holder",
    );
    let hold = gate
        .hold()
        .expect("the deep pass has not reached its publication");
    drop(elsewhere);
    assert!(
        crate::rt::timeout(short, lock.lock()).await.is_err(),
        "control: with the deep pass unpolled, its queued acquire keeps the released lock",
    );
    let lock = &lock;
    let fast = async move {
        let _hold = hold;
        drop(lock.lock().await);
    };
    tokio::pin!(fast);
    let both = async {
        tokio::select! {
            biased;
            () = &mut deep => panic!("the deep pass published before the fast tier"),
            () = &mut fast => {}
        }
        deep.await;
    };
    assert!(
        crate::rt::timeout(std::time::Duration::from_secs(5), both)
            .await
            .is_ok(),
        "polling the deep pass beside the fast tier must let both finish",
    );
}

#[tokio::test]
async fn the_fast_tier_gate_orders_the_deep_publication_after_the_fast_tier() {
    let short = std::time::Duration::from_millis(50);
    let gate = FastTierGate::default();
    let hold = gate.hold().expect("an untouched gate can be held");
    let pass = gate.pass();
    tokio::pin!(pass);
    assert!(
        crate::rt::timeout(short, &mut pass).await.is_err(),
        "the deep pass must wait while the fast tier holds the gate",
    );
    drop(hold);
    assert!(
        crate::rt::timeout(short, &mut pass).await.is_ok(),
        "releasing the hold must let the deep pass through",
    );
    assert!(
        gate.hold().is_none(),
        "once the deep pass is publishing, no fast tier may follow it",
    );
}

/// The stall reporter must not announce a wedge that is already over.
///
/// `edits_settled`'s timeout can win its race by a hair: the wait expires,
/// and the edit it was waiting for lands before the report runs. Reporting
/// on the strength of "the timeout fired" would then describe a permanent
/// wedge with no holder and zero notifications queued — which is the
/// *ticket-loss* shape, so the line would not merely be noise but point at
/// the wrong defect.
///
/// The second half matters as much: recording that position in the rate
/// limiter would make a later, genuine stall at the same position suppress
/// itself. A false report could then hide the real one, in the single
/// diagnosis stream a wedge leaves behind.
///
/// Constructed directly rather than by racing a ten-second timeout: the
/// state that race produces is simply "the reporter is called with a target
/// the barrier has already reached", which is what this hands it.
#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
async fn a_barrier_that_has_caught_up_is_not_reported_as_a_stall() {
    let backend = test_backend();
    let uri = Uri::from_str("file:///w/caught-up.tcl").unwrap();

    // One edit drawn and handed on, so the barrier has reached its target —
    // exactly the state the timeout can lose its race against.
    let target = {
        let ticket = backend.edit_order.take_ticket("didChange", &uri);
        let target = backend.edit_order.settle_target();
        drop(backend.edit_order.wait_turn(ticket).await);
        target
    };
    assert!(
        backend.edit_order.served() >= target,
        "the barrier must have caught up, or this test proves nothing",
    );

    crate::rt::timeout(
        std::time::Duration::from_secs(5),
        backend.report_edit_barrier_stall(target),
    )
    .await
    .expect("the reporter must return promptly rather than block");

    assert_eq!(
        backend
            .edit_barrier_stall_reported
            .load(std::sync::atomic::Ordering::Acquire),
        u64::MAX,
        "a barrier that has caught up must not be reported, and must not \
             claim the rate limiter's slot — doing so would suppress the next \
             genuine stall at this position (#1657)",
    );

    // The positive case still works: a turn that is genuinely held is
    // reported, and only then does the position get recorded.
    let held = backend.edit_order.take_ticket("didOpen", &uri);
    let held_at = backend.edit_order.served();
    let _turn = backend.edit_order.wait_turn(held).await;
    let queued = backend.edit_order.take_ticket("didChange", &uri);
    let stalled_target = backend.edit_order.settle_target();
    crate::rt::timeout(
        std::time::Duration::from_secs(5),
        backend.report_edit_barrier_stall(stalled_target),
    )
    .await
    .expect("the reporter must return promptly rather than block");
    assert_eq!(
        backend
            .edit_barrier_stall_reported
            .load(std::sync::atomic::Ordering::Acquire),
        held_at,
        "a genuine stall must still be reported and recorded",
    );
    drop(queued);
}

#[test]
fn a_cancelled_clone_unwinds_at_the_next_compiler_checkpoint() {
    use tcl_compiler::analysis_control::{AnalysisCheckpoint, checkpoint};
    let db = tcl_lsp_db::TclDatabase::default();
    let reached = std::sync::atomic::AtomicBool::new(false);
    assert_eq!(
        cancellable_catch(&db, || !checkpoint(AnalysisCheckpoint::Command)).ok(),
        Some(true),
        "an uncancelled read completes and is not interrupted"
    );
    salsa::Database::cancellation_token(&db).cancel();
    let read = cancellable_catch(&db, || {
        let _ = checkpoint(AnalysisCheckpoint::Command);
        reached.store(true, std::sync::atomic::Ordering::Relaxed);
    });
    assert!(matches!(read, Err(salsa::Cancelled::Local)));
    assert!(
        !reached.load(std::sync::atomic::Ordering::Relaxed),
        "work after the checkpoint never runs"
    );
}

#[test]
fn a_live_publication_cancels_outstanding_database_clones() {
    let census = Arc::new(SnapshotCensus::default());
    let db = tcl_lsp_db::TclDatabase::default();
    let snapshot = census.track(db.clone(), "test-stale-reader");
    let token = salsa::Database::cancellation_token(&*snapshot);
    assert!(!token.is_cancelled(), "a fresh reader runs uncancelled");
    let drain = census.begin_publication();
    assert!(
        token.is_cancelled(),
        "a publication must stop the stale reader instead of waiting it out"
    );
    assert!(
        census.try_track(db.clone(), "test-late-reader").is_err(),
        "no new reader is admitted while the publication drains"
    );
    drop(snapshot);
    drop(drain);
    let late = census.track(db, "test-next-reader");
    assert!(
        !salsa::Database::cancellation_token(&*late).is_cancelled(),
        "a reader admitted after the publication is not cancelled"
    );
}

/// The snapshot census must count what is live and retire what is not.
///
/// This is the reading that names what a stalled turn is waiting for: salsa
/// parks `set_text` in `cancel_others` until every other database clone
/// drops, so the oldest outstanding snapshot is the thing at the bottom of
/// the stack. A census that over-counts would accuse an innocent site; one
/// that under-counts would report "nothing outstanding" and send the next
/// reader looking somewhere else entirely.
///
/// Driven against an isolated census so its counts are exact.
#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
async fn the_snapshot_census_tracks_live_clones_and_retires_dropped_ones() {
    let db = tcl_lsp_db::TclDatabase::default();
    let census = Arc::new(SnapshotCensus::default());
    assert_eq!(census.report().outstanding, 0, "a fresh census is empty");

    let first = census.track(db.clone(), "test-first");
    // Distinguishable ages, so "oldest" means something to assert on.
    crate::rt::sleep(std::time::Duration::from_millis(20)).await;
    let second = census.track(db.clone(), "test-second");

    let report = census.report();
    assert_eq!(report.outstanding, 2, "both live snapshots must be counted");
    assert_eq!(
        report
            .oldest
            .expect("a live snapshot must have an oldest")
            .0,
        "test-first",
        "the census must name the *longest-lived* snapshot, not the newest — \
             that is the one a blocked `cancel_others` is waiting for",
    );

    drop(first);
    let report = census.report();
    assert_eq!(
        report.outstanding, 1,
        "a dropped snapshot must retire, or a wedge would be blamed on a query \
             that finished long ago",
    );
    assert_eq!(
        report.oldest.expect("one snapshot is still live").0,
        "test-second",
        "retiring the oldest must promote the next one",
    );

    drop(second);
    let report = census.report();
    assert_eq!(report.outstanding, 0, "the census must return to empty");
    assert!(
        report.oldest.is_none(),
        "an empty census reports no oldest, which is what tells the stall line \
             the holder is parked on something other than `cancel_others`",
    );

    // And the handle really is the database: the deref is what lets every
    // call site pass `&*snapshot` where it passed `&snapshot` before.
    let third = census.track(db.clone(), "test-deref");
    let _: &tcl_lsp_db::TclDatabase = &third;
    drop(third);
}

/// A zero census is a publication precondition, so it must
/// mean more than "the snapshot wrapper started dropping": the wrapped
/// Salsa clone must already be destroyed. Drive the exact generic drop
/// implementation with a probe whose destructor samples the census.
#[test]
fn snapshot_census_retires_only_after_the_wrapped_clone_drops_1800() {
    struct DropProbe {
        census: Arc<SnapshotCensus>,
        saw_itself_registered: Arc<std::sync::atomic::AtomicBool>,
    }
    impl SnapshotCancellation for DropProbe {}

    impl Drop for DropProbe {
        fn drop(&mut self) {
            self.saw_itself_registered.store(
                self.census.report().outstanding == 1,
                std::sync::atomic::Ordering::SeqCst,
            );
        }
    }

    let census = Arc::new(SnapshotCensus::default());
    let saw_itself_registered = Arc::new(std::sync::atomic::AtomicBool::new(false));
    let snapshot = census.track(
        DropProbe {
            census: Arc::clone(&census),
            saw_itself_registered: Arc::clone(&saw_itself_registered),
        },
        "drop-order-proof-1800",
    );

    assert_eq!(census.report().outstanding, 1);
    drop(snapshot);
    assert!(
        saw_itself_registered.load(std::sync::atomic::Ordering::SeqCst),
        "the wrapped clone's destructor must still see its census entry"
    );
    assert_eq!(
        census.report().outstanding,
        0,
        "the entry must retire immediately after the wrapped clone is gone"
    );
}

/// A stalled turn must name the `await` it is suspended at, not merely the
/// handler that holds it.
///
/// Naming the handler narrows a wedge from "the server is wedged" to
/// "`did_open` is wedged" and no further: a backtrace of the wedged
/// process shows every Tokio worker parked with an empty run queue, so the
/// holder is a suspended future that appears in no stack. The phase marker
/// is the only reading that can close that gap, and this test is what says
/// it is telling the truth rather than reporting a stale or default value.
///
/// Constructed, not raced: the test itself holds the `documents` lock that
/// `did_open` takes for its short ordered stage, so the handler is granted
/// the turn, suspends at exactly one known point, and stays there for as
/// long as the assertion needs. Nothing but this test can release it.
#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
async fn a_stalled_turn_names_the_await_it_is_suspended_at() {
    let backend = Arc::new(test_backend());
    let uri = Uri::from_str("file:///w/phase.tcl").unwrap();

    let held_documents = backend.documents.lock("test").await;

    let opener = {
        let backend = Arc::clone(&backend);
        let uri = uri.clone();
        tokio::spawn(async move {
            Box::pin(backend.did_open(DidOpenTextDocumentParams {
                text_document: tower_lsp_server::ls_types::TextDocumentItem {
                    uri,
                    language_id: "tcl".to_owned(),
                    version: 1,
                    text: "set x 1\n".to_owned(),
                },
            }))
            .await;
        })
    };

    let holder_now = || {
        backend
            .edit_order
            .holder
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner)
            .clone()
    };
    let reached = crate::rt::timeout(std::time::Duration::from_secs(5), async {
        loop {
            if let Some(h) = holder_now()
                && h.phase == "did_open: documents.lock"
            {
                return h;
            }
            crate::rt::sleep(std::time::Duration::from_millis(5)).await;
        }
    })
    .await;
    let Ok(holder) = reached else {
        panic!(
            "the turn holder never reported the `await` it is suspended at. `did_open` is \
                 parked on the `documents` lock this test holds and cannot be anywhere else, so \
                 the marker is missing or stale. Without it a #1657 stall line names only the \
                 handler, which is where the investigation already was. Last observed holder: \
                 {:?}",
            holder_now(),
        )
    };

    assert_eq!(
        holder.what, "didOpen",
        "the phase must be attributed to the handler that actually holds the turn",
    );
    assert_eq!(holder.uri, uri.as_str(), "…and to the document it is for");
    assert!(
        holder.phase != TURN_PHASE_GRANTED,
        "a holder past its first marked await must not still read as freshly granted",
    );
    // The phase was entered after the grant, so a reader can tell "stuck at
    // its first await" from "got several awaits in and then stopped".
    assert!(
        holder.since.elapsed() >= holder.phase_since.elapsed(),
        "the phase cannot predate the turn that owns it",
    );

    // Release it and let the handler finish, so the test leaves no wedged
    // task behind — and so this really was a suspension, not a deadlock.
    drop(held_documents);
    crate::rt::timeout(std::time::Duration::from_secs(5), opener)
        .await
        .expect("did_open must complete once the lock is released")
        .expect("the did_open task must not panic");
    assert!(
        holder_now().is_none(),
        "the turn must be handed on, clearing the holder with it",
    );
}

/// The stall line must name **who holds** the open-document map, not only
/// which lock the turn holder is waiting on.
///
/// This is the other half of the chain. The phase marker says a wedged
/// `did_change` sits at `did_change: documents.lock`; that names what it
/// wants, not who has it. Inferring the holder from an adjacent
/// `diagnostics.publish.enqueued` marker with no matching completion is an
/// inference, and a wedge need not leave so tidy a trail.
///
/// Constructed rather than raced: the test takes the map itself under a
/// known tag and holds it, which is exactly the state a real holder is in.
#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
async fn the_open_document_map_names_its_holder() {
    let backend = test_backend();
    assert!(
        backend.documents.holder().is_none(),
        "a free map must report no holder, or a stall line would accuse a \
             call site that has already finished",
    );

    {
        let _held = backend.documents.lock("a-known-test-site").await;
        let held = backend.documents.holder().expect(
            "a held map must name its holder — without this the #1657 \
                         stall line can only say which lock is wanted, never who has it",
        );
        assert_eq!(
            held.site, "a-known-test-site",
            "the holder must be the site that actually took the lock",
        );
        // Sanity that the clock is the shim and is running, not a default.
        assert!(
            held.held < std::time::Duration::from_secs(60),
            "the hold age must be measured from the acquisition, not from an epoch",
        );
        // A hold still in its first phase reports the two ages as equal —
        // one clock reading serves both at acquisition.
        assert!(
            held.in_phase <= held.held,
            "the current phase cannot predate the hold that owns it",
        );
    }

    assert!(
        backend.documents.holder().is_none(),
        "dropping the guard must clear the holder; a tag that outlived its \
             guard would blame the previous holder for the next wedge",
    );

    // And the tag tracks a second, different holder rather than sticking.
    {
        let _held = backend.documents.lock("a-second-site").await;
        assert_eq!(
            backend.documents.holder().expect("held").site,
            "a-second-site",
            "each acquisition must overwrite the tag",
        );
    }
}

fn pending_diagnostic_summary(publisher: &DiagnosticPublisher, uri: &Uri) -> Option<bool> {
    let state = publisher
        .state
        .lock()
        .unwrap_or_else(std::sync::PoisonError::into_inner);
    state
        .pending
        .get(uri)
        .map(|pending| pending.diagnostics.is_empty())
}

/// A client notification that never drains may stop diagnostics, but it
/// must not stop edits or requests from taking the global document map.
/// The close committed behind it must also replace the pending stale set.
#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
async fn stalled_diagnostic_delivery_cannot_hold_documents_and_close_wins() {
    use std::sync::atomic::Ordering;

    let backend = Arc::new(test_backend());
    // Keep the persistent consumer deliberately parked without involving
    // transport timing. Enqueue still commits normally; receipts simply do
    // not resolve until a newer state replaces them.
    backend
        .diagnostic_publisher
        .started
        .store(true, Ordering::Release);
    let uri = Uri::from_str("file:///w/mailbox-stall.tcl").unwrap();
    register(&backend, &uri, "set x 1\n").await;
    let revision = backend
        .documents
        .lock("test revision")
        .await
        .get(&uri)
        .expect("registered document")
        .revision;

    let publishing_backend = Arc::clone(&backend);
    let publishing_uri = uri.clone();
    let publish = tokio::spawn(async move {
        unassociated_delivery(
            &publishing_backend,
            &publishing_uri,
            DiagCurrency::Open(revision),
            Some(1),
        )
        .deliver_if_current(vec![tower_lsp_server::ls_types::Diagnostic::default()])
        .await
    });

    crate::rt::timeout(std::time::Duration::from_secs(1), async {
        loop {
            if pending_diagnostic_summary(&backend.diagnostic_publisher, &uri).is_some() {
                break;
            }
            crate::rt::yield_now().await;
        }
    })
    .await
    .expect("the authoritative publish must reach the mailbox");

    let mut docs = crate::rt::timeout(
        std::time::Duration::from_millis(250),
        backend.documents.lock("test close"),
    )
    .await
    .expect("a pending client send must not retain the documents lock");
    docs.remove(&uri);
    drop(docs);

    let clearing_backend = Arc::clone(&backend);
    let clearing_uri = uri.clone();
    let clear = tokio::spawn(async move {
        clearing_backend
            .clear_closed_diagnostics(&clearing_uri)
            .await;
    });

    crate::rt::timeout(std::time::Duration::from_secs(1), async {
        loop {
            let close_is_pending =
                pending_diagnostic_summary(&backend.diagnostic_publisher, &uri) == Some(true);
            if close_is_pending {
                break;
            }
            crate::rt::yield_now().await;
        }
    })
    .await
    .expect("the close must replace the pending stale diagnostics");
    assert!(
        !crate::rt::timeout(std::time::Duration::from_secs(1), publish)
            .await
            .expect("replacement must settle the stale receipt")
            .expect("the publish task must not panic"),
        "the superseded run must not claim delivery or emit its completion marker",
    );
    let state = backend
        .diagnostic_publisher
        .state
        .lock()
        .unwrap_or_else(std::sync::PoisonError::into_inner);
    let pending = state.pending.get(&uri).expect("close clear stays pending");
    assert!(
        pending.diagnostics.is_empty(),
        "the newest retained state for a closed URI must be the clear",
    );
    assert_eq!(
        state.order.iter().filter(|queued| *queued == &uri).count(),
        1
    );
    drop(state);
    clear.abort();
}

/// Latest-wins replacement is bounded per URI and moves the replacement to
/// its real cross-URI commit position.
#[tokio::test]
async fn diagnostic_mailbox_is_latest_wins_and_preserves_surviving_order() {
    use std::sync::atomic::Ordering;

    let backend = test_backend();
    let publisher = &backend.diagnostic_publisher;
    publisher.started.store(true, Ordering::Release);
    let a = Uri::from_str("file:///a.tcl").unwrap();
    let b = Uri::from_str("file:///b.tcl").unwrap();
    let first_a = publisher.enqueue(a.clone(), Vec::new(), Some(1), false, false);
    let _b = publisher.enqueue(b.clone(), Vec::new(), Some(1), false, false);
    let _latest_a = publisher.enqueue(a.clone(), Vec::new(), Some(2), false, false);

    assert_eq!(
        first_a.await.expect("publisher remains alive"),
        DiagnosticPublishOutcome::Superseded,
    );
    let state = publisher
        .state
        .lock()
        .unwrap_or_else(std::sync::PoisonError::into_inner);
    assert_eq!(state.pending.len(), 2, "one retained vector per URI");
    assert_eq!(state.order, VecDeque::from([b, a.clone()]));
    assert_eq!(state.pending.get(&a).expect("latest a").version, Some(2),);
}

/// The map must distinguish "nobody wants it" from "everyone but the
/// waiter is getting it".
///
/// A wedge can leave the barrier holder parked on `documents.lock()`
/// while the map reads as *free*. One sample cannot tell those apart, and
/// they need different fixes: a lost wakeup is a scheduling fault, whereas a
/// map being taken repeatedly past a waiter means the waiter is not in the
/// queue at all. The acquisition counter is what separates them, so it has
/// to actually count.
#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
async fn the_document_map_counts_acquisitions_and_remembers_its_last_holder() {
    let store = DocumentStore::default();

    let idle = store.contention();
    assert_eq!(idle.acquisitions, 0, "a fresh map has never been taken");
    assert!(idle.held_by.is_none(), "a fresh map is free");
    assert!(
        idle.last.is_none(),
        "a fresh map has no previous holder to blame",
    );

    {
        let _held = store.lock("first-site").await;
        let now = store.contention();
        assert_eq!(now.acquisitions, 1, "taking the map must count");
        assert_eq!(
            now.held_by.expect("held").site,
            "first-site",
            "a held map names its holder",
        );
    }

    // Released: free, but the previous holder is still nameable — the thing
    // the capture could not tell me.
    let after = store.contention();
    assert!(after.held_by.is_none(), "the guard released the map");
    assert_eq!(
        after.last.expect("a previous holder is remembered").0,
        "first-site",
        "a free map must still say who held it last, or a stall line that \
             finds it free has nothing to report at all",
    );

    // A second acquisition advances the counter: this is the reading that,
    // sampled twice during a stall, says the map is being taken *past* a
    // parked waiter rather than sitting idle.
    {
        let _held = store.lock("second-site").await;
    }
    let later = store.contention();
    assert_eq!(
        later.acquisitions, 2,
        "every acquisition must count, or a busy map is indistinguishable \
             from an untouched one and the lost-wakeup verdict is unfalsifiable",
    );
    assert_eq!(
        later.last.expect("previous holder").0,
        "second-site",
        "the remembered holder must be the most recent one",
    );
}

/// Retagging must restart the phase clock and leave the hold clock alone.
///
/// A line reading `the open-document map is held by cache_and_deliver:
/// publish send (70s)` cannot be acted on, because one age cannot say
/// whether the *publish send* is slow or whether a slow earlier phase had
/// already burned that time before the hold reached it. Retag overwrites
/// the site, so the earlier phase leaves no trace, and the two
/// possibilities want different fixes.
///
/// Both clocks together answer it: `held` is the whole hold, `in_phase` is
/// this step. `TurnHolder` carries the same pairing, so the invariant is
/// pinned here rather than left to be re-derived.
#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
async fn retagging_the_map_restarts_the_phase_clock_but_not_the_hold_clock() {
    let store = DocumentStore::default();
    let held = store.lock("first-phase").await;

    // A fresh hold is entirely within its first phase, so the two ages agree.
    let fresh = store.holder().expect("held");
    assert_eq!(fresh.site, "first-phase");
    assert!(
        fresh.held.saturating_sub(fresh.in_phase) < std::time::Duration::from_millis(50),
        "a hold still in its first phase must report the two ages as \
             effectively equal — one clock reading serves both at acquisition",
    );

    crate::rt::sleep(std::time::Duration::from_millis(120)).await;
    held.retag("second-phase");
    let after = store.holder().expect("still held");

    assert_eq!(after.site, "second-phase", "retag renames the holder");
    assert!(
        after.held >= std::time::Duration::from_millis(100),
        "the hold clock must survive a retag — it is the answer to 'how long \
             has the map been gone', which is what every waiter is blocked on",
    );
    assert!(
        after.in_phase < std::time::Duration::from_millis(100),
        "the phase clock must restart on a retag — without that, a long hold \
             reports only where it currently is, and a stall line cannot tell a \
             slow step from a step that was merely reached late (#1657)",
    );
    assert!(
        after.in_phase < after.held,
        "after a retag the current phase is strictly younger than the hold",
    );
}

/// The slowest phase of a hold must survive the retag that relabels it
/// away.
///
/// A line blaming `cache_and_deliver: publish send` for far longer than a
/// send's own budget allows means the time went to a phase that had
/// already been renamed. `site` and `phase_since` answer
/// only "is *this* step slow"; without a high-water mark nothing names an
/// earlier one.
#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
async fn the_longest_phase_of_a_hold_survives_the_retag_that_renames_it() {
    let store = DocumentStore::default();
    let held = store.lock("slow-phase").await;

    // Nothing has finished yet, so there is no high-water mark to report
    // and the clause is suppressed rather than repeating the current phase.
    assert!(store.holder().expect("held").longest_phase.is_none());

    crate::rt::sleep(std::time::Duration::from_millis(120)).await;
    held.retag("fast-phase");

    let after = store.holder().expect("still held");
    let (site, elapsed) = after.longest_phase.expect("the first phase closed");
    assert_eq!(
        site, "slow-phase",
        "the high-water mark names the phase that burned the time, not the \
             one running now",
    );
    assert!(
        elapsed >= std::time::Duration::from_millis(100),
        "and carries its duration: {elapsed:?}",
    );
    assert!(
        after.in_phase < std::time::Duration::from_millis(100),
        "the current phase is young — which is exactly the reading that was \
             ambiguous before",
    );

    // A later, shorter phase does not displace it.
    held.retag("third-phase");
    assert_eq!(
        store
            .holder()
            .expect("still held")
            .longest_phase
            .map(|(s, _)| s),
        Some("slow-phase"),
    );
}

/// The phase running at release is a finished phase like any other.
///
/// A hold whose *last* step is the slow one never retags again, so without
/// closing the phase on drop the shape most worth catching would be the one
/// that leaves no trace.
#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
async fn the_phase_running_at_release_is_recorded_too() {
    let store = DocumentStore::default();
    let held = store.lock("quick-phase").await;
    held.retag("slow-final-phase");
    crate::rt::sleep(std::time::Duration::from_millis(120)).await;
    drop(held);

    let contention = store.contention();
    assert!(contention.held_by.is_none(), "released");
    let (site, _, longest) = contention.last.expect("a departed holder");
    assert_eq!(site, "slow-final-phase");
    let (longest_site, elapsed) = longest.expect("the final phase closed on release");
    assert_eq!(longest_site, "slow-final-phase");
    assert!(
        elapsed >= std::time::Duration::from_millis(100),
        "{elapsed:?}",
    );
}

/// The stall line reports all three readings, and says nothing about a
/// high-water mark it does not have.
#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
async fn the_stall_line_names_the_longest_phase() {
    let store = DocumentStore::default();
    let before = store.contention();
    let held = store.lock("first").await;

    let fresh = describe_documents_contention(&before, &store.contention());
    assert!(fresh.contains("held by first"), "{fresh}");
    assert!(
        !fresh.contains("longest phase"),
        "a hold still in its first phase has no earlier phase to name: {fresh}",
    );

    crate::rt::sleep(std::time::Duration::from_millis(120)).await;
    held.retag("second");
    let line = describe_documents_contention(&before, &store.contention());
    assert!(line.contains("held by second"), "{line}");
    assert!(
        line.contains("longest phase so far first"),
        "the line must name the phase that burned the time: {line}",
    );
}

/// The mark covers finished phases only, so it must not be called the
/// longest while the phase running now has already outlasted it.
///
/// A hold 70s into `publish send` after a 1s earlier phase would otherwise
/// read `70.0s at this point; longest phase so far <earlier>
/// (1.0s)` — false, and pointing an investigation at the wrong step. The
/// live reading already names the longest phase in that case.
#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
async fn the_line_does_not_call_an_earlier_phase_longest_than_the_running_one() {
    let store = DocumentStore::default();
    let before = store.contention();
    let held = store.lock("quick").await;
    held.retag("slow-and-still-running");
    crate::rt::sleep(std::time::Duration::from_millis(120)).await;

    let line = describe_documents_contention(&before, &store.contention());
    assert!(line.contains("held by slow-and-still-running"), "{line}");
    assert!(
        !line.contains("longest phase"),
        "the running phase has outlasted every finished one, so `at this \
             point` is already the longest: {line}",
    );

    // Once it ends, the same phase becomes the mark like any other.
    held.retag("next");
    let line = describe_documents_contention(&before, &store.contention());
    assert!(
        line.contains("longest phase so far slow-and-still-running"),
        "{line}",
    );
}

/// The collision refusal names the documents, and says nothing at all when
/// there is no collision.
///
/// Three at most, then a count: the reason renders as one unwrapped line in
/// some hosts, and the gate refuses on the first collision regardless, so
/// the list is there to be checkable rather than exhaustive.
#[test]
fn a_collision_refusal_names_where_the_cell_already_lives() {
    assert!(describe_variable_collision("::a", "::b", &[]).is_none());

    let one = describe_variable_collision("::a", "::b", &["file:///x.tcl".to_owned()])
        .expect("a collision refuses");
    assert!(one.contains("cannot rename `::a`"), "{one}");
    assert!(
        one.contains("`::b` is already declared in file:///x.tcl"),
        "{one}"
    );
    assert!(!one.contains("more"), "one document needs no tail: {one}");

    let many: Vec<String> = (0..5).map(|i| format!("file:///f{i}.tcl")).collect();
    let listed = describe_variable_collision("::a", "::b", &many).expect("a collision refuses");
    assert!(
        listed.contains("file:///f0.tcl, file:///f1.tcl, file:///f2.tcl"),
        "{listed}"
    );
    assert!(listed.contains("and 2 more"), "{listed}");
    assert!(
        !listed.contains("file:///f3.tcl"),
        "the tail is a count, not a list: {listed}"
    );
}

/// A contention snapshot must describe one state, not several.
///
/// Behind two mutexes and an atomic, the three readings could interleave:
/// read the holder, watch
/// that guard drop and another task acquire, then read the last-holder and
/// the count from *after* the change. The line then pairs one task's
/// identity with another's metadata — the exact confusion the discriminator
/// exists to remove. Dating every age from one clock reading does not fix
/// it; that fixes *when* the numbers were taken, not *which state* they
/// describe. Only a shared lock does, which is why all three now live
/// under one.
///
/// Atomicity itself is guaranteed by construction and is verified
/// structurally: reverting to split fields fails this test's concurrent
/// half. What is pinned here is the record's semantics, which a future
/// edit could break without touching the lock.
#[tokio::test(flavor = "multi_thread", worker_threads = 4)]
async fn a_contention_snapshot_never_mixes_two_states() {
    let store = Arc::new(DocumentStore::default());

    // The deterministic half: the transitions the stall line reads.
    let empty = store.contention();
    assert_eq!(empty.acquisitions, 0);
    assert!(empty.held_by.is_none() && empty.last.is_none());

    {
        let _a = store.lock("site-a").await;
        let snap = store.contention();
        assert_eq!(snap.held_by.expect("held").site, "site-a");
        assert_eq!(snap.acquisitions, 1, "the holder's own acquisition counts");
        assert!(
            snap.last.is_none(),
            "nothing has been released yet, so there is no previous holder",
        );
    }
    let snap = store.contention();
    assert!(snap.held_by.is_none(), "released");
    assert_eq!(snap.last.expect("remembered").0, "site-a");
    assert_eq!(snap.acquisitions, 1, "releasing is not an acquisition");

    {
        let _b = store.lock("site-b").await;
        let snap = store.contention();
        assert_eq!(snap.held_by.expect("held").site, "site-b");
        assert_eq!(
            snap.last.expect("remembered").0,
            "site-a",
            "the previous holder is the one before the current, not the current",
        );
        assert_eq!(snap.acquisitions, 2);
    }
}

/// The concurrent half of the snapshot-coherence pin: genuinely impossible
/// pairings, hammered.
///
/// Split from [`a_contention_snapshot_never_mixes_two_states`]'s
/// deterministic transition checks purely for the line-count lint; the two
/// are one argument, and the doc comment there carries it.
#[tokio::test(flavor = "multi_thread", worker_threads = 4)]
async fn a_contention_snapshot_survives_concurrent_hammering() {
    let store = Arc::new(DocumentStore::default());
    //
    // Every acquisition uses a site name used exactly once, ever. A site can
    // then never be both the current holder and the most recent previous
    // holder in any real state — that pairing requires reading `holder`
    // before a release and `last` after it, which is precisely the tear.
    //
    // The obvious version of this test (a fixed set of tags) does not work,
    // and quietly passes against a deliberately-torn `contention`: a task
    // that releases and immediately re-acquires is *legitimately* both the
    // holder and the previous holder, so the pairing proves nothing. The
    // uniqueness is what makes it proof.
    let stop = Arc::new(std::sync::atomic::AtomicBool::new(false));
    let next_tag = Arc::new(std::sync::atomic::AtomicU64::new(0));
    let hammers: Vec<_> = (0..3)
        .map(|_| {
            let store = Arc::clone(&store);
            let stop = Arc::clone(&stop);
            let next_tag = Arc::clone(&next_tag);
            tokio::spawn(async move {
                while !stop.load(std::sync::atomic::Ordering::Relaxed) {
                    let n = next_tag.fetch_add(1, std::sync::atomic::Ordering::Relaxed);
                    // `&'static str` per acquisition. Leaked deliberately and
                    // bounded by the loop below; a few thousand short strings.
                    let site: &'static str = Box::leak(format!("hammer-{n}").into_boxed_str());
                    let held = store.lock(site).await;
                    for _ in 0..32 {
                        crate::rt::yield_now().await;
                    }
                    drop(held);
                    crate::rt::yield_now().await;
                }
            })
        })
        .collect();

    // Do not start the synchronous sampling loop until the real hammer
    // workers are demonstrably running. They keep acquiring and releasing
    // on the other runtime threads while sampling, preserving the
    // concurrent-transition proof without depending on initial scheduling.
    while store.contention().acquisitions < 100 {
        crate::rt::yield_now().await;
    }
    let mut previous = store.contention().acquisitions;
    let mut seen_both = 0_u32;
    for _ in 0..100_000 {
        let snap = store.contention();
        assert!(
            snap.acquisitions >= previous,
            "the acquisition count went backwards",
        );
        previous = snap.acquisitions;
        if let (Some(held), Some((last_site, _, _))) = (snap.held_by, snap.last) {
            seen_both += 1;
            assert_ne!(
                held.site, last_site,
                "this snapshot names a site as both the current holder and \
                     the previous one. Every acquisition uses a unique tag, so no \
                     real state can look like this — the fields were read at \
                     different moments, and a stall line built from them would \
                     name one task while describing another",
            );
            assert!(
                snap.acquisitions > 0,
                "a snapshot showing a holder must show its acquisition too",
            );
        }
    }

    stop.store(true, std::sync::atomic::Ordering::Relaxed);
    for h in hammers {
        let _ = h.await;
    }
    assert!(
        seen_both > 0,
        "the hammer never caught the map held with a previous holder \
             recorded, so the concurrent half proved nothing",
    );
}

/// A barrier that catches up *during* the sample window must not be
/// reported, and must not burn the rate limiter's slot.
///
/// The reporter sleeps for `DOCUMENTS_CONTENTION_SAMPLE_GAP` between its
/// two contention samples, which reopens the same race the entry check
/// closes: the stalled edit can land while it sleeps. Announcing a
/// permanent wedge that
/// is already over is bad on its own; recording that position in the rate
/// limiter is worse, because it would suppress the next *genuine* stall
/// there.
#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
async fn a_barrier_that_catches_up_during_the_sample_window_is_not_reported() {
    let backend = Arc::new(test_backend());
    let uri = Uri::from_str("file:///w/caught-up-midsample.tcl").unwrap();

    // A genuinely held turn, so the reporter gets past its entry check.
    let ticket = backend.edit_order.take_ticket("didOpen", &uri);
    let turn = backend.edit_order.wait_turn(ticket).await;
    let queued = backend.edit_order.take_ticket("didChange", &uri);
    let target = backend.edit_order.settle_target();

    let reporter = {
        let backend = Arc::clone(&backend);
        tokio::spawn(async move { backend.report_edit_barrier_stall(target).await })
    };

    // Let the reporter reach its sleep, then let the barrier catch up while
    // it is still in there.
    crate::rt::sleep(DOCUMENTS_CONTENTION_SAMPLE_GAP / 5).await;
    drop(turn);
    drop(queued);

    crate::rt::timeout(std::time::Duration::from_secs(5), reporter)
        .await
        .expect("the reporter must not hang")
        .expect("the reporter task must not panic");

    assert_eq!(
        backend
            .edit_barrier_stall_reported
            .load(std::sync::atomic::Ordering::Acquire),
        u64::MAX,
        "an edit that landed during the sample window must leave the rate \
             limiter untouched — recording it would suppress the next real stall \
             at this position (#1664's lesson, reopened by the sample sleep and \
             closed again here)",
    );
}

/// The stall line's workspace-index clause names the holder, its phase,
/// and its queue.
#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
async fn the_workspace_index_clause_names_holders_phases_and_waiters() {
    let lock = Arc::new(TrackedRwLock::new("workspace_index", 0_u32));
    assert_eq!(
        lock.contention(),
        "workspace_index: free; never written; never read; no queued waiters",
    );

    let writer = lock.write().await;
    writer.retag("publish_diagnostics_result: replace_document");
    let clause = lock.contention();
    assert!(
        clause.contains("held for write by ")
            && clause.contains("`publish_diagnostics_result: replace_document`")
            && clause.contains("lib.rs:"),
        "a writer is named with its site and phase: {clause}",
    );

    let (queued_tx, queued_rx) = tokio::sync::oneshot::channel();
    let reader = crate::rt::spawn({
        let lock = Arc::clone(&lock);
        async move {
            let _ = queued_tx.send(());
            let guard = lock.read().await;
            guard.retag("test reader: holding");
            crate::rt::sleep(std::time::Duration::from_millis(200)).await;
            drop(guard);
        }
    });
    queued_rx.await.expect("the reader task runs");
    crate::rt::timeout(std::time::Duration::from_secs(5), async {
        while !lock.contention().contains("1 queued reader(s)") {
            crate::rt::yield_now().await;
        }
    })
    .await
    .expect("a parked reader must appear in the queue");

    drop(writer);
    crate::rt::timeout(std::time::Duration::from_secs(5), async {
        while !lock.contention().contains("`test reader: holding`") {
            crate::rt::yield_now().await;
        }
    })
    .await
    .expect("the reader must be recorded, with its phase, once it holds the lock");
    let clause = lock.contention();
    assert!(
        clause.contains("held for read by 1 reader(s)") && clause.contains("no queued waiters"),
        "a reader is counted and the queue is empty again: {clause}",
    );

    reader.await.expect("the reader task must not panic");
    let clause = lock.contention();
    assert!(
        clause.contains("free; last written by ")
            && clause.contains("released ")
            && clause.contains("last read by "),
        "a free lock still names its last writer and reader: {clause}",
    );
}

/// A stalled barrier report carries the index clause.
#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
async fn the_stall_report_names_the_workspace_index_holder() {
    let backend = Arc::new(test_backend());
    let uri = Uri::from_str("file:///w/index-holder.tcl").unwrap();
    let index = backend.workspace_index.write().await;
    index.retag("test: holding the index");

    let ticket = backend.edit_order.take_ticket("didClose", &uri);
    let _turn = backend.edit_order.wait_turn(ticket).await;
    let queued = backend.edit_order.take_ticket("didChange", &uri);
    let target = backend.edit_order.settle_target();
    crate::rt::timeout(
        std::time::Duration::from_secs(5),
        backend.report_edit_barrier_stall(target),
    )
    .await
    .expect("the reporter must return promptly rather than block");
    assert_ne!(
        backend
            .edit_barrier_stall_reported
            .load(std::sync::atomic::Ordering::Acquire),
        u64::MAX,
        "a genuinely held turn is reported",
    );
    let clause = backend.workspace_index.contention();
    assert!(
        clause.contains("held for write by") && clause.contains("`test: holding the index`"),
        "the clause the report embeds names the holder: {clause}",
    );
    drop(queued);
    drop(index);
}

/// A contended acquire must be visible, counted, woken-counted, and gone
/// when it is over.
///
/// This is the poll-discriminator's ground truth. A wedge shows a waiter
/// parked on a free map; the verdict the stall line
/// draws — wake lost, versus woken-but-never-polled — is only as good as
/// these counters. A waiter that did not register would be invisible; polls
/// that did not count would read as "never polled" (the parent-starvation
/// verdict) for a future being polled constantly; wakes that did not count
/// would read as "wake lost" (the extraordinary claim) for a wake that
/// arrived.
#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
async fn a_contended_map_acquire_reports_its_polls_and_wakes() {
    let store = Arc::new(DocumentStore::default());
    assert!(
        store.waiters().is_empty(),
        "no waiter exists before anything contends",
    );

    let held = store.lock("holder").await;
    assert!(
        store.waiters().is_empty(),
        "the fast path must not register a waiter — there is nothing \
             waiting, and a ghost entry would be accused by the next stall line",
    );

    let contender = {
        let store = Arc::clone(&store);
        tokio::spawn(async move {
            let _guard = store.lock("contender").await;
        })
    };

    // The contender parks. Its registration and at least one poll must be
    // visible while it waits.
    let parked = crate::rt::timeout(std::time::Duration::from_secs(5), async {
        loop {
            let waiters = store.waiters();
            if let [w] = waiters.as_slice()
                && w.site == "contender"
                && w.polls >= 1
            {
                return *w;
            }
            crate::rt::sleep(std::time::Duration::from_millis(5)).await;
        }
    })
    .await
    .expect("the parked contender must appear in the waiter registry");
    assert_eq!(
        parked.wakes, 0,
        "nothing has released the map, so no wake can have been recorded — \
             a phantom wake here would later disprove a real lost-wake verdict",
    );

    // Release. The fair mutex hands the lock to the queued contender, which
    // requires waking it — that wake must be counted before the waiter
    // finishes and deregisters. We can't sample the registry after the
    // handoff (the entry is gone, correctly), so sample the Arc the
    // registry shared: grab it while the waiter is still parked.
    let telemetry = {
        let tracking = store.tracking();
        Arc::clone(&tracking.waiters[0])
    };
    drop(held);
    crate::rt::timeout(std::time::Duration::from_secs(5), contender)
        .await
        .expect("the contender must acquire once the map is released")
        .expect("the contender task must not panic");

    assert!(
        store.waiters().is_empty(),
        "a completed acquire must deregister — a stale entry would be \
             accused by every later stall line",
    );
    let t = telemetry
        .lock()
        .unwrap_or_else(std::sync::PoisonError::into_inner);
    assert!(
        t.wakes >= 1,
        "releasing the map woke the queued waiter, and that wake must be \
             counted: with it missed, a stall line would report 'never woken' — \
             the lost-wake verdict — about a wake that demonstrably arrived",
    );
    assert!(
        t.polls >= 2,
        "the wake leads to a final successful poll, which must be counted \
             like the first",
    );
}

/// A waiter cancelled mid-wait must deregister.
///
/// Handler futures are dropped wholesale (a closed connection, an aborted
/// request), taking any parked acquire with them. The registration is
/// removed by a drop guard precisely so that this case cannot leave a ghost
/// waiter — an entry that would sit in the registry forever and be accused
/// by every subsequent stall line as a decades-old parked task.
#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
async fn a_cancelled_map_acquire_leaves_no_ghost_waiter() {
    let store = Arc::new(DocumentStore::default());
    let held = store.lock("holder").await;

    {
        let mut acquire = Box::pin(store.lock("doomed"));
        assert!(
            crate::rt::timeout(std::time::Duration::from_millis(50), &mut acquire)
                .await
                .is_err(),
            "the acquire must park behind the held map, or dropping it \
                 proves nothing",
        );
        assert_eq!(
            store.waiters().len(),
            1,
            "the parked acquire must be registered",
        );
        // `acquire` drops here — cancellation.
    }

    assert!(
        store.waiters().is_empty(),
        "a cancelled acquire must deregister its waiter — the drop guard is \
             the only thing between this and a permanent ghost entry (#1657)",
    );
    drop(held);
}

/// The waiter clause must state the right verdict for each telemetry shape.
///
/// The whole point of the shim is that a human reads the verdict off the
/// stall line, so the mapping from counters to words is behaviour, not
/// cosmetics: woken-after-last-poll must read as a driving problem,
/// and never-woken as a lost wake, without guessing which scheduler layer
/// failed to drive it.
#[test]
fn the_waiter_clause_states_the_verdict() {
    let base = WaiterSnapshot {
        telemetry_id: 1,
        site: "did_open",
        parked_for: std::time::Duration::from_secs(18),
        polls: 1,
        since_last_poll: std::time::Duration::from_secs(18),
        wakes: 0,
        since_last_wake: None,
        #[cfg(not(target_family = "wasm"))]
        task_id: None,
    };

    let never_woken = describe_documents_waiters(&[base], false);
    assert!(
        never_woken.contains("lost or never sent"),
        "a never-woken waiter is the lost-wake verdict: {never_woken}",
    );

    let woken_not_polled = describe_documents_waiters(
        &[WaiterSnapshot {
            wakes: 1,
            since_last_wake: Some(std::time::Duration::from_secs(9)),
            ..base
        }],
        false,
    );
    assert!(
        woken_not_polled.contains("never polled again"),
        "a wake newer than the last poll is the not-being-driven verdict: \
             {woken_not_polled}",
    );

    let nobody = describe_documents_waiters(&[], false);
    assert!(
        nobody.contains("No task is in the map's contended-acquire path"),
        "an empty registry must say so rather than staying silent: {nobody}",
    );

    // Behind a HELD map, zero wakes is the expected state, not evidence:
    // the holder has not released, so no wake was ever due. The run-1
    // poll-shim capture printed the lost-wake wording for four such
    // victims, which invited suspicion of the mutex for waiters that were
    // merely queued behind a stuck holder.
    let held_victim = describe_documents_waiters(&[base], true);
    assert!(
        held_victim.contains("a victim of the holder above"),
        "a waiter behind a held map must be framed as a victim: {held_victim}",
    );
    assert!(
        !held_victim.contains("lost or never sent"),
        "a waiter behind a held map must not be given the lost-wake verdict: \
             {held_victim}",
    );
}

/// The nudge triggers only for a stale waiter on a free map.
///
/// The watchdog acts on production state, so a wrong predicate is either a
/// evidence probe that never fires (the wedge stays unobserved) or one that
/// fires on healthy states (pokes and log noise on every long but
/// legitimate hold). The trigger is pinned against its nearest legitimate
/// neighbour.
#[test]
fn the_nudge_fires_on_impossible_shapes_only() {
    let held = HeldFor {
        site: "deliver_if_current",
        held: std::time::Duration::from_secs(5),
        in_phase: std::time::Duration::from_secs(5),
        longest_phase: None,
    };
    let waiter = |parked_ms: u64| WaiterSnapshot {
        telemetry_id: 2,
        site: "did_open",
        parked_for: std::time::Duration::from_millis(parked_ms),
        polls: 1,
        since_last_poll: std::time::Duration::from_millis(parked_ms),
        wakes: 0,
        since_last_wake: None,
        #[cfg(not(target_family = "wasm"))]
        task_id: None,
    };
    let contention = |held_by: Option<HeldFor>| DocumentsContention {
        held_by,
        last: None,
        acquisitions: 1,
    };

    // A stale waiter on a FREE map. Its neighbour — the same
    // waiter behind a HELD map — is every long but legitimate hold, and
    // must not nudge.
    assert_eq!(
        nudge_reason(&contention(None), &[waiter(4100)]),
        Some(NudgeTarget {
            telemetry_id: 2,
            polls: 1,
        }),
        "a fair mutex hands over immediately; a stale waiter on a free map \
             was never resumed",
    );
    assert_eq!(
        nudge_reason(&contention(Some(held)), &[waiter(60_000)]),
        None,
        "a waiter behind a held map is a victim of the holder, however \
             stale — nudging would fire on every long legitimate hold (#1678)",
    );
    assert_eq!(
        nudge_reason(&contention(None), &[waiter(500)]),
        None,
        "a fresh waiter on a free map is an ordinary handoff in progress",
    );
    assert_eq!(
        nudge_reason(&contention(None), &[]),
        None,
        "an idle map never nudges",
    );
}

/// The watchdog step nudges a wedged-looking store and leaves a healthy
/// one alone — driven directly, as the thread loop drives it.
#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
async fn the_watchdog_step_nudges_only_a_wedged_store() {
    let store = Arc::new(DocumentStore::default());
    let handle = tokio::runtime::Handle::current();
    let mut log = Vec::new();

    // Healthy: idle store, no nudge, nothing logged.
    assert!(
        !unpark_watchdog_step(&store, &handle, &mut log),
        "an idle store must not be nudged",
    );
    assert!(log.is_empty(), "no action, no log line");

    // Wedged-looking: a waiter registration on a free map, backdated past
    // the evidence threshold. There is deliberately no acquire future to
    // resume, so the outcome must report that the external spawns did not
    // recover the exact target.
    let old = crate::rt::Instant::now() - NUDGE_WAITER_THRESHOLD * 2;
    let telemetry = Arc::new(std::sync::Mutex::new(WaiterTelemetry {
        site: "did_open",
        parked_since: old,
        polls: 1,
        last_poll: old,
        wakes: 0,
        last_wake: None,
        #[cfg(not(target_family = "wasm"))]
        task_id: None,
    }));
    store.tracking().waiters.push(telemetry);

    let nudges_before = UNPARK_NUDGES.load(std::sync::atomic::Ordering::Relaxed);
    // Run the step off the runtime, as the real watchdog thread does — it
    // sleeps 500ms inline, which must not block a worker in this test.
    let stepped = {
        let store = Arc::clone(&store);
        let handle = handle.clone();
        tokio::task::spawn_blocking(move || {
            let mut log = Vec::new();
            let stepped = unpark_watchdog_step(&store, &handle, &mut log);
            (stepped, log)
        })
        .await
        .expect("watchdog step must not panic")
    };
    assert!(stepped.0, "a stale waiter on a free map must be nudged");
    let logged = String::from_utf8(stepped.1).expect("log is utf8");
    assert!(
        logged.contains("[nudge] waiter parked on a free map"),
        "the nudge must log its reason and evidence: {logged}",
    );
    assert!(
        logged.contains("[nudge] outcome: STILL WEDGED"),
        "the nudge must log its outcome — the outcome line is the built-in \
             falsifier for the lost-unpark frame: {logged}",
    );
    assert_eq!(
        UNPARK_NUDGES.load(std::sync::atomic::Ordering::Relaxed),
        nudges_before + 1,
        "each nudge counts",
    );
}

/// Wait for the single document-sync handler under test to draw its
/// `EditOrder` ticket **and** hand it on, or give up.
///
/// `edits_settled` alone cannot express this: called before the handler has
/// drawn its ticket it returns immediately and proves nothing, so the wait
/// is on the counters directly.
async fn one_edit_turn_released(backend: &Backend) -> bool {
    use std::sync::atomic::Ordering;
    crate::rt::timeout(std::time::Duration::from_secs(5), async {
        loop {
            let order = &backend.edit_order;
            if order.next_ticket.load(Ordering::Acquire) == 1
                && order.now_serving.load(Ordering::Acquire) == 1
            {
                return;
            }
            crate::rt::sleep(std::time::Duration::from_millis(5)).await;
        }
    })
    .await
    .is_ok()
}

/// `did_close` must hand its `EditOrder` turn on as soon as the
/// ordered mutations are applied, rather than holding it across the disk
/// reindex and the closed-file republish.  The ticket is a *global*
/// barrier — every request handler awaits `edits_settled` and the next
/// `did_change` waits for the ticket itself — so a close that keeps it
/// across that tail freezes hover / completion / semantic tokens in every
/// open document for as long as the close takes.
///
/// The `rehoming_gate` stands in for the tail's cost: the ordered mutations
/// (the documents map, the index entry) never take it, and the reindex takes
/// it before any other tail lock. Holding that first lock pins the close
/// without letting the tail hold `documents` while this test inspects it.
/// Using the later `db` lock here made the test itself racy: the reindex
/// could win `documents`, block on `db`, and deadlock the inspection below.
#[tokio::test(flavor = "multi_thread", worker_threads = 4)]
async fn did_close_hands_its_edit_turn_on_before_the_reindex_tail() {
    let backend = Arc::new(test_backend());
    let root = unique_scratch_dir("close-off-ticket");
    let on_disk = root.join("closing.tcl");
    std::fs::write(&on_disk, "proc foo {} {}\n").unwrap();
    let uri = Uri::from_file_path(&on_disk).unwrap();
    register(&backend, &uri, "proc foo {} {}\n").await;

    let rehoming_held = backend.rehoming_gate.lock().await;
    let closing = crate::rt::spawn({
        let backend = Arc::clone(&backend);
        let uri = uri.clone();
        async move {
            backend
                .did_close(DidCloseTextDocumentParams {
                    text_document: TextDocumentIdentifier { uri },
                })
                .await;
        }
    });

    assert!(
        one_edit_turn_released(&backend).await,
        "did_close must release its turn before the reindex, which cannot \
             run while the rehoming gate is held",
    );
    assert!(
        !backend.documents.lock("test").await.contains_key(&uri),
        "the mutations the ticket covers must already be applied",
    );
    assert!(
        !backend.closed_diag_gen.lock().await.contains_key(&uri),
        "the closed republish is the tail; it must still be pending here",
    );

    drop(rehoming_held);
    crate::rt::timeout(std::time::Duration::from_secs(30), closing)
        .await
        .expect("the close must finish once its tail can take the rehoming gate")
        .expect("did_close panicked");
    assert!(
        backend.closed_diag_gen.lock().await.contains_key(&uri),
        "the closed republish still lands, ordered after the mutations",
    );
    std::fs::remove_dir_all(&root).ok();
}

/// The edit side: `did_change` must hand its turn on once the splice
/// and the salsa source are committed — not hold it across the diagnostics
/// scheduling and the whole-source `detect_dialect` re-scan.
///
/// `diag_slots` stands in for that tail here: the ordered mutations never
/// take it and `schedule_diagnostics` takes it first thing, so a held
/// `diag_slots` lock pins the handler in its tail.
#[tokio::test(flavor = "multi_thread", worker_threads = 4)]
async fn did_change_hands_its_edit_turn_on_before_the_scheduling_tail() {
    use tower_lsp_server::ls_types::{
        TextDocumentContentChangeEvent, VersionedTextDocumentIdentifier,
    };
    let backend = Arc::new(test_backend());
    let uri = Uri::from_str("file:///w/edited.tcl").unwrap();
    register(&backend, &uri, "set x 1\n").await;

    let slots_held = backend.diag_slots.lock().await;
    let editing = crate::rt::spawn({
        let backend = Arc::clone(&backend);
        let uri = uri.clone();
        async move {
            backend
                .did_change(DidChangeTextDocumentParams {
                    text_document: VersionedTextDocumentIdentifier { uri, version: 2 },
                    content_changes: vec![TextDocumentContentChangeEvent {
                        range: None,
                        range_length: None,
                        text: "set x 2\n".to_owned(),
                    }],
                })
                .await;
        }
    });

    assert!(
        one_edit_turn_released(&backend).await,
        "did_change must release its turn before scheduling diagnostics",
    );
    assert_eq!(
        backend
            .documents
            .lock("test")
            .await
            .get(&uri)
            .map(|doc| doc.text.clone())
            .as_deref(),
        Some("set x 2\n"),
        "the splice the ticket covers must already be committed",
    );

    drop(slots_held);
    crate::rt::timeout(std::time::Duration::from_secs(30), editing)
        .await
        .expect("the edit must finish once its tail can take the diag_slots lock")
        .expect("did_change panicked");
}

/// An edit that lands *between* a config apply and the reload's own
/// `reschedule_all_open_documents` must analyse under the config that has
/// been applied, not the one its slot cached before the apply.
///
/// That window is real and observable: `run_config_reload` applies the
/// switches first (which is the instant `tcl-lsp.getEffectiveConfig` starts
/// reporting them), then walks the disk for `SpecTcl` packs, and only then
/// reschedules.  A client that treats the command as the settle signal and
/// then types lands inside it — and without the epoch stamp, that keystroke
/// reuses inputs resolved before the apply, so a just-disabled optimiser
/// still emitted its O-codes on that publish.
///
/// Pinned without racing the debounce: the worker's first act after the
/// debounce is `capture_job`, which takes `documents`, so holding that lock
/// parks it there.  It cannot retire the slot from there (retirement needs a
/// *clean* slot, and it has already taken the dirty flag), so `latest_inputs`
/// stays observable for the whole test.
#[tokio::test(flavor = "multi_thread", worker_threads = 4)]
async fn an_edit_during_a_config_apply_re_resolves_its_diagnostics_inputs() {
    let backend = test_backend();
    let uri = Uri::from_str("file:///w/epoch.tcl").unwrap();
    register(&backend, &uri, "set x 1\n").await;

    let optimiser_in_slot = async || -> bool {
        backend
            .diag_slots
            .lock()
            .await
            .get(&uri)
            .expect("the slot must still exist")
            .latest_inputs
            .as_ref()
            .expect("a scheduled slot carries its inputs")
            .policy_layers
            .builder()
            .build()
            .optimiser
            .enabled
    };

    // The first edit primes the cache, exactly as a keystroke does.
    backend
        .schedule_diagnostics(uri.clone(), "tcl8.6".to_owned())
        .await;
    let docs_held = backend.documents.lock("test").await;
    assert!(
        optimiser_in_slot().await,
        "the optimiser starts enabled, so the primed inputs must say so",
    );

    // The apply half of `run_config_reload`: the switch is live and the
    // command already reports it, but no reschedule has run yet.
    backend
        .apply_global_config(&serde_json::json!({"optimiser": {"enabled": false}}))
        .await
        .unwrap();
    assert!(
        !*backend.optimiser_enabled.lock().await,
        "the apply must have landed, or this test proves nothing",
    );

    // …and the user types.  The edit path asks for no refresh; the epoch
    // stamp is the only thing that can make this correct.
    backend
        .schedule_diagnostics(uri.clone(), "tcl8.6".to_owned())
        .await;
    assert!(
        !optimiser_in_slot().await,
        "an edit arriving after a config apply must re-resolve its analyser \
             inputs — reusing the pre-apply cache republishes the O-codes the \
             user just disabled (#1651)",
    );
    drop(docs_held);
}

/// The epoch stamp is only worth anything if it describes a snapshot that
/// saw *one* configuration. `diag_inputs` is a long chain of awaits over a
/// dozen config mutexes, so an apply landing inside it produces a snapshot
/// that is half pre-change and half post-change; committing that — under
/// either epoch — puts that window straight back, because the worker
/// takes `latest_inputs` at drain time and never re-checks it.
///
/// Interleaved deterministically rather than by luck. The resolve is parked
/// on `spec_packs`, which `registry_for_dialect` takes *after*
/// `resolved_analysis_settings` has already read the optimiser switch — so
/// the parked task is holding a snapshot that says "enabled" while the test
/// flips it to disabled underneath. The park is observable because the
/// URI is fresh: `schedule_diagnostics_impl`'s first act is a
/// `slots.entry(uri).or_default()` peek, so the slot appearing in the map
/// proves the task is past it and inside the resolve, and it cannot leave
/// the resolve while the test holds `spec_packs`.
///
/// The flip is made directly rather than through `apply_global_config`
/// because that path takes `spec_packs` itself (via `sync_db_config`) and
/// would deadlock against the park. The wiring from a real apply to the
/// invalidation is pinned by
/// `an_edit_during_a_config_apply_re_resolves_its_diagnostics_inputs`; what
/// is under test here is what `schedule_diagnostics_impl` does with an
/// epoch that moves mid-resolve.
#[tokio::test(flavor = "multi_thread", worker_threads = 4)]
async fn a_snapshot_resolved_across_a_config_change_is_discarded_not_committed() {
    let backend = Arc::new(test_backend());
    let uri = Uri::from_str("file:///w/mid-resolve.tcl").unwrap();
    register(&backend, &uri, "set x 1\n").await;

    // Park the diagnostics worker, so it cannot retire the slot out from
    // under the assertions.
    let docs_held = backend.documents.lock("test").await;
    // Park the resolve, after the optimiser switch has been read.
    let packs_held = backend.spec_packs.lock().await;

    let scheduling = crate::rt::spawn({
        let backend = Arc::clone(&backend);
        let uri = uri.clone();
        async move {
            backend.schedule_diagnostics(uri, "tcl8.6".to_owned()).await;
        }
    });

    assert!(
        wait_for(|| async { backend.diag_slots.lock().await.contains_key(&uri) }).await,
        "the scheduler must reach its slot peek, or nothing is being interleaved",
    );

    // The apply half: the switch is now off and the epoch has moved, while
    // the parked resolve still holds a snapshot that says it is on.
    backend.policy_layers.lock().await.editor =
        serde_json::json!({ "optimiser": { "enabled": false } });
    backend.invalidate_diag_inputs();
    let epoch_after_apply = backend.diag_inputs_epoch();

    drop(packs_held);
    crate::rt::timeout(std::time::Duration::from_secs(30), scheduling)
        .await
        .expect("the schedule must finish once the pack lock is free")
        .expect("schedule_diagnostics panicked");

    let slots = backend.diag_slots.lock().await;
    let slot = slots.get(&uri).expect("the slot must still exist");
    let inputs = slot
        .latest_inputs
        .as_ref()
        .expect("a scheduled slot carries its inputs");
    assert!(
        !inputs.policy_layers.builder().build().optimiser.enabled,
        "a snapshot read across the apply must be discarded and re-read, not \
             committed — publishing it republishes the O-codes the user just disabled",
    );
    assert_eq!(
        slot.inputs_epoch, epoch_after_apply,
        "the committed stamp must name the configuration the snapshot actually saw",
    );
    drop(slots);
    drop(docs_held);
}

/// Two schedules for one URI can be in flight at once and nothing makes
/// them finish in the order they started, so a resolve that read epoch N
/// can land *after* one that read N+1 and has already committed. Letting it
/// win would replace a current snapshot with an older one and stamp the slot
/// backwards — and the reuse check would then call the older one current,
/// which is worse than having no stamp at all.
///
/// The faster commit is installed directly. That is not a shortcut around a
/// race: `(latest_inputs, inputs_epoch)` at a later epoch than the one the
/// next resolve will read *is* the state that interleaving leaves behind,
/// and building it outright is what makes the assertion deterministic
/// instead of dependent on which task the runtime happens to poll first.
#[tokio::test(flavor = "multi_thread", worker_threads = 4)]
async fn a_late_resolve_cannot_stamp_the_slot_backwards() {
    let backend = test_backend();
    let uri = Uri::from_str("file:///w/late-resolve.tcl").unwrap();
    register(&backend, &uri, "set x 1\n").await;
    let docs_held = backend.documents.lock("test").await;

    // What the faster scheduler committed: the optimiser off, under an
    // epoch later than anything a resolve starting now could read.
    backend.policy_layers.lock().await.editor =
        serde_json::json!({ "optimiser": { "enabled": false } });
    backend.invalidate_diag_inputs();
    backend
        .schedule_diagnostics(uri.clone(), "tcl8.6".to_owned())
        .await;
    let newer_epoch = backend.diag_inputs_epoch() + 5;
    {
        let mut slots = backend.diag_slots.lock().await;
        let slot = slots.get_mut(&uri).expect("the slot must exist");
        assert!(
            !slot
                .latest_inputs
                .as_ref()
                .expect("inputs")
                .policy_layers
                .builder()
                .build()
                .optimiser
                .enabled,
            "the newer snapshot must start out with the optimiser off",
        );
        slot.inputs_epoch = newer_epoch;
    }

    // The slower resolve now lands. It reads the configuration as it stands
    // — which the test moves back to "enabled", so an overwrite is visible —
    // and stamps it with today's epoch, which is behind the slot's.
    backend.policy_layers.lock().await.editor =
        serde_json::json!({ "optimiser": { "enabled": true } });
    backend
        .schedule_diagnostics(uri.clone(), "tcl8.6".to_owned())
        .await;

    let slots = backend.diag_slots.lock().await;
    let slot = slots.get(&uri).expect("the slot must still exist");
    assert!(
        !slot
            .latest_inputs
            .as_ref()
            .expect("inputs")
            .policy_layers
            .builder()
            .build()
            .optimiser
            .enabled,
        "a resolve stamped behind the slot must not overwrite the newer snapshot",
    );
    assert_eq!(
        slot.inputs_epoch, newer_epoch,
        "and it must not stamp the slot backwards, which would make the reuse \
             check call the older snapshot current",
    );
    drop(slots);
    drop(docs_held);
}

/// An edit must not evict the edited document from the workspace index.
/// `publish_diagnostics_result` re-indexes it (remove + add) behind its own
/// `is_current` check, so a per-keystroke removal buys nothing but a window
/// in which the file contributes no procs, classes or call sites to any
/// cross-file query — on top of fourteen workspace-wide `retain` passes
/// per edit.
///
/// Pinned the same way as the turn-handover test above: `diag_slots` is
/// held, so the handler is parked in its tail and no publish can have run by the
/// time the assertion reads the index.
#[tokio::test(flavor = "multi_thread", worker_threads = 4)]
async fn did_change_does_not_evict_the_document_from_the_workspace_index() {
    use tower_lsp_server::ls_types::{
        TextDocumentContentChangeEvent, VersionedTextDocumentIdentifier,
    };
    let backend = Arc::new(test_backend());
    let uri = Uri::from_str("file:///w/indexed.tcl").unwrap();
    register(&backend, &uri, "proc published {} {}\n").await;

    let slots_held = backend.diag_slots.lock().await;
    let editing = crate::rt::spawn({
        let backend = Arc::clone(&backend);
        let uri = uri.clone();
        async move {
            backend
                .did_change(DidChangeTextDocumentParams {
                    text_document: VersionedTextDocumentIdentifier { uri, version: 2 },
                    content_changes: vec![TextDocumentContentChangeEvent {
                        range: None,
                        range_length: None,
                        text: "proc renamed {} {}\n".to_owned(),
                    }],
                })
                .await;
        }
    });

    assert!(
        one_edit_turn_released(&backend).await,
        "did_change must release its turn before scheduling diagnostics",
    );
    assert!(
        backend
            .workspace_index
            .read()
            .await
            .procs()
            .any(|p| p.uri == uri.as_str() && p.name == "published"),
        "the last published analysis must still be indexed mid-edit",
    );

    drop(slots_held);
    crate::rt::timeout(std::time::Duration::from_secs(30), editing)
        .await
        .expect("the edit must finish once its tail can take the diag_slots lock")
        .expect("did_change panicked");
}

async fn register(backend: &Backend, uri: &Uri, src: &str) {
    backend.documents.lock("test").await.insert(
        uri.clone(),
        DocumentState::new(src.to_owned(), "tcl8.6".to_owned()),
    );
    backend
        .db_set_source(uri, src, "tcl8.6".to_owned())
        .await
        .expect("the fixture retains its actual checked SourceFile owner");
    let analysis = backend
        .analysis_for(uri, Arc::from(src), "tcl8.6".to_owned())
        .await
        .expect("the fixture analyses its actual current source and full input");
    backend
        .workspace_index
        .write()
        .await
        .add_document(uri.as_str(), &analysis);
}

/// `resolve_target_locations` reads each unique target
/// URI once rather than once per site. Correctness check: several sites
/// interleaved across two documents must all resolve, each against the
/// *right* document's source, and the result must keep the exact input
/// order (some callers, e.g. the code-lens click target, rely on
/// `resolve_target_locations`'s order matching `textDocument/references`'
/// own).
#[tokio::test]
async fn resolve_target_locations_groups_by_uri_and_preserves_site_order() {
    let backend = test_backend();
    let a = Uri::from_str("file:///a.tcl").unwrap();
    let b = Uri::from_str("file:///b.tcl").unwrap();
    // a.tcl: "aaa\nbbb\nccc\n" — three one-word lines.
    // b.tcl: "xxx\nyyy\n" — two one-word lines.
    register(&backend, &a, "aaa\nbbb\nccc\n").await;
    register(&backend, &b, "xxx\nyyy\n").await;
    let span_at = |line_start_byte: u32, len: u32| {
        tcl_lexer::Span::new(line_start_byte, line_start_byte + len)
    };
    // Interleaved: b, a, b, a, a — deliberately not grouped by URI, and
    // not in either document's own line order, so a naive "sort by URI"
    // implementation would be caught by the order assertion below.
    let targets = vec![
        (b.to_string(), span_at(4, 3)), // b.tcl line 1: "yyy"
        (a.to_string(), span_at(8, 3)), // a.tcl line 2: "ccc"
        (b.to_string(), span_at(0, 3)), // b.tcl line 0: "xxx"
        (a.to_string(), span_at(0, 3)), // a.tcl line 0: "aaa"
        (a.to_string(), span_at(4, 3)), // a.tcl line 1: "bbb"
    ];
    let locations = backend.resolve_target_locations(targets).await.unwrap();
    assert_eq!(locations.len(), 5, "{locations:?}");
    let got: Vec<(String, u32)> = locations
        .iter()
        .map(|l| (l.uri.to_string(), l.range.start.line))
        .collect();
    assert_eq!(
        got,
        vec![
            (b.to_string(), 1),
            (a.to_string(), 2),
            (b.to_string(), 0),
            (a.to_string(), 0),
            (a.to_string(), 1),
        ],
        "grouping by URI must not reorder the result",
    );
}

/// A target URI that fails to parse, or has no document, is dropped
/// without disturbing the other targets' resolution or order.
#[tokio::test]
async fn resolve_target_locations_drops_unresolvable_targets_and_keeps_the_rest() {
    let backend = test_backend();
    let a = Uri::from_str("file:///a.tcl").unwrap();
    register(&backend, &a, "aaa\nbbb\n").await;
    let targets = vec![
        ("not a uri".to_owned(), tcl_lexer::Span::new(0, 3)),
        (a.to_string(), tcl_lexer::Span::new(0, 3)),
        (
            "file:///never-opened-and-not-on-disk.tcl".to_owned(),
            tcl_lexer::Span::new(0, 3),
        ),
        (a.to_string(), tcl_lexer::Span::new(4, 7)),
    ];
    let locations = backend.resolve_target_locations(targets).await.unwrap();
    let got: Vec<u32> = locations.iter().map(|l| l.range.start.line).collect();
    assert_eq!(got, vec![0, 1], "{locations:?}");
}

#[tokio::test]
async fn cross_document_references_finds_sibling_call_sites() {
    let backend = test_backend();
    let lib = Uri::from_str("file:///lib.tcl").unwrap();
    let consumer = Uri::from_str("file:///consumer.tcl").unwrap();
    let lib_src = "proc helper {} {}\nhelper\n";
    register(&backend, &lib, lib_src).await;
    register(&backend, &consumer, "helper\nhelper\n").await;
    // From lib.tcl's `helper` declaration, cross-doc refs
    // are the two calls in consumer.tcl.
    let analysis = {
        let mut a = Analyser::new();
        a.analyse(lib_src, "tcl8.6").clone()
    };
    let cross = backend
        .cross_document_references(&lib, lib_src, &analysis, Position::new(0, 5), false)
        .await
        .unwrap();
    assert_eq!(cross.len(), 2, "{cross:?}");
    assert!(cross.iter().all(|l| l.uri == consumer));
}

/// The pure-consumer shape, reduced to a literal `source`: a file that
/// `source`s a sibling and then calls its procs bare. `a.tcl` sources
/// `b.tcl` (which declares `helper`) and calls `helper` twice itself;
/// `c.tcl` calls it once more. `a.tcl` has no local declaration of
/// `helper` to anchor `cross_document_references`'s exclusion of the
/// current document on, so without the workspace-resolved fallback both
/// of `a.tcl`'s own calls — including the one under the cursor — are
/// dropped entirely.
#[tokio::test]
async fn workspace_resolved_references_reaches_the_current_documents_own_calls() {
    let backend = test_backend();
    let a = Uri::from_str("file:///a.tcl").unwrap();
    let b = Uri::from_str("file:///b.tcl").unwrap();
    let c = Uri::from_str("file:///c.tcl").unwrap();
    let b_src = "proc helper {} {}\n";
    register(&backend, &b, b_src).await;
    let a_src = "source b.tcl\nhelper\nhelper\n";
    register(&backend, &a, a_src).await;
    register(&backend, &c, "helper\n").await;
    let analysis = {
        let mut an = Analyser::new();
        an.analyse(a_src, "tcl8.6").clone()
    };
    // Cursor on a.tcl's own first `helper` call (line 1).
    let refs = backend
        .workspace_resolved_references(&a, a_src, &analysis, Position::new(1, 3), true)
        .await
        .unwrap();
    let a_hits = refs.iter().filter(|l| l.uri == a).count();
    assert_eq!(
        a_hits, 2,
        "both of a.tcl's own calls must be reached, not just the sourced-in decl: {refs:?}"
    );
    assert!(
        refs.iter().any(|l| l.uri == b),
        "b.tcl's declaration must still be reached: {refs:?}"
    );
    assert!(
        refs.iter().any(|l| l.uri == c),
        "c.tcl's call must still be reached: {refs:?}"
    );
}

/// End-to-end analogue of the test above, through the real
/// `textDocument/references` handler — proving the handler picks the
/// workspace-resolved fallback automatically (no caller-side branching
/// needed) whenever the single-document pass finds nothing local to
/// anchor on.
#[tokio::test]
async fn references_handler_reaches_own_calls_in_a_pure_consumer_document() {
    let backend = test_backend();
    let a = Uri::from_str("file:///a2.tcl").unwrap();
    let b = Uri::from_str("file:///b2.tcl").unwrap();
    register(&backend, &b, "proc helper {} {}\n").await;
    let a_src = "source b2.tcl\nhelper\nhelper\n";
    register(&backend, &a, a_src).await;
    let params = ReferenceParams {
        text_document_position: TextDocumentPositionParams {
            text_document: TextDocumentIdentifier { uri: a.clone() },
            position: Position::new(1, 3), // on a.tcl's own first `helper` call
        },
        context: ReferenceContext {
            include_declaration: true,
        },
        work_done_progress_params: WorkDoneProgressParams::default(),
        partial_result_params: PartialResultParams::default(),
    };
    let refs = Box::pin(backend.references(params))
        .await
        .expect("ok")
        .expect("some references");
    let a_hits: Vec<_> = refs.iter().filter(|l| l.uri == a).collect();
    assert_eq!(
        a_hits.len(),
        2,
        "both of a.tcl's own calls must be reached: {refs:?}"
    );
    assert!(
        refs.iter().any(|l| l.uri == b),
        "b.tcl's declaration must still be reached: {refs:?}"
    );
}

/// A proc declared twice, verbatim, in the same document (plain Tcl's own
/// "last redefinition wins" semantics, tclsh 9.0 / 8.6-verified) — the
/// shape a real library writes when it declares one proc at two separate
/// line ranges.  Identifying "the symbol at cursor" only
/// via `all_procs.values().find(|p| covers(p.name_span))`, and
/// `all_procs` (keyed by qualified name) retains only the *winning*
/// declaration's span on a duplicate insert — so a cursor on the
/// *shadowed* (non-winning) declaration's own name token could never
/// match, silently dropping every cross-file caller from
/// find-references, and — far worse — from rename: applying that
/// incomplete `WorkspaceEdit` leaves a cross-file caller still bound
/// to the old name, which a second, dead definition (the very shadowed
/// declaration the rename was issued from) is still lying around to
/// silently satisfy, changing the program's behaviour with no error
/// surfaced anywhere.
#[tokio::test]
async fn cross_document_references_reach_caller_from_shadowed_duplicate_decl() {
    let backend = test_backend();
    let lib = Uri::from_str("file:///lib31_refs.tcl").unwrap();
    let consumer = Uri::from_str("file:///consumer31_refs.tcl").unwrap();
    let lib_src = "proc List2array {lst} { return ONE }\nproc List2array {lst} { return TWO }\n";
    register(&backend, &lib, lib_src).await;
    register(&backend, &consumer, "List2array x\n").await;
    let analysis = {
        let mut a = Analyser::new();
        a.analyse(lib_src, "tcl8.6").clone()
    };
    // Cursor on the SHADOWED (first, non-winning) declaration's own
    // name token (line 0, col 6 — `proc List2array`).
    let cross = backend
        .cross_document_references(&lib, lib_src, &analysis, Position::new(0, 6), false)
        .await
        .unwrap();
    assert_eq!(
        cross.len(),
        1,
        "cross-file call site in consumer.tcl must not be silently \
             dropped when querying from the shadowed declaration: {cross:?}"
    );
    assert!(cross.iter().all(|l| l.uri == consumer));
}

/// The same shape as
/// `cross_document_references_reach_caller_from_shadowed_duplicate_decl`,
/// but for rename — the more severe half: an LSP-presented "complete"
/// rename issued from the shadowed declaration must still rewrite the
/// cross-file caller, or accepting the edit silently resurrects the dead
/// first definition for that caller and changes real program output with
/// no error.
#[tokio::test]
async fn cross_document_rename_reaches_caller_from_shadowed_duplicate_decl() {
    let backend = test_backend();
    let lib = Uri::from_str("file:///lib31_rename.tcl").unwrap();
    let consumer = Uri::from_str("file:///consumer31_rename.tcl").unwrap();
    let lib_src = "proc List2array {lst} { return ONE }\nproc List2array {lst} { return TWO }\n";
    register(&backend, &lib, lib_src).await;
    register(&backend, &consumer, "List2array x\n").await;
    let analysis = {
        let mut a = Analyser::new();
        a.analyse(lib_src, "tcl8.6").clone()
    };
    let mut changes: std::collections::HashMap<Uri, Vec<TextEdit>> =
        std::collections::HashMap::new();
    // Cursor on the SHADOWED (first, non-winning) declaration.
    backend
        .add_cross_document_rename_edits(
            &lib,
            lib_src,
            &analysis,
            Position::new(0, 6),
            "ListToArray",
            &mut changes,
        )
        .await
        .unwrap();
    let consumer_edits = changes.get(&consumer).cloned().unwrap_or_default();
    assert_eq!(
        consumer_edits.len(),
        1,
        "the cross-file caller must be rewritten, or it stays bound \
             to the old name while the dead shadowed definition (also \
             renamed away) silently resurrects for it: {changes:?}"
    );
    assert_eq!(consumer_edits[0].new_text, "ListToArray");
}

/// The *nested, cross-namespace* self-redefinition: a
/// `proc ticklecharts::activate` whose body declares an unqualified
/// `proc activate`.
///
/// Distinct from the shape above (two verbatim-identical top-level
/// declarations in one namespace) in the half that matters: the inner
/// declaration is written *unqualified inside a qualified proc's body*,
/// so reaching the cross-file caller depends on namespace resolution, not
/// only on keeping every physical declaration's span.
///
/// Oracle, byte-identical on tclsh 9.0.4 and 8.6.16: running `main.tcl`
/// prints `activating for the first time` then `already activated`, and
/// probing the command table afterwards reports `::ticklecharts::activate`
/// present with no global `::activate` at all — the nested `proc`
/// redefines the *same* command in the enclosing namespace.
#[tokio::test]
async fn cross_document_references_reach_caller_from_nested_self_redefinition() {
    let backend = test_backend();
    let lib = Uri::from_str("file:///lib45_refs.tcl").unwrap();
    let consumer = Uri::from_str("file:///consumer45_refs.tcl").unwrap();
    let lib_src = "namespace eval ticklecharts {}\n\
                       proc ticklecharts::activate {bool} {\n\
                       \x20if {$bool} {\n\
                       \x20 proc activate {bool} {puts \"already activated\"}\n\
                       \x20 puts \"activating for the first time\"\n\
                       \x20}\n\
                       }\n";
    register(&backend, &lib, lib_src).await;
    register(
        &backend,
        &consumer,
        "ticklecharts::activate 1\nticklecharts::activate 1\n",
    )
    .await;
    let analysis = {
        let mut a = Analyser::new();
        a.analyse(lib_src, "tcl8.6").clone()
    };
    // Both physical declarations must answer the same cross-file set:
    // the OUTER header (line 1, on `activate` of `ticklecharts::activate`)
    // and the NESTED one (line 3, on the bare `activate`).
    for (line, character, which) in [(1u32, 20u32, "outer"), (3, 7, "nested")] {
        let cross = backend
            .cross_document_references(
                &lib,
                lib_src,
                &analysis,
                Position::new(line, character),
                false,
            )
            .await
            .unwrap();
        assert_eq!(
            cross.len(),
            2,
            "both cross-file callers must be reached from the {which} \
                 declaration: {cross:?}"
        );
        assert!(cross.iter().all(|l| l.uri == consumer), "{cross:?}");
    }
}

/// The rename half of the same shape — the severe one. An edit set that
/// drops the cross-file callers leaves them bound to the old name while
/// the *other* declaration of the very same command is still lying
/// around under it.
#[tokio::test]
async fn cross_document_rename_reaches_caller_from_nested_self_redefinition() {
    let backend = test_backend();
    let lib = Uri::from_str("file:///lib45_rename.tcl").unwrap();
    let consumer = Uri::from_str("file:///consumer45_rename.tcl").unwrap();
    let lib_src = "namespace eval ticklecharts {}\n\
                       proc ticklecharts::activate {bool} {\n\
                       \x20if {$bool} {\n\
                       \x20 proc activate {bool} {puts \"already activated\"}\n\
                       \x20}\n\
                       }\n";
    register(&backend, &lib, lib_src).await;
    register(
        &backend,
        &consumer,
        "ticklecharts::activate 1\nticklecharts::activate 1\n",
    )
    .await;
    let analysis = {
        let mut a = Analyser::new();
        a.analyse(lib_src, "tcl8.6").clone()
    };
    for (line, character, which) in [(1u32, 20u32, "outer"), (3, 7, "nested")] {
        let mut changes: std::collections::HashMap<Uri, Vec<TextEdit>> =
            std::collections::HashMap::new();
        backend
            .add_cross_document_rename_edits(
                &lib,
                lib_src,
                &analysis,
                Position::new(line, character),
                "enable",
                &mut changes,
            )
            .await
            .unwrap();
        let consumer_edits = changes.get(&consumer).cloned().unwrap_or_default();
        assert_eq!(
            consumer_edits.len(),
            2,
            "both cross-file callers must be rewritten from the {which} \
                 declaration: {changes:?}"
        );
        // The caller spells the command with its namespace qualifier, and
        // rename preserves that qualifier rather than flattening the call
        // to a bare name.
        assert!(
            consumer_edits
                .iter()
                .all(|e| e.new_text == "ticklecharts::enable"),
            "the qualifier must be preserved: {consumer_edits:?}"
        );
    }
}

/// Build an on-disk autoload library (`tclIndex` + defining file, like a
/// `TCLLIBPATH` entry) whose `Rbc_Wire` also calls `Rbc_ActiveLegend`
/// internally, and point the backend's package database at it.  Returns
/// the library file's URI.
async fn seed_autoload_library(backend: &Backend, tag: &str) -> Uri {
    let libdir = unique_scratch_dir(tag);
    std::fs::write(
        libdir.join("graph.tcl"),
        "proc Rbc_ActiveLegend {graph} {}\nproc Rbc_Wire {} { Rbc_ActiveLegend .g }\n",
    )
    .unwrap();
    std::fs::write(
        libdir.join("tclIndex"),
        "# Tcl autoload index file, version 2.0\n\
             set auto_index(Rbc_ActiveLegend) [list source [file join $dir graph.tcl]]\n\
             set auto_index(Rbc_Wire) [list source [file join $dir graph.tcl]]\n",
    )
    .unwrap();
    *backend.package_resolver.write().await = build_package_resolver(
        &vfs::NativeStore,
        &[],
        &[libdir
            .to_str()
            .expect("library path configuration requires UTF-8")
            .to_owned()],
        &[],
        WORKSPACE_SCAN_DIR_CAP,
    );
    Uri::from_file_path(libdir.join("graph.tcl")).expect("library uri")
}

/// The autoload tier merges the defining library file
/// into the workspace index, so cross-document **references** reach the
/// library declaration and the library's own internal call sites — not
/// just go-to-definition.
#[tokio::test]
async fn autoload_merge_makes_references_reach_the_library_m8() {
    let backend = test_backend();
    let lib_uri = seed_autoload_library(&backend, "autoload-refs").await;
    // The workspace document only *calls* the library command.
    let app = Uri::from_str("file:///app.tcl").unwrap();
    let app_src = "Rbc_ActiveLegend .g\n";
    register(&backend, &app, app_src).await;
    let analysis = {
        let mut a = Analyser::new();
        a.analyse(app_src, "tcl8.6").clone()
    };
    let refs = backend
        .cross_document_references(&app, app_src, &analysis, Position::new(0, 3), true)
        .await
        .unwrap();
    assert!(
        refs.iter()
            .any(|l| l.uri == lib_uri && l.range.start.line == 0),
        "declaration in the library file: {refs:?}"
    );
    assert!(
        refs.iter()
            .any(|l| l.uri == lib_uri && l.range.start.line == 1),
        "library-internal call site: {refs:?}"
    );
}

#[tokio::test]
async fn original_autoload_navigation_joins_current_source_declaration_identity() {
    let backend = test_backend();
    let lib_uri = seed_autoload_library(&backend, "original-autoload-navigation").await;
    let app = Uri::from_str("file:///original-autoload-app.tcl").unwrap();
    let source = "Rbc_ActiveLegend .g\n";
    register(&backend, &app, source).await;
    let document = backend.read_document(&app).await.unwrap().unwrap();
    let analysis = backend
        .analysis_for(&app, document.text.clone(), document.dialect)
        .await
        .unwrap();
    assert!(!analysis.allows_retained_logical_declaration_advice());
    let position = Position::new(0, 3);
    let locations = backend
        .autoload_definition(&app, source, position, &analysis)
        .await
        .unwrap();
    assert_eq!(locations.len(), 1, "{locations:?}");
    assert_eq!(locations[0].uri, lib_uri);
    assert_eq!(locations[0].range.start.line, 0);
    let hover = backend
        .cross_document_hover(&app, source, position, &analysis)
        .await
        .unwrap()
        .expect("current original library declaration hover");
    assert!(hover.value.contains("Rbc_ActiveLegend"), "{hover:?}");
    assert_eq!(
        backend
            .autoload_definition(&app, &format!("{source} "), position, &analysis)
            .await
            .unwrap(),
        [] as [tower_lsp_server::ls_types::Location; 0]
    );
    let mut missing = analysis.as_ref().clone();
    missing.resolved_input = None;
    assert_eq!(
        backend
            .autoload_definition(&app, source, position, &missing)
            .await
            .unwrap(),
        [] as [tower_lsp_server::ls_types::Location; 0]
    );
    assert!(
        backend
            .cross_document_hover(&app, source, position, &missing)
            .await
            .unwrap()
            .is_none()
    );
    assert_eq!(
        backend
            .autoload_definition(&app, source, Position::new(0, 17), &analysis)
            .await
            .unwrap(),
        [] as [tower_lsp_server::ls_types::Location; 0]
    );
}

#[tokio::test]
async fn native_bare_autoload_head_keeps_its_own_readonly_eligibility_and_source_currency() {
    for public in [true, false] {
        let backend = test_backend();
        let provider = seed_autoload_library(&backend, &format!("bare-autoload-{public}")).await;
        let provider_path = provider.to_file_path().unwrap().into_owned();
        std::fs::write(&provider_path, "proc Rbc_ActiveLegend {} {}\n").unwrap();
        let app: Uri = "file:///bare-autoload-caller.tcl".parse().unwrap();
        let source = "Rbc_ActiveLegend\n";
        register(&backend, &app, source).await;
        let document = backend.read_document(&app).await.unwrap().unwrap();
        let analysis = backend
            .analysis_for(&app, document.text.clone(), document.dialect.clone())
            .await
            .unwrap();
        let position = Position::new(0, 4);
        assert!(core_definition::original_autoload_request_at(source, &analysis, 0, 4).is_some());
        assert!(
            !backend
                .workspace_index
                .read()
                .await
                .contains_document(provider.as_str())
        );
        let locations = if public {
            let response = backend
                .goto_definition(
                    serde_json::from_value(serde_json::json!({
                        "textDocument":{"uri":app.as_str()}, "position":{"line":0,"character":4}
                    }))
                    .unwrap(),
                )
                .await
                .unwrap();
            match response {
                Some(GotoDefinitionResponse::Array(locations)) => locations,
                other => panic!("first bare public autoload response: {other:?}"),
            }
        } else {
            // The exact autoload owner independently proves head eligibility;
            // a declined generic geometry helper cannot erase that owner.
            backend
                .definition_workspace_fallback(
                    &app,
                    &document,
                    &analysis,
                    position,
                    (
                        backend.diag_inputs_epoch(),
                        backend.live_publication_uri_generation(&app),
                    ),
                    false,
                )
                .await
                .unwrap()
        };
        assert_eq!(locations.len(), 1);
        assert_eq!(locations[0].uri, provider);
        assert_eq!(locations[0].range.start.line, 0);
        if public {
            for _ in 0..2 {
                let response = backend
                    .goto_definition(
                        serde_json::from_value(serde_json::json!({
                            "textDocument":{"uri":app.as_str()}, "position":{"line":0,"character":4}
                        }))
                        .unwrap(),
                    )
                    .await
                    .unwrap();
                assert!(
                    matches!(response, Some(GotoDefinitionResponse::Array(ref targets))
                        if targets.len() == 1 && targets[0].uri == provider && targets[0].range.start.line == 0),
                    "repeated publication must preserve the current target: {response:?}"
                );
            }
        }

        assert!(
            core_definition::original_autoload_request_at("Rbc_ActiveLegend \n", &analysis, 0, 4)
                .is_none()
        );
        let mut missing = analysis.as_ref().clone();
        missing.resolved_input = None;
        assert!(core_definition::original_autoload_request_at(source, &missing, 0, 4).is_none());
        std::fs::write(&provider_path, "proc replaced_header {} {}\n").unwrap();
        assert!(
            backend
                .compute_definition(&app, position)
                .await
                .unwrap()
                .is_empty(),
            "a changed closed provider cannot reuse its former header"
        );
    }
}
#[tokio::test]
async fn library_publication_refuses_actual_configuration_and_factory_changes() {
    use salsa::Setter as _;

    for factory_change in [false, true] {
        let backend = test_backend();
        let uri = Uri::from_str("untitled:library-full-input").unwrap();
        register(&backend, &uri, "proc library_full_input {} {}\n").await;
        let snapshot = backend.read_document(&uri).await.unwrap().unwrap();
        let epoch = backend.diag_inputs_epoch();
        let generation = *backend.class_factory_generation.read().await;
        let receipt = backend
            .capture_workspace_symbol_analysis(&uri, &snapshot)
            .await
            .unwrap()
            .unwrap();
        if factory_change {
            let mut analyser = Analyser::new();
            let oracle = Arc::new(
                analyser
                    .analyse("oo::class create LibraryFactory {}", "tcl8.6")
                    .class_factories(),
            );
            let mut generation = backend.class_factory_generation.write().await;
            let mut db = backend.db.lock().await;
            let files = backend.db_files.lock().await;
            files[&uri]
                .set_workspace_class_factories(&mut *db)
                .to(Some(oracle));
            *generation = generation.saturating_add(1);
        } else {
            let config = backend.resolved_db_config(&uri).await;
            let mut db = backend.db.lock().await;
            config
                .set_extra_commands(&mut *db)
                .to(vec!["library_new_command".to_owned()]);
        }
        assert!(
            !backend
                .publish_checked_library_analyses(
                    &[(uri.clone(), snapshot, receipt)],
                    epoch,
                    generation
                )
                .await
                .unwrap()
        );
        assert!(
            !backend
                .autoloaded_library_uris
                .lock()
                .await
                .contains(uri.as_str())
        );
    }
}

#[tokio::test]
